cat > vendor/terminal_size/src/lib.rs <<'EOF'
//! Minimal reimplementation of terminal size detection used by clap's
//! `wrap_help` feature.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

fn size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(libc::STDOUT_FILENO)
        .or_else(|| size_of_fd(libc::STDERR_FILENO))
        .or_else(|| size_of_fd(libc::STDIN_FILENO))
}
EOF
cat > compile.sh <<'EOF'
#!/bin/bash
# Builds the miniserve reimplementation and places the binary at ./executable
set -e
cd "$(dirname "$0")"
export CARGO_NET_OFFLINE=true
cargo build --release --offline
cp target/release/miniserve ./executable
chmod +x ./executable
EOF
chmod +x compile.sh; cat > .gitignore <<'EOF'
/target
/executable
Cargo.lock.bak
EOF
echo done"}

