{"command":"mkdir -p /workspace/src; cat > /workspace/src/cli.rs <<'EOF'
//! Command line interface definition.

use clap::builder::{PossibleValue, PossibleValuesParser, TypedValueParser};
use clap::{value_parser, Arg, ArgAction, Command, ValueHint};
use std::net::IpAddr;
use std::path::PathBuf;

use crate::auth::{parse_auth, RequiredAuth};

pub const ABOUT: &str = "For when you really just want to serve some files over HTTP right now!";
pub const VERSION: &str = "0.32.0";
pub const AUTHORS: &str =
    "Sven-Hendrik Haase <svenstaro@gmail.com>, Boastful Squirrel <boastful.squirrel@gmail.com>";

/// Parsed header (name lowercased, value)
#[derive(Clone, Debug)]
pub struct HeaderPair {
    pub name: String,
    pub value: Vec<u8>,
}

#[derive(Debug)]
pub enum HeaderParseError {
    Name,
    Value,
    NewLine,
    TooMany,
}

impl std::fmt::Display for HeaderParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            HeaderParseError::Name => "invalid header name",
            HeaderParseError::Value => "invalid header value",
            HeaderParseError::NewLine => "invalid new line",
            HeaderParseError::TooMany => "too many headers",
        };
        f.write_str(s)
    }
}
impl std::error::Error for HeaderParseError {}

fn is_token(b: u8) -> bool {
    matches!(b, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~')
        || b.is_ascii_alphanumeric()
}

/// Emulates parsing of a single header line like httparse::parse_headers with
/// a one-element header buffer.
pub fn parse_header(src: &str) -> Result<Vec<HeaderPair>, HeaderParseError> {
    let buf = format!("{src}\n");
    let b = buf.as_bytes();
    let mut i = 0;
    let mut out: Vec<HeaderPair> = Vec::new();
    loop {
        if i >= b.len() {
            break; // partial
        }
        // end of headers?
        if b[i] == b'\r' {
            if i + 1 >= b.len() {
                break;
            }
            if b[i + 1] == b'\n' {
                break;
            }
            return Err(HeaderParseError::NewLine);
        }
        if b[i] == b'\n' {
            break;
        }
        if out.len() >= 1 {
            return Err(HeaderParseError::TooMany);
        }
        // name
        let start = i;
        while i < b.len() && is_token(b[i]) {
            i += 1;
        }
        if i >= b.len() {
            break;
        }
        if b[i] != b':' || i == start {
            return Err(HeaderParseError::Name);
        }
        let name = &buf[start..i];
        i += 1;
        // skip whitespace
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
        let vstart = i;
        let mut vend;
        loop {
            if i >= b.len() {
                // partial: value incomplete
                return Ok(out);
            }
            let c = b[i];
            if c == b'\r' {
                vend = i;
                if i + 1 >= b.len() {
                    return Ok(out);
                }
                if b[i + 1] != b'\n' {
                    return Err(HeaderParseError::Value);
                }
                i += 2;
                break;
            }
            if c == b'\n' {
                vend = i;
                i += 1;
                break;
            }
            if c == b'\t' || c == b' ' || (0x21..=0x7e).contains(&c) || c >= 0x80 {
                i += 1;
                continue;
            }
            return Err(HeaderParseError::Value);
        }
        while vend > vstart && (b[vend - 1] == b' ' || b[vend - 1] == b'\t') {
            vend -= 1;
        }
        out.push(HeaderPair { name: name.to_ascii_lowercase(), value: b[vstart..vend].to_vec() });
    }
    Ok(out)
}

pub fn parse_chmod(src: &str) -> Result<u32, std::num::ParseIntError> {
    u32::from_str_radix(src, 8)
}

fn sorting_method_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("name").help("Sort by name"),
        PossibleValue::new("size").help("Sort by size"),
        PossibleValue::new("date")
            .help("Sort by last modification date (natural sort: follows alphanumerical order)"),
    ]
}

fn sorting_order_values() -> Vec<PossibleValue> {
    vec![
        PossibleValue::new("asc").help("Ascending order"),
        PossibleValue::new("desc").help("Descending order"),
    ]
}

fn theme_values() -> PossibleValuesParser {
    PossibleValuesParser::new(["squirrel", "archlinux", "zenburn", "monokai"])
}

pub fn build_command() -> Command {
    Command::new("miniserve")
        .version(VERSION)
        .author(AUTHORS)
        .about(ABOUT)
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .env("MINISERVE_VERBOSE")
                .action(ArgAction::SetTrue)
                .help("Be verbose, includes emitting access logs"),
        )
        .arg(
            Arg::new("temp_upload_directory")
                .long("temp-directory")
                .value_name("TEMP_UPLOAD_DIRECTORY")
                .env("MINISERVER_TEMP_UPLOAD_DIRECTORY")
                .value_parser(value_parser!(PathBuf))
                .requires("allowed_upload_dir")
                .action(ArgAction::Set)
                .help("The path to where file uploads will be written to before being moved to their correct location. It's wise to make sure that this directory will be written to disk and not into memory")
                .long_help("The path to where file uploads will be written to before being moved to their correct location. It's wise to make sure that this directory will be written to disk and not into memory.\n\nThis value will only be used **IF** file uploading is enabled. If this option is not set, the operating system default temporary directory will be used."),
        )
        .arg(
            Arg::new("index")
                .long("index")
                .value_name("INDEX")
                .env("MINISERVE_INDEX")
                .value_parser(value_parser!(PathBuf))
                .action(ArgAction::Set)
                .help("The name of a directory index file to serve, like \"index.html\"")
                .long_help("The name of a directory index file to serve, like \"index.html\"\n\nNormally, when miniserve serves a directory, it creates a listing for that directory. However, if a directory contains this file, miniserve will serve that file instead."),
        )
        .arg(
            Arg::new("spa")
                .long("spa")
                .env("MINISERVE_SPA")
                .action(ArgAction::SetTrue)
                .requires("index")
                .help("Activate SPA (Single Page Application) mode")
                .long_help("Activate SPA (Single Page Application) mode\n\nThis will cause the file given by --index to be served for all non-existing file paths. In effect, this will serve the index file whenever a 404 would otherwise occur in order to allow the SPA router to handle the request instead."),
        )
        .arg(
            Arg::new("pretty_urls")
                .long("pretty-urls")
                .env("MINISERVE_PRETTY_URLS")
                .action(ArgAction::SetTrue)
                .help("Activate Pretty URLs mode")
                .long_help("Activate Pretty URLs mode\n\nThis will cause the server to serve the equivalent `.html` file indicated by the path.\n\n`/about` will try to find `about.html` and serve it."),
        )
        .arg(
            Arg::new("port")
                .short('p')
                .long("port")
                .value_name("PORT")
                .env("MINISERVE_PORT")
                .default_value("8080")
                .value_parser(value_parser!(u16))
                .action(ArgAction::Set)
                .help("Port to use"),
        )
        .arg(
            Arg::new("interfaces")
                .short('i')
                .long("interfaces")
                .value_name("INTERFACES")
                .env("MINISERVE_INTERFACE")
                .value_parser(value_parser!(IpAddr))
                .num_args(1)
                .action(ArgAction::Append)
                .help("Interface to listen on"),
        )
        .arg(
            Arg::new("auth")
                .short('a')
                .long("auth")
                .value_name("AUTH")
                .env("MINISERVE_AUTH")
                .value_parser(parse_auth_value)
                .num_args(1)
                .action(ArgAction::Append)
                .help("Set authentication")
                .long_help("Set authentication\n\nCurrently supported formats:\nusername:password, username:sha256:hash, username:sha512:hash\n(e.g. joe:123, joe:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3)"),
        )
        .arg(
            Arg::new("auth_file")
                .long("auth-file")
                .value_name("AUTH_FILE")
                .env("MINISERVE_AUTH_FILE")
                .value_parser(value_parser!(PathBuf))
                .value_hint(ValueHint::FilePath)
                .action(ArgAction::Set)
                .help("Read authentication values from a file")
                .long_help("Read authentication values from a file\n\nExample file content:\n\njoe:123\nbob:sha256:a665a45920422f9d417e4867efdc4fb8a04a1f3fff1fa07e998e86f7f7a27ae3\nbill:"),
        )
        .arg(
            Arg::new("route_prefix")
                .long("route-prefix")
                .value_name("ROUTE_PREFIX")
                .env("MINISERVE_ROUTE_PREFIX")
                .action(ArgAction::Set)
                .help("Use a specific route prefix"),
        )
        .arg(
            Arg::new("random_route")
                .long("random-route")
                .env("MINISERVE_RANDOM_ROUTE")
                .action(ArgAction::SetTrue)
                .conflicts_with("route_prefix")
                .help("Generate a random 6-hexdigit route"),
        )
        .arg(
            Arg::new("no_symlinks")
                .short('P')
                .long("no-symlinks")
                .env("MINISERVE_NO_SYMLINKS")
                .action(ArgAction::SetTrue)
                .help("Hide symlinks in listing and prevent them from being followed"),
        )
        .arg(
            Arg::new("hidden")
                .short('H')
                .long("hidden")
                .env("MINISERVE_HIDDEN")
                .action(ArgAction::SetTrue)
                .help("Show hidden files"),
        )
        .arg(
            Arg::new("default_sorting_method")
                .short('S')
                .long("default-sorting-method")
                .value_name("DEFAULT_SORTING_METHOD")
                .env("MINISERVE_DEFAULT_SORTING_METHOD")
                .default_value("name")
                .value_parser(PossibleValuesParser::new(sorting_method_values()))
                .action(ArgAction::Set)
                .help("Default sorting method for file list"),
        )
        .arg(
            Arg::new("default_sorting_order")
                .short('O')
                .long("default-sorting-order")
                .value_name("DEFAULT_SORTING_ORDER")
                .env("MINISERVE_DEFAULT_SORTING_ORDER")
                .default_value("desc")
                .value_parser(PossibleValuesParser::new(sorting_order_values()))
                .action(ArgAction::Set)
                .help("Default sorting order for file list"),
        )
        .arg(
            Arg::new("color_scheme")
                .short('c')
                .long("color-scheme")
                .value_name("COLOR_SCHEME")
                .env("MINISERVE_COLOR_SCHEME")
                .default_value("squirrel")
                .value_parser(theme_values())
                .ignore_case(true)
                .action(ArgAction::Set)
                .help("Default color scheme"),
        )
        .arg(
            Arg::new("color_scheme_dark")
                .short('d')
                .long("color-scheme-dark")
                .value_name("COLOR_SCHEME_DARK")
                .env("MINISERVE_COLOR_SCHEME_DARK")
                .default_value("archlinux")
                .value_parser(theme_values())
                .ignore_case(true)
                .action(ArgAction::Set)
                .help("Default color scheme"),
        )
        .arg(
            Arg::new("qrcode")
                .short('q')
                .long("qrcode")
                .env("MINISERVE_QRCODE")
                .action(ArgAction::SetTrue)
                .help("Enable QR code display"),
        )
        .arg(
            Arg::new("allowed_upload_dir")
                .short('u')
                .long("upload-files")
                .value_name("ALLOWED_UPLOAD_DIR")
                .env("MINISERVE_ALLOWED_UPLOAD_DIR")
                .value_parser(value_parser!(PathBuf))
                .num_args(0..=1)
                .action(ArgAction::Append)
                .help("Enable file uploading (and optionally specify for which directory)")
                .long_help("Enable file uploading (and optionally specify for which directory)\n\nThe provided path is not a physical file system path. Instead, it's relative to the serve dir. For instance, if the serve dir is '/home/hello', set this to '/upload' to allow uploading to '/home/hello/upload'. When specified via environment variable, a path always needs to be specified."),
        )
        .arg(
            Arg::new("web_upload_concurrency")
                .long("web-upload-files-concurrency")
                .value_name("WEB_UPLOAD_CONCURRENCY")
                .env("MINISERVE_WEB_UPLOAD_CONCURRENCY")
                .default_value("0")
                .value_parser(value_parser!(usize))
                .action(ArgAction::Set)
                .help("Configure amount of concurrent uploads when visiting the website. Must have upload-files option enabled for this setting to matter")
                .long_help("Configure amount of concurrent uploads when visiting the website. Must have upload-files option enabled for this setting to matter.\n\nFor example, a value of 4 would mean that the web browser will only upload 4 files at a time to the web server when using the web browser interface.\n\nWhen the value is kept at 0, it attempts to resolve all the uploads at once in the web browser.\n\nNOTE: Web pages have a limit of how many active HTTP connections that they can make at one time, so even though you might set a concurrency limit of 100, the browser might only make progress on the max amount of connections it allows the web page to have open."),
        )
        .arg(
            Arg::new("chmod")
                .long("chmod")
                .value_name("CHMOD")
                .env("MINISERVE_CHMOD")
                .value_parser(parse_chmod)
                .requires("allowed_upload_dir")
                .action(ArgAction::Set)
                .help("Set unix file permissions of uploaded files")
                .long_help("Set unix file permissions of uploaded files\n\nThis takes an octal number, for example 0600. By default 0666 & ~umask is used to simulate the system's default behavior."),
        )
        .arg(
            Arg::new("directory_size")
                .long("directory-size")
                .env("MINISERVE_DIRECTORY_SIZE")
                .action(ArgAction::SetTrue)
                .help("Enable recursive directory size calculation")
                .long_help("Enable recursive directory size calculation\n\nThis is disabled by default because it is a potentially fairly IO intensive operation."),
        )
        .arg(
            Arg::new("mkdir_enabled")
                .short('U')
                .long("mkdir")
                .env("MINISERVE_MKDIR_ENABLED")
                .action(ArgAction::SetTrue)
                .requires("allowed_upload_dir")
                .help("Enable creating directories"),
        )
        .arg(
            Arg::new("media_type")
                .short('m')
                .long("media-type")
                .value_name("MEDIA_TYPE")
                .env("MINISERVE_MEDIA_TYPE")
