pub const AUTHORS: &str =
    "Sven-Hendrik Haase <svenstaro@gmail.com>, Boastful Squirrel <boastful.squirrel@gmail.com>";

/// Parsed header (name lowercased, value)
#[derive(Clone, Debug)]
pub struct HeaderPair {
    pub name: String,
    pub value: Vec<u8>,
}

#[derive(Debug)]
pub enum HeaderParseError {
    Name,
    Value,
    NewLine,
    TooMany,
}

impl std::fmt::Display for HeaderParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            HeaderParseError::Name => "invalid header name",
            HeaderParseError::Value => "invalid header value",
            HeaderParseError::NewLine => "invalid new line",
            HeaderParseError::TooMany => "too many headers",
        };
        f.write_str(s)
    }
}
impl std::error::Error for HeaderParseError {}

fn is_token(b: u8) -> bool {
    matches!(b, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~')
        || b.is_ascii_alphanumeric()
}

/// Emulates parsing of a single header line like httparse::parse_headers with
/// a one-element header buffer.
pub fn parse_header(src: &str) -> Result<Vec<HeaderPair>, HeaderParseError> {
    let buf = format!("{src}\n");
    let b = buf.as_bytes();
    let mut i = 0;
    let mut out: Vec<HeaderPair> = Vec::new();
    loop {
        if i >= b.len() {
            break; // partial
        }
        // end of headers?
        if b[i] == b'\r' {
            if i + 1 >= b.len() {
                break;
            }
            if b[i + 1] == b'\n' {
                break;
            }
            return Err(HeaderParseError::NewLine);
        }
        if b[i] == b'\n' {
            break;
        }
        if out.len() >= 1 {
            return Err(HeaderParseError::TooMany);
        }
        // name
        let start = i;
        while i < b.len() && is_token(b[i]) {
            i += 1;
        }
        if i >= b.len() {
            break;
        }
        if b[i] != b':' || i == start {
            return Err(HeaderParseError::Name);
        }
        let name = &buf[start..i];
        i += 1;
        // skip whitespace
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
        let vstart = i;
        let mut vend;
        loop {
            if i >= b.len() {
                // partial: value incomplete
                return Ok(out);
            }
            let c = b[i];
            if c == b'\r' {
                vend = i;
                if i + 1 >= b.len() {
                    return Ok(out);
                }
                if b[i + 1] != b'\n' {
                    return Err(HeaderParseError::Value);
                }
                i += 2;
                break;
            }
            if c == b'\n' {
                vend = i;
                i += 1;
                break;
            }
            if c == b'\t' || c == b' ' || (0x21..=0x7e).contains(&c) || c >= 0x80 {
                i += 1;
                continue;
            }
            return Err(HeaderParseError::Value);
        }
        while vend > vstart && (b[vend - 1] == b' ' || b[vend - 1] == b'\t') {
            vend -= 1;
        }
        out.push(HeaderPair { name: name.to_ascii_lowercase(), value: b[vstart..vend].to_vec() });
    }
    Ok(out)
}

