impl std::fmt::Display for AuthParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AuthParseError::InvalidAuthFormat => write!(f, "Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash"),
            AuthParseError::InvalidPasswordHash => write!(f, "Invalid format for password hash. Expected hex code"),
            AuthParseError::InvalidHashMethod(m) => write!(f, "{m} is not a valid hashing method. Expected sha256 or sha512"),
            AuthParseError::PasswordTooLong => write!(f, "HTTP password length exceeds 255 characters"),
        }
    }
}

impl std::error::Error for AuthParseError {}

pub fn hex_decode(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    if b.len() % 2 != 0 {
        return None;
    }
    let val = |c: u8| -> Option<u8> {
        match c {
            b'0'..=b'9' => Some(c - b'0'),
            b'a'..=b'f' => Some(c - b'a' + 10),
            b'A'..=b'F' => Some(c - b'A' + 10),
            _ => None,
        }
    };
    let mut out = Vec::with_capacity(b.len() / 2);
    for ch in b.chunks(2) {
        out.push(val(ch[0])? << 4 | val(ch[1])?);
    }
    Some(out)
}

pub fn parse_auth(src: &str) -> Result<RequiredAuth, AuthParseError> {
    let mut split = src.splitn(3, ':');
    let username = split.next().ok_or(AuthParseError::InvalidAuthFormat)?;
    let second = split.next().ok_or(AuthParseError::InvalidAuthFormat)?;
    let password = match split.next() {
        Some(hash_hex) => {
            let bin = hex_decode(hash_hex).ok_or(AuthParseError::InvalidPasswordHash)?;
            match second {
                "sha256" => RequiredAuthPassword::Sha256(bin),
                "sha512" => RequiredAuthPassword::Sha512(bin),
                _ => return Err(AuthParseError::InvalidHashMethod(second.to_string())),
            }
        }
        None => {
            if second.len() > 255 {
                return Err(AuthParseError::PasswordTooLong);
            }
            RequiredAuthPassword::Plain(second.to_string())
        }
    };
    Ok(RequiredAuth { username: username.to_string(), password })
}

pub fn base64_decode_strict(s: &str) -> Option<Vec<u8>> {
    let b = s.as_bytes();
    if b.len() % 4 != 0 {
        return None;
    }
    let val = |c: u8| -> Option<u32> {
        match c {
            b'A'..=b'Z' => Some((c - b'A') as u32),
            b'a'..=b'z' => Some((c - b'a' + 26) as u32),
            b'0'..=b'9' => Some((c - b'0' + 52) as u32),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    };
    let mut out = Vec::new();
    let n = b.len() / 4;
    for (idx, ch) in b.chunks(4).enumerate() {
        let last = idx == n - 1;
        let pad = ch.iter().rev().take_while(|&&c| c == b'=').count();
        if pad > 0 && !last {
            return None;
        }
        if pad > 2 {
            return None;
        }
        let mut acc: u32 = 0;
        for (k, &c) in ch.iter().enumerate() {
            let v = if k >= 4 - pad { 0 } else { val(c)? };
            acc = (acc << 6) | v;
        }
        let bytes = [(acc >> 16) as u8, (acc >> 8) as u8, acc as u8];
        // canonical check for trailing bits
        if pad == 1 && (acc & 0xff) != 0 {
            return None;
        }
        if pad == 2 && (acc & 0xffff) != 0 {
            return None;
        }
        out.extend_from_slice(&bytes[..3 - pad]);
    }
    Some(out)
}

pub enum AuthResult {
    /// No or malformed credentials
    Missing,
    /// Credentials given but don't match
    Invalid,
    /// Valid credentials for the given user name
    Ok(String),
}

pub fn check_auth(header: Option<&[u8]>, required: &[RequiredAuth]) -> AuthResult {
    let h = match header {
        Some(h) => h,
        None => return AuthResult::Missing,
    };
    let h = match std::str::from_utf8(h) {
        Ok(s) => s,
        Err(_) => return AuthResult::Missing,
    };
    let rest = match h.strip_prefix("Basic ") {
        Some(r) => r,
        None => return AuthResult::Missing,
    };
    let decoded = match base64_decode_strict(rest) {
        Some(d) => d,
        None => return AuthResult::Missing,
    };
    let decoded = match String::from_utf8(decoded) {
        Ok(s) => s,
        Err(_) => return AuthResult::Missing,
    };
    let (user, pass) = match decoded.split_once(':') {
        Some(x) => x,
        None => return AuthResult::Missing,
    };
    let ok = required.iter().any(|r| r.username == user && compare_password(pass, &r.password));
    if ok {
        AuthResult::Ok(user.to_string())
    } else {
        AuthResult::Invalid
    }
}

fn compare_password(given: &str, required: &RequiredAuthPassword) -> bool {
    match required {
        RequiredAuthPassword::Plain(p) => given == p,
        RequiredAuthPassword::Sha256(h) => Sha256::digest(given.as_bytes()).as_slice() == h.as_slice(),
        RequiredAuthPassword::Sha512(h) => Sha512::digest(given.as_bytes()).as_slice() == h.as_slice(),
    }
}
