{"command":"cat > /workspace/src/timeutil.rs <<'EOF'
//! Date/time helpers (UTC only).

use std::time::{SystemTime, UNIX_EPOCH};

pub struct Civil {
    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
    pub weekday: u32, // 0 = Monday
}

const WEEKDAYS: [&str; 7] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

pub fn days_to_civil(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn civil_to_days(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = (y - era * 400) as i64;
    let m = m as i64;
    let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_unix(secs: i64) -> Civil {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (year, month, day) = days_to_civil(days);
    let weekday = ((days + 3).rem_euclid(7)) as u32; // 1970-01-01 was Thursday (3)
    Civil {
        year,
        month,
        day,
        hour: (rem / 3600) as u32,
        minute: ((rem % 3600) / 60) as u32,
        second: (rem % 60) as u32,
        weekday,
    }
}

pub fn unix_secs(t: SystemTime) -> i64 {
    match t.duration_since(UNIX_EPOCH) {
        Ok(d) => d.as_secs() as i64,
        Err(e) => -(e.duration().as_secs_f64().ceil() as i64),
    }
}

pub fn now_secs() -> i64 {
    unix_secs(SystemTime::now())
}

/// "Sat, 10 Oct 2026 04:11:46 +0000"
pub fn rfc2822(secs: i64) -> String {
    let c = civil_from_unix(secs);
    format!(
        "{}, {:02} {} {} {:02}:{:02}:{:02} +0000",
        WEEKDAYS[c.weekday as usize],
        c.day,
        MONTHS[(c.month - 1) as usize],
        c.year,
        c.hour,
        c.minute,
        c.second
    )
}

/// "Sat, 10 Oct 2026 04:11:46 GMT"
pub fn http_date(secs: i64) -> String {
    let c = civil_from_unix(secs);
    format!(
        "{}, {:02} {} {:04} {:02}:{:02}:{:02} GMT",
        WEEKDAYS[c.weekday as usize],
        c.day,
        MONTHS[(c.month - 1) as usize],
        c.year,
        c.hour,
        c.minute,
        c.second
    )
}

/// Parse an HTTP date (IMF-fixdate, RFC 850, asctime). Returns unix seconds.
pub fn parse_http_date(s: &str) -> Option<i64> {
    let s = s.trim();
    let month_idx = |m: &str| MONTHS.iter().position(|x| x.eq_ignore_ascii_case(m)).map(|i| i as u32 + 1);
    let parse_time = |t: &str| -> Option<(u32, u32, u32)> {
        let mut it = t.split(':');
        let h = it.next()?.parse().ok()?;
        let mi = it.next()?.parse().ok()?;
        let se = it.next()?.parse().ok()?;
        if it.next().is_some() || h > 23 || mi > 59 || se > 60 {
            return None;
        }
        Some((h, mi, se))
    };
    let parts: Vec<&str> = s.split_whitespace().collect();
    let (y, mo, d, (h, mi, se)) = if parts.len() == 6 && parts[0].ends_with(',') && parts[5] == "GMT" {
        // IMF-fixdate: Sun, 06 Nov 1994 08:49:37 GMT
        let d: u32 = parts[1].parse().ok()?;
        let mo = month_idx(parts[2])?;
