//! A small HTTP/1.x server implementation.

use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::sync::Arc;
use std::time::{Duration, Instant};

use crate::tls::{TlsAcceptor, TlsStream};

pub type StreamFn = Box<dyn FnOnce(&mut dyn Write) -> io::Result<()> + Send>;

pub enum Body {
    /// Empty body with `content-length: 0`
    Empty,
    /// No body and no content-length header (e.g. 304)
    NoBody,
    Bytes(Vec<u8>),
    File(std::fs::File, u64, u64),
    /// Streamed with chunked transfer encoding
    Stream(StreamFn),
}

pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, Vec<u8>)>,
    pub body: Body,
}

impl Response {
    pub fn new(status: u16) -> Response {
        Response { status, headers: Vec::new(), body: Body::Empty }
    }
    pub fn with_body(status: u16, content_type: Option<&str>, body: Vec<u8>) -> Response {
        let mut r = Response::new(status);
        if let Some(ct) = content_type {
            r.set_header("content-type", ct);
        }
        r.body = Body::Bytes(body);
        r
    }
    pub fn text(status: u16, body: &str) -> Response {
        Response::with_body(status, Some("text/plain; charset=utf-8"), body.as_bytes().to_vec())
    }
    pub fn header(&self, name: &str) -> Option<&[u8]> {
        self.headers.iter().find(|(n, _)| n == name).map(|(_, v)| v.as_slice())
    }
    pub fn header_str(&self, name: &str) -> Option<&str> {
        self.header(name).and_then(|v| std::str::from_utf8(v).ok())
    }
    pub fn has_header(&self, name: &str) -> bool {
        self.headers.iter().any(|(n, _)| n == name)
    }
    pub fn set_header(&mut self, name: &str, value: &str) {
        self.set_header_bytes(name, value.as_bytes());
    }
    pub fn set_header_bytes(&mut self, name: &str, value: &[u8]) {
        if let Some(h) = self.headers.iter_mut().find(|(n, _)| n == name) {
            h.1 = value.to_vec();
        } else {
            self.headers.push((name.to_string(), value.to_vec()));
        }
    }
    pub fn remove_header(&mut self, name: &str) {
        self.headers.retain(|(n, _)| n != name);
    }
    pub fn body_len(&self) -> Option<u64> {
        match &self.body {
            Body::Empty | Body::NoBody => Some(0),
            Body::Bytes(b) => Some(b.len() as u64),
            Body::File(_, _, l) => Some(*l),
            Body::Stream(_) => None,
        }
    }
