//! A small HTTP/1.x server implementation.

use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::sync::Arc;
use std::time::{Duration, Instant};

use crate::tls::{TlsAcceptor, TlsStream};

pub type StreamFn = Box<dyn FnOnce(&mut dyn Write) -> io::Result<()> + Send>;

pub enum Body {
    /// Empty body with `content-length: 0`
    Empty,
    /// No body and no content-length header (e.g. 304)
    NoBody,
    Bytes(Vec<u8>),
    File(std::fs::File, u64, u64),
    /// Streamed with chunked transfer encoding
    Stream(StreamFn),
}

pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, Vec<u8>)>,
    pub body: Body,
}

impl Response {
    pub fn new(status: u16) -> Response {
        Response { status, headers: Vec::new(), body: Body::Empty }
    }
    pub fn with_body(status: u16, content_type: Option<&str>, body: Vec<u8>) -> Response {
        let mut r = Response::new(status);
        if let Some(ct) = content_type {
            r.set_header("content-type", ct);
        }
        r.body = Body::Bytes(body);
        r
    }
    pub fn text(status: u16, body: &str) -> Response {
        Response::with_body(status, Some("text/plain; charset=utf-8"), body.as_bytes().to_vec())
    }
    pub fn header(&self, name: &str) -> Option<&[u8]> {
        self.headers.iter().find(|(n, _)| n == name).map(|(_, v)| v.as_slice())
    }
    pub fn header_str(&self, name: &str) -> Option<&str> {
        self.header(name).and_then(|v| std::str::from_utf8(v).ok())
    }
    pub fn has_header(&self, name: &str) -> bool {
        self.headers.iter().any(|(n, _)| n == name)
    }
    pub fn set_header(&mut self, name: &str, value: &str) {
        self.set_header_bytes(name, value.as_bytes());
    }
    pub fn set_header_bytes(&mut self, name: &str, value: &[u8]) {
        if let Some(h) = self.headers.iter_mut().find(|(n, _)| n == name) {
            h.1 = value.to_vec();
        } else {
            self.headers.push((name.to_string(), value.to_vec()));
        }
    }
    pub fn remove_header(&mut self, name: &str) {
        self.headers.retain(|(n, _)| n != name);
    }
    pub fn body_len(&self) -> Option<u64> {
        match &self.body {
            Body::Empty | Body::NoBody => Some(0),
            Body::Bytes(b) => Some(b.len() as u64),
            Body::File(_, _, l) => Some(*l),
            Body::Stream(_) => None,
        }
    }
}

pub struct Request {
    pub method: String,
    pub target: String,
    pub path: String,
    pub query: String,
    pub version_minor: u8,
    pub headers: Vec<(String, Vec<u8>)>,
    pub peer: SocketAddr,
    pub https: bool,
}

impl Request {
    pub fn header(&self, name: &str) -> Option<&[u8]> {
        self.headers.iter().find(|(n, _)| n == name).map(|(_, v)| v.as_slice())
    }
    pub fn header_str(&self, name: &str) -> Option<&str> {
        self.header(name).and_then(|v| std::str::from_utf8(v).ok())
    }
    pub fn headers_all<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a [u8]> + 'a {
        self.headers.iter().filter(move |(n, _)| n == name).map(|(_, v)| v.as_slice())
    }
}

pub trait Handler: Send + Sync {
    fn handle(&self, req: &Request, body: &mut dyn Read) -> Response;
}

pub fn reason(code: u16) -> &'static str {
    match code {
        100 => "Continue",
        101 => "Switching Protocols",
        200 => "OK",
        201 => "Created",
        202 => "Accepted",
        204 => "No Content",
        206 => "Partial Content",
        207 => "Multi-Status",
        301 => "Moved Permanently",
        302 => "Found",
        303 => "See Other",
        304 => "Not Modified",
        307 => "Temporary Redirect",
        308 => "Permanent Redirect",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        406 => "Not Acceptable",
        408 => "Request Timeout",
        409 => "Conflict",
        411 => "Length Required",
        412 => "Precondition Failed",
        413 => "Payload Too Large",
        414 => "URI Too Long",
        415 => "Unsupported Media Type",
        416 => "Range Not Satisfiable",
        417 => "Expectation Failed",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        502 => "Bad Gateway",
        503 => "Service Unavailable",
        505 => "HTTP Version Not Supported",
        _ => "",
    }
}

/// Connection abstraction over plain TCP and TLS streams.
pub enum Conn {
    Plain(TcpStream),
    Tls(TlsStream),
}

impl Conn {
    fn set_read_timeout(&self, d: Option<Duration>) {
        match self {
            Conn::Plain(s) => {
                let _ = s.set_read_timeout(d);
            }
            Conn::Tls(t) => t.set_read_timeout(d),
        }
    }
}

impl Read for Conn {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Conn::Plain(s) => s.read(buf),
            Conn::Tls(t) => t.read(buf),
        }
    }
}

impl Write for Conn {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Conn::Plain(s) => s.write(buf),
            Conn::Tls(t) => t.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Conn::Plain(s) => s.flush(),
            Conn::Tls(t) => t.flush(),
        }
    }
}

/// Shared reader/writer over a connection.
struct ConnIo {
    reader: BufReader<ConnReadHalf>,
}

/// We need both buffered reading and writing to the same connection.
/// Use a raw pointer wrapper living as long as the connection thread.
struct ConnReadHalf(*mut Conn);
unsafe impl Send for ConnReadHalf {}
impl Read for ConnReadHalf {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        unsafe { (*self.0).read(buf) }
    }
}

enum BodyKind {
    None,
    Length(u64),
    Chunked,
}

/// Request body reader over the buffered connection.
pub struct BodyReader<'a> {
    inner: &'a mut BufReader<ConnReadHalf>,
    kind: BodyKind,
    remaining: u64,
    chunk_left: u64,
    done: bool,
    pub error: bool,
    continue_sender: Option<&'a mut dyn FnMut()>,
}

impl<'a> BodyReader<'a> {
    fn send_continue(&mut self) {
        if let Some(f) = self.continue_sender.take() {
            f();
        }
    }
    fn read_line(&mut self) -> io::Result<String> {
        let mut line = Vec::new();
        loop {
            let mut b = [0u8; 1];
            let n = self.inner.read(&mut b)?;
            if n == 0 {
                return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "eof in chunk"));
            }
            line.push(b[0]);
            if b[0] == b'\n' {
                break;
            }
            if line.len() > 4096 {
                return Err(io::Error::new(io::ErrorKind::InvalidData, "chunk line too long"));
            }
        }
        Ok(String::from_utf8_lossy(&line).trim().to_string())
    }
    /// Drain the remaining body; returns false if the connection must be closed.
    fn drain(&mut self, limit: u64) -> bool {
        if self.done || self.error {
            return !self.error;
        }
        if let BodyKind::Length(_) = self.kind {
            if self.remaining > limit {
                return false;
            }
        }
        if self.continue_sender.is_some() {
            // client is waiting for 100-continue which we never sent; just close
            return matches!(self.kind, BodyKind::None);
        }
        let mut buf = [0u8; 16384];
        let mut total = 0u64;
        loop {
            match self.read(&mut buf) {
                Ok(0) => return !self.error,
                Ok(n) => {
                    total += n as u64;
                    if total > limit {
                        return false;
                    }
                }
                Err(_) => return false,
            }
        }
    }
}

impl<'a> Read for BodyReader<'a> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.done || buf.is_empty() {
            return Ok(0);
        }
        self.send_continue();
        match self.kind {
            BodyKind::None => {
                self.done = true;
                Ok(0)
            }
            BodyKind::Length(_) => {
                if self.remaining == 0 {
                    self.done = true;
                    return Ok(0);
                }
                let max = std::cmp::min(buf.len() as u64, self.remaining) as usize;
                let n = match self.inner.read(&mut buf[..max]) {
                    Ok(n) => n,
                    Err(e) => {
                        self.error = true;
                        return Err(e);
                    }
                };
                if n == 0 {
                    self.error = true;
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "payload incomplete"));
                }
                self.remaining -= n as u64;
                if self.remaining == 0 {
                    self.done = true;
                }
                Ok(n)
            }
            BodyKind::Chunked => {
                if self.chunk_left == 0 {
                    let line = match self.read_line() {
                        Ok(l) => l,
                        Err(e) => {
                            self.error = true;
                            return Err(e);
                        }
                    };
                    let size_str = line.split(';').next().unwrap_or("").trim();
                    let size = match u64::from_str_radix(size_str, 16) {
                        Ok(s) => s,
                        Err(_) => {
                            self.error = true;
                            return Err(io::Error::new(io::ErrorKind::InvalidData, "bad chunk size"));
                        }
                    };
                    if size == 0 {
                        // trailers
                        loop {
                            match self.read_line() {
                                Ok(l) if l.is_empty() => break,
                                Ok(_) => continue,
                                Err(e) => {
                                    self.error = true;
                                    return Err(e);
                                }
                            }
                        }
                        self.done = true;
                        return Ok(0);
                    }
                    self.chunk_left = size;
                }
                let max = std::cmp::min(buf.len() as u64, self.chunk_left) as usize;
                let n = match self.inner.read(&mut buf[..max]) {
                    Ok(n) => n,
                    Err(e) => {
                        self.error = true;
                        return Err(e);
                    }
                };
                if n == 0 {
                    self.error = true;
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "payload incomplete"));
                }
                self.chunk_left -= n as u64;
                if self.chunk_left == 0 {
                    // consume CRLF
                    let _ = self.read_line();
                }
                Ok(n)
            }
        }
    }
}

pub struct ServerOptions {
    pub verbose: bool,
}

fn is_tchar(b: u8) -> bool {
    matches!(b, b'!' | b'#' | b'$' | b'%' | b'&' | b'\'' | b'*' | b'+' | b'-' | b'.' | b'^' | b'_' | b'`' | b'|' | b'~')
        || b.is_ascii_alphanumeric()
}

fn is_uri_char(b: u8) -> bool {
    // httparse accepts visible ASCII (excluding space/DEL) and obs bytes >= 0x80
    (0x21..=0x7e).contains(&b) || b >= 0x80
}

enum HeadResult {
    Ok(Request, BodyKind, bool /*expect continue*/),
    Closed,
    Bad,
    TooLarge,
    Timeout,
}

fn read_head(reader: &mut BufReader<ConnReadHalf>, peer: SocketAddr, https: bool) -> HeadResult {
    let mut head: Vec<u8> = Vec::new();
    // skip leading empty lines
    loop {
        let mut line = Vec::new();
        let r = reader.read_until(b'\n', &mut line);
        match r {
            Ok(0) => {
                return if head.is_empty() && line.is_empty() { HeadResult::Closed } else { HeadResult::Bad };
            }
            Ok(_) => {}
            Err(e) => {
                if e.kind() == io::ErrorKind::WouldBlock || e.kind() == io::ErrorKind::TimedOut {
                    return if head.is_empty() { HeadResult::Timeout } else { HeadResult::Bad };
                }
                return HeadResult::Closed;
            }
        }
        if !line.ends_with(b"\n") {
            return if head.is_empty() && line.is_empty() { HeadResult::Closed } else { HeadResult::Bad };
        }
        if head.is_empty() && (line == b"\r\n" || line == b"\n") {
            continue;
        }
        let end = line == b"\r\n" || line == b"\n";
        head.extend_from_slice(&line);
        if head.len() > 64 * 1024 {
            return HeadResult::TooLarge;
        }
        if end {
            break;
        }
    }
    let text = &head;
    let mut lines: Vec<&[u8]> = Vec::new();
    for l in text.split(|&b| b == b'\n') {
        let l = if l.ends_with(b"\r") { &l[..l.len() - 1] } else { l };
        lines.push(l);
    }
    // request line
    let rl = lines[0];
    let parts: Vec<&[u8]> = rl.split(|&b| b == b' ').collect();
    if parts.len() != 3 {
        return HeadResult::Bad;
    }
    let method = parts[0];
    if method.is_empty() || !method.iter().all(|&b| is_tchar(b)) {
        return HeadResult::Bad;
    }
    let target = parts[1];
    if target.is_empty() || !target.iter().all(|&b| is_uri_char(b)) {
        return HeadResult::Bad;
    }
    let version_minor = match parts[2] {
        b"HTTP/1.1" => 1,
        b"HTTP/1.0" => 0,
        _ => return HeadResult::Bad,
    };
    let mut headers = Vec::new();
    for l in &lines[1..] {
        if l.is_empty() {
            continue;
        }
        let colon = match l.iter().position(|&b| b == b':') {
            Some(c) => c,
            None => return HeadResult::Bad,
        };
        let name = &l[..colon];
        if name.is_empty() || !name.iter().all(|&b| is_tchar(b)) {
            return HeadResult::Bad;
        }
        let mut v = &l[colon + 1..];
        while let Some((&f, rest)) = v.split_first() {
            if f == b' ' || f == b'\t' {
                v = rest;
            } else {
                break;
            }
        }
        while let Some((&last, rest)) = v.split_last() {
            if last == b' ' || last == b'\t' {
                v = rest;
            } else {
                break;
            }
        }
        if v.iter().any(|&b| b < 0x20 && b != b'\t' || b == 0x7f) {
            return HeadResult::Bad;
        }
        headers.push((String::from_utf8_lossy(name).to_ascii_lowercase(), v.to_vec()));
    }
    let target_s = String::from_utf8_lossy(target).to_string();
    // derive path & query
    let mut path_part = target_s.clone();
    if let Some(idx) = path_part.find("://") {
        // absolute-form
        let rest = &path_part[idx + 3..];
        path_part = match rest.find('/') {
            Some(p) => rest[p..].to_string(),
            None => "/".to_string(),
        };
    }
    let (path, query) = match path_part.find('?') {
        Some(q) => (path_part[..q].to_string(), path_part[q + 1..].to_string()),
        None => (path_part.clone(), String::new()),
    };
    let path = if let Some(h) = path.find('#') { path[..h].to_string() } else { path };
    let req = Request {
        method: String::from_utf8_lossy(method).to_string(),
        target: target_s,
        path,
        query,
        version_minor,
        headers,
        peer,
        https,
    };
    // body framing
    let te = req.header_str("transfer-encoding").map(|s| s.to_ascii_lowercase());
    let kind = if let Some(te) = te {
        if te.trim().ends_with("chunked") && version_minor == 1 {
            BodyKind::Chunked
        } else {
            return HeadResult::Bad;
        }
    } else if let Some(cl) = req.header("content-length") {
        let s = std::str::from_utf8(cl).unwrap_or("x");
        match s.trim().parse::<u64>() {
            Ok(0) => BodyKind::None,
            Ok(n) => BodyKind::Length(n),
            Err(_) => return HeadResult::Bad,
        }
    } else {
        BodyKind::None
    };
    let expect = req
        .header_str("expect")
        .map(|e| e.eq_ignore_ascii_case("100-continue"))
        .unwrap_or(false)
        && version_minor == 1;
    HeadResult::Ok(req, kind, expect)
}

fn wants_keep_alive(req: &Request) -> bool {
    let conn = req.header_str("connection").map(|s| s.to_ascii_lowercase());
    match req.version_minor {
        1 => !conn.map(|c| c.split(',').any(|t| t.trim() == "close")).unwrap_or(false),
        _ => conn.map(|c| c.split(',').any(|t| t.trim() == "keep-alive")).unwrap_or(false),
    }
}

struct CountingWriter<'a> {
    inner: &'a mut dyn Write,
    count: u64,
}

impl<'a> Write for CountingWriter<'a> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let n = self.inner.write(buf)?;
        self.count += n as u64;
        Ok(n)
    }
    fn flush(&mut self) -> io::Result<()> {
        self.inner.flush()
    }
}

struct ChunkedWriter<'a> {
    inner: &'a mut dyn Write,
    count: u64,
}

impl<'a> Write for ChunkedWriter<'a> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        let mut out = Vec::with_capacity(buf.len() + 16);
        out.extend_from_slice(format!("{:X}\r\n", buf.len()).as_bytes());
        out.extend_from_slice(buf);
        out.extend_from_slice(b"\r\n");
        self.inner.write_all(&out)?;
        self.count += buf.len() as u64;
        Ok(buf.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        self.inner.flush()
    }
}

/// Buffered writer that only writes to the underlying stream in large blocks.
struct BlockWriter<'a> {
    inner: &'a mut dyn Write,
    buf: Vec<u8>,
}

impl<'a> Write for BlockWriter<'a> {
    fn write(&mut self, data: &[u8]) -> io::Result<usize> {
        self.buf.extend_from_slice(data);
        if self.buf.len() >= 65536 {
            self.inner.write_all(&self.buf)?;
            self.buf.clear();
        }
        Ok(data.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        if !self.buf.is_empty() {
            self.inner.write_all(&self.buf)?;
            self.buf.clear();
        }
        self.inner.flush()
    }
}

fn write_response(
    conn: &mut dyn Write,
    req_version: u8,
    is_head: bool,
    keep_alive: bool,
    explicit_close: bool,
    resp: Response,
) -> io::Result<(bool, u64)> {
    let mut head = Vec::with_capacity(512);
    head.extend_from_slice(format!("HTTP/1.{} {} {}\r\n", req_version, resp.status, reason(resp.status)).as_bytes());
    let no_body_status = resp.status < 200 || resp.status == 204 || resp.status == 304;
    let mut keep_alive = keep_alive;
    let streamed = matches!(resp.body, Body::Stream(_));
    if streamed && req_version == 0 {
        keep_alive = false;
    }
    let mut len_header: Option<String> = None;
    match &resp.body {
        Body::NoBody => {}
        Body::Stream(_) => {
            if req_version == 1 {
                len_header = Some("transfer-encoding: chunked".to_string());
            }
        }
        _ => {
            if !no_body_status {
                len_header = Some(format!("content-length: {}", resp.body_len().unwrap_or(0)));
            }
        }
    }
    if let Some(l) = len_header {
        head.extend_from_slice(l.as_bytes());
        head.extend_from_slice(b"\r\n");
    }
    if req_version == 1 && !keep_alive && explicit_close {
        head.extend_from_slice(b"connection: close\r\n");
    } else if req_version == 0 && keep_alive {
        head.extend_from_slice(b"connection: keep-alive\r\n");
    }
    for (n, v) in &resp.headers {
        head.extend_from_slice(n.as_bytes());
        head.extend_from_slice(b": ");
        head.extend_from_slice(v);
        head.extend_from_slice(b"\r\n");
    }
    head.extend_from_slice(format!("date: {}\r\n\r\n", crate::timeutil::http_date(crate::timeutil::now_secs())).as_bytes());
    let size = resp.body_len();
    if is_head || no_body_status {
        conn.write_all(&head)?;
        conn.flush()?;
        // HEAD of streamed body cannot keep alive reliably with chunked framing
        return Ok((keep_alive, size.unwrap_or(0)));
    }
    match resp.body {
        Body::Empty | Body::NoBody => {
            conn.write_all(&head)?;
            conn.flush()?;
            Ok((keep_alive, 0))
        }
        Body::Bytes(b) => {
            if b.len() < 65536 {
                head.extend_from_slice(&b);
                conn.write_all(&head)?;
            } else {
                conn.write_all(&head)?;
                conn.write_all(&b)?;
            }
            conn.flush()?;
            Ok((keep_alive, b.len() as u64))
        }
        Body::File(mut f, off, len) => {
            use std::io::Seek;
            conn.write_all(&head)?;
            f.seek(io::SeekFrom::Start(off))?;
            let mut left = len;
            let mut buf = vec![0u8; 65536];
            while left > 0 {
                let want = std::cmp::min(left, buf.len() as u64) as usize;
                let n = f.read(&mut buf[..want])?;
                if n == 0 {
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "file truncated"));
                }
                conn.write_all(&buf[..n])?;
                left -= n as u64;
            }
            conn.flush()?;
            Ok((keep_alive, len))
        }
        Body::Stream(f) => {
            conn.write_all(&head)?;
            conn.flush()?;
            if req_version == 1 {
                let mut cw = ChunkedWriter { inner: conn, count: 0 };
                let res = {
                    let mut bw = BlockWriter { inner: &mut cw, buf: Vec::new() };
                    let r = f(&mut bw);
                    match r {
                        Ok(()) => bw.flush(),
                        Err(e) => Err(e),
                    }
                };
                let count = cw.count;
                match res {
                    Ok(()) => {
                        conn.write_all(b"0\r\n\r\n")?;
                        conn.flush()?;
                        Ok((keep_alive, count))
                    }
                    Err(_) => Ok((false, count)),
                }
            } else {
                let mut cw = CountingWriter { inner: conn, count: 0 };
                let res = {
                    let mut bw = BlockWriter { inner: &mut cw, buf: Vec::new() };
                    let r = f(&mut bw);
                    match r {
                        Ok(()) => bw.flush(),
                        Err(e) => Err(e),
                    }
                };
                let _ = res;
                Ok((false, cw.count))
            }
        }
    }
}

fn handle_connection(mut conn: Conn, peer: SocketAddr, https: bool, handler: Arc<dyn Handler>, opts: Arc<ServerOptions>) {
    let conn_ptr: *mut Conn = &mut conn;
    let mut reader = BufReader::with_capacity(16384, ConnReadHalf(conn_ptr));
    let mut first = true;
    loop {
        conn.set_read_timeout(Some(Duration::from_secs(5)));
        let head = read_head(&mut reader, peer, https);
        let (req, kind, expect) = match head {
            HeadResult::Ok(r, k, e) => (r, k, e),
            HeadResult::Closed => return,
            HeadResult::Timeout => {
                if first {
                    let msg = format!(
                        "HTTP/1.1 408 Request Timeout\r\ncontent-length: 0\r\nconnection: close\r\ndate: {}\r\n\r\n",
                        crate::timeutil::http_date(crate::timeutil::now_secs())
                    );
                    let _ = conn.write_all(msg.as_bytes());
                }
                return;
            }
            HeadResult::Bad | HeadResult::TooLarge => {
                let code = if matches!(head, HeadResult::TooLarge) { 431 } else { 400 };
                let msg = format!(
                    "HTTP/1.1 {} {}\r\ncontent-length: 0\r\nconnection: close\r\ndate: {}\r\n\r\n",
                    code,
                    reason(code),
                    crate::timeutil::http_date(crate::timeutil::now_secs())
                );
                let _ = conn.write_all(msg.as_bytes());
                let _ = conn.flush();
                return;
            }
        };
        first = false;
        let start = Instant::now();
        conn.set_read_timeout(Some(Duration::from_secs(300)));
        let keep_alive = wants_keep_alive(&req);
        let explicit_close = req
            .header_str("connection")
            .map(|c| c.to_ascii_lowercase().split(',').any(|t| t.trim() == "close"))
            .unwrap_or(false);
        let is_head = req.method == "HEAD";
        let conn_ptr2: *mut Conn = &mut conn;
        let mut send_continue = move || unsafe {
            let _ = (*conn_ptr2).write_all(b"HTTP/1.1 100 Continue\r\n\r\n");
            let _ = (*conn_ptr2).flush();
        };
        let (resp, body_ok) = {
            let remaining = match kind {
                BodyKind::Length(n) => n,
                _ => 0,
            };
            let mut body = BodyReader {
                inner: &mut reader,
                kind,
                remaining,
                chunk_left: 0,
                done: false,
                error: false,
                continue_sender: if expect { Some(&mut send_continue) } else { None },
            };
            let resp = handler.handle(&req, &mut body);
            let ok = body.drain(1 << 20);
            (resp, ok)
        };
        let status = resp.status;
        let keep = keep_alive && body_ok;
        let result = write_response(&mut conn, req.version_minor, is_head, keep, explicit_close, resp);
        let (keep, size) = match result {
            Ok(x) => x,
            Err(_) => (false, 0),
        };
        if opts.verbose {
            let referer = req.header("referer").map(|v| String::from_utf8_lossy(v).to_string()).unwrap_or_else(|| "-".to_string());
            let ua = req.header("user-agent").map(|v| String::from_utf8_lossy(v).to_string()).unwrap_or_else(|| "-".to_string());
            let ver = if req.version_minor == 1 { "HTTP/1.1" } else { "HTTP/1.0" };
