fn pem_blocks(data: &str) -> Vec<(String, String)> {
    // returns (label, full block text)
    let mut out = Vec::new();
    let mut rest = data;
    while let Some(start) = rest.find("-----BEGIN ") {
        let after = &rest[start + 11..];
        let label_end = match after.find("-----") {
            Some(e) => e,
            None => break,
        };
        let label = after[..label_end].to_string();
        let end_marker = format!("-----END {}-----", label);
        let block_end = match rest[start..].find(&end_marker) {
            Some(e) => start + e + end_marker.len(),
            None => break,
        };
        out.push((label, rest[start..block_end].to_string()));
        rest = &rest[block_end..];
    }
    out
}

fn panic_no_key() -> ! {
    let mut e = io::stderr();
    let _ = write!(
