        std::process::id()
    );
    let _ = e.flush();
    std::process::abort();
}

pub fn load_config(cert: &Path, key: &Path) -> Result<TlsConfig, ConfigError> {
    let cert_data = std::fs::read(cert).map_err(|e| ConfigError {
        msg: format!("Couldn't access TLS certificate {:?}", cert),
        causes: vec![e.to_string()],
    })?;
    let key_data = std::fs::read(key).map_err(|e| ConfigError {
        msg: format!("Couldn't access TLS key {:?}", key),
        causes: vec![e.to_string()],
    })?;
    let cert_text = String::from_utf8_lossy(&cert_data).to_string();
    let key_text = String::from_utf8_lossy(&key_data).to_string();
    let certs: Vec<String> = pem_blocks(&cert_text)
        .into_iter()
        .filter(|(l, _)| l == "CERTIFICATE")
        .map(|(_, b)| b)
        .collect();
    let key_block = pem_blocks(&key_text)
        .into_iter()
        .find(|(l, _)| l == "PRIVATE KEY" || l == "RSA PRIVATE KEY" || l == "EC PRIVATE KEY")
        .map(|(_, b)| b);
    let key_block = match key_block {
        Some(k) => k,
        None => panic_no_key(),
    };
    if certs.is_empty() {
        return Err(ConfigError { msg: "peer sent no certificates".to_string(), causes: vec![] });
    }
    unsafe {
        let ctx = SSL_CTX_new(TLS_server_method());
        if ctx.is_null() {
            return Err(ConfigError { msg: "failed to create TLS context".to_string(), causes: vec![] });
        }
        for (i, c) in certs.iter().enumerate() {
            let bio = BIO_new_mem_buf(c.as_ptr() as *const c_void, c.len() as c_int);
            let x = PEM_read_bio_X509(bio, std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut());
            BIO_free(bio);
            if x.is_null() {
                ERR_clear_error();
                return Err(ConfigError { msg: "invalid peer certificate: BadEncoding".to_string(), causes: vec![] });
            }
            if i == 0 {
                SSL_CTX_use_certificate(ctx, x);
                X509_free(x);
            } else {
                // ownership transferred to ctx
                SSL_CTX_ctrl(ctx, SSL_CTRL_EXTRA_CHAIN_CERT, 0, x as *mut c_void);
            }
        }
        let bio = BIO_new_mem_buf(key_block.as_ptr() as *const c_void, key_block.len() as c_int);
        let pkey = PEM_read_bio_PrivateKey(bio, std::ptr::null_mut(), std::ptr::null_mut(), std::ptr::null_mut());
        BIO_free(bio);
