//! Assorted helpers.

use std::cmp::Ordering;

/// Escape text for HTML like maud does.
pub fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 8);
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Percent-encode a path segment (component set without '/').
pub fn encode_segment(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        let keep = b.is_ascii_alphanumeric() || matches!(b, b'!' | b'\'' | b'(' | b')' | b'*' | b'-' | b'.' | b'_' | b'~');
        if keep {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn hexval(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Percent-decode bytes (invalid escapes are kept as-is).
pub fn percent_decode(s: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'%' && i + 2 < s.len() + 0 && i + 2 <= s.len() - 1 + 0 {
            if let (Some(h), Some(l)) = (hexval(s[i + 1]), hexval(s[i + 2])) {
                out.push(h << 4 | l);
                i += 3;
                continue;
            }
        }
        out.push(s[i]);
        i += 1;
    }
    out
}

pub fn percent_decode_str(s: &str) -> Vec<u8> {
    percent_decode(s.as_bytes())
}

/// Decode application/x-www-form-urlencoded (form_urlencoded crate semantics).
pub fn form_decode(s: &str) -> String {
    let replaced: Vec<u8> = s.bytes().map(|b| if b == b'+' { b' ' } else { b }).collect();
    String::from_utf8_lossy(&percent_decode(&replaced)).into_owned()
}

/// Parse a query string into key/value pairs.
pub fn parse_query(q: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    for part in q.split('&') {
        if part.is_empty() {
            continue;
        }
        let (k, v) = match part.find('=') {
            Some(i) => (&part[..i], &part[i + 1..]),
            None => (part, ""),
        };
        out.push((form_decode(k), form_decode(v)));
    }
    out
}

/// Human readable size like bytesize's IEC display.
pub fn human_size(bytes: u64) -> String {
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut unit: u64 = 1024;
    let mut idx = 0;
    while idx + 1 < units.len() && bytes >= unit.saturating_mul(1024) && unit.checked_mul(1024).is_some() {
        unit *= 1024;
        idx += 1;
    }
    format!("{:.1} {}", bytes as f64 / unit as f64, units[idx])
}

/// Port of alphanumeric_sort::compare_str
pub fn alnum_compare(a: &str, b: &str) -> Ordering {
    let mut c1 = a.chars();
