//! Static file serving, modelled after actix-files' NamedFile.

use std::fs::Metadata;
use std::os::unix::fs::MetadataExt;
use std::path::Path;
use std::time::UNIX_EPOCH;

use crate::http::{Body, Request, Response};
use crate::util;

pub fn etag_for(md: &Metadata) -> String {
    let (secs, nanos) = match md.modified().ok().and_then(|m| m.duration_since(UNIX_EPOCH).ok()) {
        Some(d) => (d.as_secs(), d.subsec_nanos()),
        None => (0, 0),
    };
    format!("\"{:x}:{:x}:{:x}:{:x}\"", md.ino(), md.len(), secs, nanos)
}

fn parse_etag_list(v: &str) -> Option<Vec<(bool, String)>> {
    // returns list of (weak, tag)
    let mut out = Vec::new();
    for item in v.split(',') {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        let (weak, rest) = if let Some(r) = item.strip_prefix("W/") { (true, r) } else { (false, item) };
        if rest.len() < 2 || !rest.starts_with('"') || !rest.ends_with('"') {
            return None;
        }
        let tag = &rest[1..rest.len() - 1];
        if tag.contains('"') {
            return None;
        }
        out.push((weak, tag.to_string()));
    }
    if out.is_empty() {
        return None;
    }
    Some(out)
}

pub struct HttpRange {
    pub start: u64,
    pub length: u64,
}

pub fn parse_range(header: &str, size: u64) -> Result<Vec<HttpRange>, ()> {
    if header.is_empty() {
        return Ok(Vec::new());
    }
    let rest = header.strip_prefix("bytes=").ok_or(())?;
    let size_sig = size as i64;
    let mut no_overlap = false;
    let mut ranges = Vec::new();
    for ra in rest.split(',').map(|x| x.trim()).filter(|x| !x.is_empty()) {
        let mut it = ra.split('-');
        let start_str = it.next().ok_or(())?.trim();
        let end_str = it.next().ok_or(())?.trim();
        if start_str.is_empty() {
            let mut length: i64 = end_str.parse().map_err(|_| ())?;
            if length > size_sig {
                length = size_sig;
            }
            ranges.push(HttpRange { start: (size_sig - length) as u64, length: length as u64 });
        } else {
            let start: i64 = start_str.parse().map_err(|_| ())?;
            if start < 0 {
                return Err(());
            }
            if start >= size_sig {
                no_overlap = true;
                continue;
            }
            let length = if end_str.is_empty() {
                size_sig - start
            } else {
                let mut end: i64 = end_str.parse().map_err(|_| ())?;
                if start > end {
                    return Err(());
                }
                if end >= size_sig {
                    end = size_sig - 1;
                }
                end - start + 1
            };
            ranges.push(HttpRange { start: start as u64, length: length as u64 });
        }
    }
    if no_overlap && ranges.is_empty() {
        return Err(());
    }
    Ok(ranges)
}

/// Serve a file. `path` must point to an existing regular file.
pub fn serve_file(req: &Request, path: &Path) -> std::io::Result<Response> {
    let file = std::fs::File::open(path)?;
    let md = file.metadata()?;
    let ct_base = util::guess_mime(path);
    let ct = util::with_utf8(ct_base);
    let filename = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
    let disposition = if util::is_inline(ct_base) { "inline" } else { "attachment" };
    let etag = etag_for(&md);
    let mtime_secs = md.modified().ok().and_then(|m| m.duration_since(UNIX_EPOCH).ok()).map(|d| d.as_secs() as i64);
    let last_modified = mtime_secs.map(crate::timeutil::http_date);
    let my_tag = &etag[1..etag.len() - 1];

    // preconditions
    let if_match = req.header_str("if-match");
    let any_match = match if_match {
        None => true,
        Some(v) if v.trim() == "*" => true,
        Some(v) => match parse_etag_list(v) {
            None => true,
            Some(items) => items.iter().any(|(weak, t)| !weak && t == my_tag),
        },
    };
    let precondition_failed = if !any_match {
        true
    } else if let (Some(m), Some(since)) = (mtime_secs, req.header_str("if-unmodified-since").and_then(crate::timeutil::parse_http_date)) {
        m >= 0 && since >= 0 && m > since
    } else {
        false
    };

    let inm = req.header_str("if-none-match");
    let none_match = match inm {
        None => true,
        Some(v) if v.trim() == "*" => false,
        Some(v) => match parse_etag_list(v) {
            None => true,
            Some(items) => !items.iter().any(|(_, t)| t == my_tag),
        },
    };
    let inm_parsed = inm.map(|v| v.trim() == "*" || parse_etag_list(v).is_some()).unwrap_or(false);
    let not_modified = if !none_match {
        true
    } else if inm_parsed {
        false
    } else if let (Some(m), Some(since)) = (mtime_secs, req.header_str("if-modified-since").and_then(crate::timeutil::parse_http_date)) {
        m >= 0 && since >= 0 && m <= since
    } else {
        false
    };

    let mut res = Response::new(200);
    res.set_header("content-type", &ct);
    res.set_header("content-disposition", &util::content_disposition(disposition, &filename));
    if let Some(lm) = &last_modified {
        res.set_header("last-modified", lm);
    }
    res.set_header("etag", &etag);
    res.set_header("accept-ranges", "bytes");

    let full_len = md.len();
    let mut length = full_len;
    let mut offset = 0;
    if let Some(range) = req.header("range") {
        match std::str::from_utf8(range) {
            Ok(r) => match parse_range(r, full_len) {
                Ok(ranges) if !ranges.is_empty() => {
                    length = ranges[0].length;
                    offset = ranges[0].start;
                    res.set_header(
                        "content-range",
                        &format!("bytes {}-{}/{}", offset, (offset + length).saturating_sub(1), full_len),
                    );
                }
                Ok(_) => {}
                Err(_) => {
                    res.set_header("content-range", &format!("bytes */{}", length));
                    res.status = 416;
                    res.body = Body::Empty;
                    return Ok(res);
                }
            },
            Err(_) => {
                res.status = 400;
                res.body = Body::Empty;
                return Ok(res);
            }
        }
    }

    if precondition_failed {
        res.status = 412;
        res.body = Body::Empty;
        return Ok(res);
    } else if not_modified {
        res.status = 304;
        res.body = Body::NoBody;
        return Ok(res);
    }

    if offset != 0 || length != full_len {
        res.status = 206;
    }
    res.body = Body::File(file, offset, length);
    Ok(res)
}
