fn chevron_up() -> &'static str {
    "▴"
}
fn chevron_down() -> &'static str {
    "▾"
}

fn build_link(out: &mut String, name: &str, title: &str, sort_method: Option<SortingMethod>, sort_order: Option<SortingOrder>) {
    let mut link = format!("?sort={name}&order=asc");
    let mut help = format!("Sort by {name} in ascending order");
    let mut chevron = chevron_down();
    let mut class = "";
    if let Some(method) = sort_method {
        if method.as_str() == name {
            class = "active";
            if let Some(order) = sort_order {
                if order == SortingOrder::Asc {
                    link = format!("?sort={name}&order=desc");
                    help = format!("Sort by {name} in descending order");
                    chevron = chevron_up();
                }
            }
        }
    }
    out.push_str("<span class=\"");
    out.push_str(class);
    out.push_str("\"><span class=\"chevron\">");
    out.push_str(chevron);
    out.push_str("</span><a href=\"");
    out.push_str(&esc(&link));
    out.push_str("\" title=\"");
    out.push_str(&esc(&help));
    out.push_str("\">");
    out.push_str(&esc(title));
    out.push_str("</a></span>");
}

fn make_link_with_trailing_slash(link: &str) -> String {
    if link.ends_with('/') {
        link.to_string()
    } else {
        format!("{link}/")
    }
}

pub fn parametrized_link(link: &str, sort_method: Option<SortingMethod>, sort_order: Option<SortingOrder>, raw: bool) -> String {
    if raw {
        return format!("{}?raw=true", make_link_with_trailing_slash(link));
    }
    if let (Some(m), Some(o)) = (sort_method, sort_order) {
        return format!("{}?sort={}&order={}", make_link_with_trailing_slash(link), m.as_str(), o.as_str());
    }
    make_link_with_trailing_slash(link)
}

fn entry_row(
