            out.push_str("<a class=\"symlink\" href=\"");
            out.push_str(&href);
            out.push_str("\">");
            out.push_str(&esc(&entry.name));
            out.push_str("/<span class=\"symlink-symbol\"></span><a class=\"directory\">");
