pub fn raw_page(entries: &[Entry], is_root: bool, conf: &MiniserveConfig) -> String {
    let mut out = String::with_capacity(4096);
    out.push_str("<!DOCTYPE html><html><body><table><thead><th class=\"name\">Name</th><th class=\"size\">Size</th><th class=\"date\">Last modification</th></thead><tbody>");
    if !is_root {
