            (conf.zip_enabled, "zip", "zip"),
        ] {
            if !enabled {
                continue;
            }
            let link = if sort_method.is_none() && sort_order.is_none() {
                format!("?download={method}")
            } else {
                format!("{}&download={}", parametrized_link("", sort_method, sort_order, false), method)
            };
            out.push_str("<a href=\"");
            out.push_str(&esc(&link));
            out.push_str("\">Download .");
            out.push_str(ext);
            out.push_str("</a>");
        }
        out.push_str("</div>");
    }
    out.push_str("<div class=\"toolbar_box_group\">");
    if conf.file_upload && upload_allowed {
        out.push_str("<div class=\"toolbar_box\"><form id=\"file_submit\" action=\"");
        out.push_str(&esc(&upload_action));
        out.push_str("\" method=\"POST\" enctype=\"multipart/form-data\"><p>Select a file to upload or drag it anywhere into the window</p><div>");
        match &conf.uploadable_media_type {
            Some(accept) => {
                out.push_str("<input id=\"file-input\" accept=\"");
