cat > /workspace/src/render.rs <<'EOF'
//! HTML rendering (mimics the maud templates of miniserve).

use crate::config::{MiniserveConfig, SortingMethod, SortingOrder};
use crate::listing::{Breadcrumb, Entry, ListingQuery};
use crate::util::html_escape as esc;

const THEME_JS: &str = include_str!("assets/theme.js");
const API_JS: &str = include_str!("assets/api.js");
const UPLOAD_JS: &str = include_str!("assets/upload.js");

const THEMES: [(&str, &str); 5] = [
    ("Default (light/dark)", "default"),
    ("Squirrel (light)", "squirrel"),
    ("Arch Linux (dark)", "archlinux"),
    ("Zenburn (dark)", "zenburn"),
    ("Monokai (dark)", "monokai"),
];

fn page_header(out: &mut String, title: &str, file_upload: bool, conf: &MiniserveConfig) {
    out.push_str("<head><meta charset=\"utf-8\"><meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"color-scheme\" content=\"dark light\">");
    out.push_str("<link rel=\"icon\" type=\"image/svg+xml\" href=\"");
    out.push_str(&esc(&conf.favicon_route));
    out.push_str("\"><link rel=\"stylesheet\" href=\"");
    out.push_str(&esc(&conf.css_route));
    out.push_str("\"><title>");
    out.push_str(&esc(title));
    out.push_str("</title><script>");
    out.push_str(THEME_JS);
    out.push_str("</script><script>const API_ROUTE = '");
    out.push_str(&conf.api_route);
    out.push_str("';");
    out.push_str(API_JS);
    out.push_str("</script>");
    if file_upload {
        out.push_str("<script>");
        out.push_str(&esc(&format!("const CONCURRENCY = {};", conf.web_upload_concurrency)));
        out.push_str(UPLOAD_JS);
        out.push_str("</script>");
    }
    out.push_str("</head>");
}

fn version_footer(out: &mut String) {
    out.push_str("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/");
    out.push_str(crate::cli::VERSION);
    out.push_str("</div>");
}

pub fn render_error(error_description: &str, status: u16, conf: &MiniserveConfig, return_address: &str) -> String {
    let code = format!("{} {}", status, crate::http::reason(status));
    let mut out = String::with_capacity(4096);
    out.push_str("<!DOCTYPE html><html>");
    page_header(&mut out, &code, false, conf);
    out.push_str("<body><div class=\"error\"><p>");
    out.push_str(&esc(&code));
    out.push_str("</p>");
    for line in error_description.lines() {
        out.push_str("<p>");
        out.push_str(&esc(line));
        out.push_str("</p>");
    }
    if conf.route_prefix.is_empty() && !conf.disable_indexing {
        out.push_str("<div class=\"error-nav\"><a class=\"error-back\" href=\"");
        out.push_str(&esc(return_address));
        out.push_str("\">Go back to file listing</a></div>");
    }
    if !conf.hide_version_footer {
        out.push_str("<p class=\"footer\">");
        version_footer(&mut out);
        out.push_str("</p>");
    }
    out.push_str("</div></body></html>");
    out
}

fn chevron_up() -> &'static str {
    "▴"
}
fn chevron_down() -> &'static str {
    "▾"
}

fn build_link(out: &mut String, name: &str, title: &str, sort_method: Option<SortingMethod>, sort_order: Option<SortingOrder>) {
    let mut link = format!("?sort={name}&order=asc");
    let mut help = format!("Sort by {name} in ascending order");
    let mut chevron = chevron_down();
    let mut class = "";
    if let Some(method) = sort_method {
        if method.as_str() == name {
            class = "active";
            if let Some(order) = sort_order {
                if order == SortingOrder::Asc {
                    link = format!("?sort={name}&order=desc");
                    help = format!("Sort by {name} in descending order");
                    chevron = chevron_up();
                }
            }
        }
    }
    out.push_str("<span class=\"");
    out.push_str(class);
    out.push_str("\"><span class=\"chevron\">");
    out.push_str(chevron);
    out.push_str("</span><a href=\"");
    out.push_str(&esc(&link));
    out.push_str("\" title=\"");
    out.push_str(&esc(&help));
    out.push_str("\">");
    out.push_str(&esc(title));
    out.push_str("</a></span>");
}

fn make_link_with_trailing_slash(link: &str) -> String {
    if link.ends_with('/') {
        link.to_string()
    } else {
        format!("{link}/")
    }
}

pub fn parametrized_link(link: &str, sort_method: Option<SortingMethod>, sort_order: Option<SortingOrder>, raw: bool) -> String {
    if raw {
        return format!("{}?raw=true", make_link_with_trailing_slash(link));
    }
    if let (Some(m), Some(o)) = (sort_method, sort_order) {
        return format!("{}?sort={}&order={}", make_link_with_trailing_slash(link), m.as_str(), o.as_str());
    }
    make_link_with_trailing_slash(link)
}

fn entry_row(
    out: &mut String,
    entry: &Entry,
    sort_method: Option<SortingMethod>,
    sort_order: Option<SortingOrder>,
    raw: bool,
    conf: &MiniserveConfig,
    rm_allowed: bool,
    encoded_dir: &str,
) {
    out.push_str("<tr class=\"entry-type-");
    out.push_str(if entry.is_dir { "directory" } else { "file" });
    out.push_str("\"><td><p>");
    if entry.is_dir {
        let href = esc(&parametrized_link(&entry.link, sort_method, sort_order, raw));
        if let Some(dest) = &entry.symlink_info {
            out.push_str("<a class=\"symlink\" href=\"");
            out.push_str(&href);
            out.push_str("\">");
            out.push_str(&esc(&entry.name));
            out.push_str("/<span class=\"symlink-symbol\"></span><a class=\"directory\">");
            out.push_str(&esc(dest));
            out.push_str("/</a></a>");
        } else {
            out.push_str("<a class=\"directory\" href=\"");
            out.push_str(&href);
            out.push_str("\">");
            out.push_str(&esc(&entry.name));
            out.push_str("/</a>");
        }
    } else {
        let href = esc(&entry.link);
        if let Some(dest) = &entry.symlink_info {
            out.push_str("<a class=\"symlink\" href=\"");
            out.push_str(&href);
            out.push_str("\">");
            out.push_str(&esc(&entry.name));
            out.push_str("<span class=\"symlink-symbol\"></span><a class=\"file\">");
            out.push_str(&esc(dest));
            out.push_str("</a></a>");
        } else {
            out.push_str("<a class=\"file\" href=\"");
            out.push_str(&href);
            out.push_str("\">");
            out.push_str(&esc(&entry.name));
            out.push_str("</a>");
        }
        if !raw {
            if let Some(size) = entry.size {
                out.push_str("<span class=\"mobile-info size\">");
                if conf.size_display_exact {
                    out.push_str(&format!("{} B", size));
                } else {
                    build_link(out, "size", &crate::util::human_size(size), sort_method, sort_order);
                }
                out.push_str("</span>");
            }
            if let Some(h) = &entry.humanized {
                out.push_str("<span class=\"mobile-info history\">");
                build_link(out, "date", h, sort_method, sort_order);
                out.push_str("</span>");
            }
        }
    }
    out.push_str("</p></td><td class=\"size-cell\">");
    if let Some(size) = entry.size {
        if conf.size_display_exact {
            out.push_str(&format!("{} B", size));
        } else {
            out.push_str(&crate::util::human_size(size));
        }
    }
    out.push_str("</td><td class=\"date-cell\">");
    if let Some(d) = &entry.date_str {
        out.push_str("<span>");
        out.push_str(&esc(d));
        out.push_str(" </span>");
    }
    if let Some(h) = &entry.humanized {
        out.push_str("<span class=\"history\">");
        out.push_str(&esc(h));
        out.push_str("</span>");
    }
    out.push_str("</td>");
    if rm_allowed && !raw {
        let rm_path = format!("{}/{}", encoded_dir.trim_end_matches('/'), crate::util::encode_segment(&entry.name));
        out.push_str("<td class=\"actions-cell\"><form class=\"rm_form\" action=\"");
        out.push_str(&esc(&format!("{}/rm?path={}", conf.route_prefix, rm_path)));
        out.push_str("\" method=\"POST\"><button type=\"submit\" title=\"Delete\">✗</button></form></td>");
    }
    out.push_str("</tr>");
}

pub fn raw_page(entries: &[Entry], is_root: bool, conf: &MiniserveConfig) -> String {
    let mut out = String::with_capacity(4096);
    out.push_str("<!DOCTYPE html><html><body><table><thead><th class=\"name\">Name</th><th class=\"size\">Size</th><th class=\"date\">Last modification</th></thead><tbody>");
    if !is_root {
        out.push_str("<tr><td colspan=\"3\"><p><a class=\"root\" href=\"");
        out.push_str(&esc(&parametrized_link("../", None, None, true)));
        out.push_str("\">..</a></p></td></tr>");
    }
    for e in entries {
        entry_row(&mut out, e, None, None, true, conf, false, "");
    }
    out.push_str("</tbody></table></body></html>");
    out
}

fn wget_footer(out: &mut String, abs_url_path: &str, root_dir_name: &str, current_user: Option<&str>, path: &str) {
    fn escape_apostrophes(x: &str) -> String {
        x.replace('\'', "'\"'\"'")
    }
    let depth = path.matches('/').count().saturating_sub(1);
    let cut_dirs = match depth {
        0 => format!(" -P '{}'", escape_apostrophes(root_dir_name)),
        1 => String::new(),
        x => format!(" --cut-dirs={}", x - 1),
    };
    let user_params = match current_user {
        Some(u) => format!(" --ask-password --user '{}'", escape_apostrophes(u)),
        None => String::new(),
    };
    let encoded_abs_path = abs_url_path.replace('\'', "%27");
    let command = format!("wget -rcnp -R 'index.html*' -nH{cut_dirs}{user_params} '{encoded_abs_path}?raw=true'");
    let click_to_copy = format!("navigator.clipboard.writeText(\"{command}\")");
    out.push_str("<div class=\"downloadDirectory\"><p>Download folder:</p><a class=\"cmd\" title=\"Click to copy!\" style=\"cursor: pointer;\" onclick=\"");
    out.push_str(&esc(&click_to_copy));
    out.push_str("\">");
    out.push_str(&esc(&command));
    out.push_str("</a></div>");
}

pub struct PageContext<'a> {
    pub entries: &'a [Entry],
    pub readme: Option<(String, String)>,
    pub abs_url: String,
    pub is_root: bool,
    pub query: &'a ListingQuery,
    pub breadcrumbs: &'a [Breadcrumb],
    pub encoded_dir: String,
    pub current_user: Option<String>,
    pub request_path: String,
    pub root_dir_name: String,
}

pub fn page(ctx: &PageContext, conf: &MiniserveConfig) -> String {
    let sort_method = ctx.query.sort;
    let sort_order = ctx.query.order;
    let upload_route = format!("{}/upload", conf.route_prefix);
    let mut upload_action = format!("{}?path={}", upload_route, ctx.encoded_dir);
    if let Some(m) = sort_method {
        upload_action = format!("{}&sort={}", upload_action, m.as_str());
    }
    if let Some(o) = sort_order {
        upload_action = format!("{}&order={}", upload_action, o.as_str());
    }
    let mkdir_action = format!("{}?path={}", upload_route, ctx.encoded_dir);
    let title_path = ctx.breadcrumbs.iter().map(|b| b.name.clone()).collect::<Vec<_>>().join("/");
    let upload_allowed = conf.allowed_upload_dir.is_empty()
        || conf.allowed_upload_dir.iter().any(|x| ctx.encoded_dir.starts_with(&format!("/{x}")));
    let rm_allowed = conf.rm_enabled
        && (conf.allowed_rm_dir.is_empty() || conf.allowed_rm_dir.iter().any(|x| ctx.encoded_dir.starts_with(&format!("/{x}"))));

    let mut out = String::with_capacity(16384);
    out.push_str("<!DOCTYPE html><html>");
    page_header(&mut out, &title_path, conf.file_upload, conf);
    out.push_str("<body id=\"drop-container\"><div class=\"toolbar_box_group\">");
    if conf.file_upload {
        out.push_str("<div class=\"drag-form\"><div class=\"form_title\"><h1>Drop your file here to upload it</h1></div></div>");
    }
    if conf.mkdir_enabled {
        out.push_str("<div class=\"form\"><div class=\"form_title\"><h1>Create a new directory</h1></div></div>");
    }
    out.push_str("</div><nav>");
    if conf.show_qrcode {
        out.push_str("<div><p>QR code</p><div class=\"qrcode\" id=\"qrcode\" title=\"");
        out.push_str(&ctx.abs_url);
        out.push_str("\">");
        out.push_str(&crate::qr::svg_for(&ctx.abs_url));
        out.push_str("</div></div>");
    }
    if !conf.hide_theme_selector {
        out.push_str("<div><p>Change theme...</p><ul class=\"theme\">");
        for (name, id) in THEMES.iter() {
            out.push_str(&format!(
                "<li data-theme=\"{id}\"><a href=\"javascript:updateColorScheme(&quot;{id}&quot;)\" title=\"Switch to {name} theme\">{name}</a></li>"
            ));
        }
        out.push_str("</ul></div>");
    }
    out.push_str("</nav><div class=\"container\"><span id=\"top\"></span><h1 class=\"title\" dir=\"ltr\">");
    for el in ctx.breadcrumbs {
        if el.link == "." {
            out.push_str("<span><bdi>");
            out.push_str(&esc(&el.name));
            out.push_str("</bdi></span>");
        } else {
            out.push_str("<a href=\"");
            out.push_str(&esc(&parametrized_link(&el.link, sort_method, sort_order, false)));
            out.push_str("\"><bdi>");
            out.push_str(&esc(&el.name));
            out.push_str("</bdi></a>");
        }
        out.push('/');
    }
    out.push_str("</h1><div class=\"toolbar\">");
    if conf.tar_enabled || conf.tar_gz_enabled || conf.zip_enabled {
        out.push_str("<div class=\"download\">");
        for (enabled, method, ext) in [
            (conf.tar_gz_enabled, "tar_gz", "tar.gz"),
            (conf.tar_enabled, "tar", "tar"),
            (conf.zip_enabled, "zip", "zip"),
        ] {
            if !enabled {
                continue;
            }
            let link = if sort_method.is_none() && sort_order.is_none() {
                format!("?download={method}")
            } else {
                format!("{}&download={}", parametrized_link("", sort_method, sort_order, false), method)
            };
            out.push_str("<a href=\"");
            out.push_str(&esc(&link));
            out.push_str("\">Download .");
            out.push_str(ext);
            out.push_str("</a>");
        }
        out.push_str("</div>");
    }
    out.push_str("<div class=\"toolbar_box_group\">");
    if conf.file_upload && upload_allowed {
        out.push_str("<div class=\"toolbar_box\"><form id=\"file_submit\" action=\"");
        out.push_str(&esc(&upload_action));
        out.push_str("\" method=\"POST\" enctype=\"multipart/form-data\"><p>Select a file to upload or drag it anywhere into the window</p><div>");
        match &conf.uploadable_media_type {
            Some(accept) => {
                out.push_str("<input id=\"file-input\" accept=\"");
                out.push_str(&esc(accept));
                out.push_str("\" type=\"file\" name=\"file_to_upload\" required=\"\" multiple></input>");
            }
            None => out.push_str("<input id=\"file-input\" type=\"file\" name=\"file_to_upload\" required=\"\" multiple></input>"),
        }
        out.push_str("<button type=\"submit\">Upload file</button></div></form></div>");
    }
    if conf.mkdir_enabled && upload_allowed {
        out.push_str("<div class=\"toolbar_box\"><form id=\"mkdir\" action=\"");
        out.push_str(&esc(&mkdir_action));
        out.push_str("\" method=\"POST\" enctype=\"multipart/form-data\"><p>Specify a directory name to create</p><div class=\"toolbar_box\"><input type=\"text\" name=\"mkdir\" required=\"\" placeholder=\"Directory name\"></input><button type=\"submit\">Create directory</button></div></form></div>");
    }
    out.push_str("</div></div><table><thead><th class=\"name\">");
    build_link(&mut out, "name", "Name", sort_method, sort_order);
    out.push_str("</th><th class=\"size\">");
    build_link(&mut out, "size", "Size", sort_method, sort_order);
    out.push_str("</th><th class=\"date\">");
    build_link(&mut out, "date", "Last modification", sort_method, sort_order);
    out.push_str("</th>");
    if rm_allowed {
        out.push_str("<th class=\"actions\"><span>Actions</span></th>");
    }
    out.push_str("</thead><tbody>");
    if !ctx.is_root {
        out.push_str(&format!("<tr><td colspan=\"{}\"><p><span class=\"root-chevron\">◂</span><a class=\"root\" href=\"", if rm_allowed { 4 } else { 3 }));
        out.push_str(&esc(&parametrized_link("../", sort_method, sort_order, false)));
        out.push_str("\">Parent directory</a></p></td></tr>");
    }
    for e in ctx.entries {
        entry_row(&mut out, e, sort_method, sort_order, false, conf, rm_allowed, &ctx.encoded_dir);
    }
    out.push_str("</tbody></table>");
    if let Some((name, contents)) = &ctx.readme {
        out.push_str("<div id=\"readme\"><h3 id=\"readme-filename\">");
        out.push_str(&esc(name));
        out.push_str("</h3><div id=\"readme-contents\">");
        out.push_str(contents);
        out.push_str("</div></div>");
    }
    out.push_str("<a class=\"back\" href=\"#top\">⇪</a><div class=\"footer\">");
    if conf.show_wget_footer {
        wget_footer(&mut out, &ctx.abs_url, &ctx.root_dir_name, ctx.current_user.as_deref(), &ctx.request_path);
    }
    if !conf.hide_version_footer {
        version_footer(&mut out);
    }
    out.push_str("</div></div>");
    out.push_str("<div class=\"upload_area\" id=\"upload_area\"><template id=\"upload_file_item\"><li class=\"upload_file_item\"><div class=\"upload_file_container\"><div class=\"upload_file_text\"><span class=\"file_upload_percent\"></span> - <span class=\"file_size\"></span> - <span class=\"file_name\"></span></div><button class=\"file_cancel_upload\">✖</button></div><div class=\"file_progress_bar\"></div></li></template><div class=\"upload_container\"><div class=\"upload_header\"><h4 style=\"margin:0px\" id=\"upload_title\"></h4><svg id=\"upload-toggle\" xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\" class=\"size-6\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"m4.5 15.75 7.5-7.5 7.5 7.5\"></path></svg></div><div class=\"upload_action\"><p id=\"upload_action_text\">Starting upload...</p><button class=\"upload_cancel\" id=\"upload_cancel\">CANCEL</button></div><div class=\"upload_files\"><ul class=\"upload_file_list\" id=\"upload_file_list\"></ul></div></div></div>");
    out.push_str("</body></html>");
    out
}
EOF
echo ok

