//! Runtime errors produced while handling requests.

use std::io;

use crate::http::Response;

pub enum RuntimeError {
    Io(String, io::Error),
    Multipart(String),
    DuplicateFile,
    UploadHashMismatch,
    UploadForbidden,
    RmForbidden,
    InvalidPath(String),
    InsufficientPermissions(String),
    Parse(String, String),
    ArchiveCreation(String, Box<RuntimeError>),
    ArchiveCreationDetail(String),
    InvalidHttpCredentials,
    InvalidHttpRequest(String),
    RouteNotFound(String),
}

impl std::fmt::Display for RuntimeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        use RuntimeError::*;
        match self {
            Io(m, e) => write!(f, "{m}\ncaused by: {e}"),
            Multipart(m) => write!(f, "Failed to process multipart request\ncaused by: {m}"),
            DuplicateFile => write!(f, "File already exists, and the on_duplicate_files option is set to error out"),
            UploadHashMismatch => write!(f, "File hash that was provided did not match checksum of uploaded file"),
            UploadForbidden => write!(f, "Upload not allowed to this directory"),
            RmForbidden => write!(f, "Remove not allowed to this directory"),
            InvalidPath(m) => write!(f, "Invalid path\ncaused by: {m}"),
            InsufficientPermissions(m) => write!(f, "Insufficient permissions to create file in {m}"),
            Parse(a, b) => write!(f, "Failed to parse {a}\ncaused by: {b}"),
            ArchiveCreation(a, e) => write!(f, "An error occurred while creating the {a}\ncaused by: {e}"),
            ArchiveCreationDetail(m) => write!(f, "{m}"),
            InvalidHttpCredentials => write!(f, "Invalid credentials for HTTP authentication"),
            InvalidHttpRequest(m) => write!(f, "Invalid HTTP request\ncaused by: {m}"),
            RouteNotFound(m) => write!(f, "Route {m} could not be found"),
        }
    }
}

impl std::fmt::Debug for RuntimeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        use RuntimeError::*;
        match self {
            Io(m, e) => write!(f, "IoError({:?}, {:?})", m, e),
            Multipart(m) => write!(f, "MultipartError({:?})", m),
            DuplicateFile => write!(f, "DuplicateFileError"),
            UploadHashMismatch => write!(f, "UploadHashMismatchError"),
            UploadForbidden => write!(f, "UploadForbiddenError"),
            RmForbidden => write!(f, "RmForbiddenError"),
            InvalidPath(m) => write!(f, "InvalidPathError({:?})", m),
            InsufficientPermissions(m) => write!(f, "InsufficientPermissionsError({:?})", m),
            Parse(a, b) => write!(f, "ParseError({:?}, {:?})", a, b),
            ArchiveCreation(a, e) => write!(f, "ArchiveCreationError({:?}, {:?})", a, e),
            ArchiveCreationDetail(m) => write!(f, "ArchiveCreationDetailError({:?})", m),
            InvalidHttpCredentials => write!(f, "InvalidHttpCredentials"),
            InvalidHttpRequest(m) => write!(f, "InvalidHttpRequestError({:?})", m),
            RouteNotFound(m) => write!(f, "RouteNotFoundError({:?})", m),
        }
    }
}

impl RuntimeError {
    pub fn status(&self) -> u16 {
        use RuntimeError::*;
        match self {
            Io(_, _) => 500,
            UploadHashMismatch | Multipart(_) | InvalidPath(_) | Parse(_, _) | InvalidHttpRequest(_) => 400,
            DuplicateFile => 409,
            UploadForbidden | RmForbidden | InsufficientPermissions(_) => 403,
            ArchiveCreation(_, e) => e.status(),
            ArchiveCreationDetail(_) => 500,
            InvalidHttpCredentials => 401,
            RouteNotFound(_) => 404,
        }
    }

    pub fn into_response(self) -> Response {
        let msg = self.to_string();
        crate::logger::log_error_chain(&msg);
        let mut r = Response::text(self.status(), &msg);
        if let RuntimeError::InvalidHttpCredentials = self {
            r.set_header("www-authenticate", "Basic realm=\"miniserve\"");
        }
        r
    }
}
EOF
echo ok"}

