/// Builds the directory listing response for `dir` (filesystem path).
pub fn directory_listing(
    req: &Request,
    dir: &Path,
    conf: &MiniserveConfig,
    current_user: Option<&str>,
    local_addr: &str,
) -> Response {
    if conf.disable_indexing {
        return Response::text(404, "File not found.");
    }
    let serve_path = req.path.clone();
    let ci = connection_info(req, local_addr);
    let abs_url = format!("{}://{}{}", ci.scheme, ci.host, serve_path);
    let base = Path::new(&serve_path);
    let is_root = base.parent().is_none() || base == Path::new(&conf.route_prefix);

    let stripped = if conf.route_prefix.is_empty() {
        serve_path.as_str()
    } else {
        serve_path.strip_prefix(conf.route_prefix.as_str()).unwrap_or(serve_path.as_str())
    };
    let trimmed = stripped.trim_matches('/');
    let encoded_dir = format!("/{}", trimmed);

    let title = conf.title.clone().unwrap_or_else(|| ci.host.clone());
    let breadcrumbs = {
        let decoded = String::from_utf8_lossy(&util::percent_decode_str(&encoded_dir)).to_string();
        let mut res = Vec::new();
        let mut link_acc = format!("{}/", conf.route_prefix);
        let comps: Vec<Component> = Path::new(&decoded).components().collect();
        for (i, c) in comps.iter().enumerate() {
            let name = match c {
                Component::RootDir => title.clone(),
                Component::Normal(s) => {
                    let n = s.to_string_lossy().to_string();
                    link_acc.push_str(&(util::encode_segment(&n) + "/"));
                    n
                }
                _ => String::new(),
            };
            let link = if i + 1 < comps.len() { link_acc.clone() } else { ".".to_string() };
            res.push(Breadcrumb { name, link });
        }
        res
    };

    let query = extract_query_parameters(&req.query);
    let mut entries: Vec<Entry> = Vec::new();
    let mut readme: Option<(String, String)> = None;

    let rd = match std::fs::read_dir(dir) {
        Ok(r) => r,
        Err(e) => return Response::text(500, &e.to_string()),
    };
    for entry in rd {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let file_name = entry.file_name().to_string_lossy().to_string();
        let visible = !file_name.starts_with('.');
        if !(visible || conf.show_hidden) {
            continue;
        }
        let lmd = entry.metadata();
        let (is_symlink, metadata) = match lmd {
            Ok(m) if m.file_type().is_symlink() => (true, std::fs::metadata(entry.path())),
            other => (false, other),
        };
        let symlink_dest = if is_symlink && conf.show_symlink_info {
            std::fs::read_link(entry.path()).ok().map(|p| p.to_string_lossy().into_owned())
        } else {
            None
        };
        let encoded_name = util::encode_segment(&file_name);
        let file_url = if serve_path.ends_with('/') {
            format!("{serve_path}{encoded_name}")
        } else {
            format!("{serve_path}/{encoded_name}")
        };
        let metadata = match metadata {
            Ok(m) => m,
            Err(_) => continue,
        };
        if conf.no_symlinks && is_symlink {
            continue;
        }
        let mtime = metadata.modified().ok();
        let date_str = mtime.map(|t| crate::timeutil::listing_date(crate::timeutil::unix_secs(t)));
        let humanized = mtime.map(humanize_systemtime);
        if metadata.is_dir() {
            entries.push(Entry {
                name: file_name,
                is_dir: true,
                link: file_url,
                size: None,
                mtime,
                symlink_info: symlink_dest,
                date_str,
                humanized,
            });
        } else if metadata.is_file() {
            let link = match &conf.file_external_url {
                Some(base_url) => format!("{}{}", base_url.trim_end_matches('/'), file_url),
                None => file_url,
            };
            if conf.readme && readme_match(&file_name.to_lowercase()) {
                let ext = file_name.rsplit('.').next().unwrap_or("").to_lowercase();
                if let Ok(content) = std::fs::read_to_string(entry.path()) {
                    let html = if ext == "md" {
                        crate::markdown::markdown_to_html(&content)
                    } else {
                        format!("<pre>{}</pre>", content)
                    };
                    readme = Some((file_name.clone(), html));
                }
            }
            entries.push(Entry {
                name: file_name,
                is_dir: false,
                link,
                size: Some(metadata.len()),
                mtime,
                symlink_info: symlink_dest,
                date_str,
                humanized,
            });
        }
    }

    match query.sort.unwrap_or(conf.default_sorting_method) {
        SortingMethod::Name => entries.sort_by(|a, b| util::alnum_compare(&a.name.to_lowercase(), &b.name.to_lowercase())),
        SortingMethod::Size => entries.sort_by(|a, b| b.size.unwrap_or(0).cmp(&a.size.unwrap_or(0))),
        SortingMethod::Date => entries.sort_by(|a, b| {
            b.mtime.unwrap_or(std::time::UNIX_EPOCH).cmp(&a.mtime.unwrap_or(std::time::UNIX_EPOCH))
        }),
    }
    if query.order.unwrap_or(conf.default_sorting_order) == SortingOrder::Asc {
        entries.reverse();
    }
    if conf.dirs_first {
        entries.sort_by_key(|e| !e.is_dir);
    }

    if let Some(method) = query.download {
        if !method.is_enabled(conf) {
            return Response::text(403, "Archive creation is disabled.");
        }
        crate::logger::info(&format!(
            "Creating an archive ({}) of {}...",
            method.extension(),
            dir.display()
        ));
        let dir_name = dir
            .components()
            .last()
            .map(|c| c.as_os_str().to_string_lossy().to_string())
            .unwrap_or_default();
        let file_name = format!("{}.{}", dir_name, method.extension());
        let mut resp = Response::new(200);
        resp.set_header("content-type", method.content_type());
        resp.set_header("content-transfer-encoding", "binary");
        resp.set_header("content-disposition", &format!("attachment; filename={:?}", file_name));
        let dir_buf: PathBuf = dir.to_path_buf();
        let skip_symlinks = conf.no_symlinks;
        resp.body = Body::Stream(Box::new(move |w| crate::archive::create_archive(method, &dir_buf, skip_symlinks, w)));
        return resp;
    }

    if query.raw == Some(true) {
        let body = crate::render::raw_page(&entries, is_root, conf);
        return Response::with_body(200, Some("text/html; charset=utf-8"), body.into_bytes());
    }

    let ctx = crate::render::PageContext {
        entries: &entries,
        readme,
        abs_url,
        is_root,
        query: &query,
        breadcrumbs: &breadcrumbs,
        encoded_dir,
        current_user: current_user.map(|s| s.to_string()),
        request_path: serve_path.clone(),
        root_dir_name: title,
    };
    let body = crate::render::page(&ctx, conf);
    Response::with_body(200, Some("text/html; charset=utf-8"), body.into_bytes())
}
EOF
