use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use crate::config::MiniserveConfig;
use crate::errors::RuntimeError;
use crate::http::{Body, Handler, Request, Response};
use crate::util;

pub struct App {
    pub conf: Arc<MiniserveConfig>,
    pub root: PathBuf,
