pub enum SegmentError {
    BadStart(char),
    BadChar(char),
    BadEnd(char),
    NotValidUtf8,
}

impl std::fmt::Display for SegmentError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SegmentError::BadStart(c) => write!(f, "segment started with invalid character: ('{c}')"),
            SegmentError::BadChar(c) => write!(f, "segment contained invalid character ('{c}')"),
            SegmentError::BadEnd(c) => write!(f, "segment ended with invalid character: ('{c}')"),
            SegmentError::NotValidUtf8 => write!(f, "path is not a valid UTF-8 string after percent-decoding"),
        }
    }
}

/// Port of actix-files' PathBufWrap::parse_path
pub fn parse_path(path: &str, hidden_files: bool) -> Result<PathBuf, SegmentError> {
    let segment_count = path.matches('/').count() + 1;
    let decoded = String::from_utf8(util::percent_decode_str(path)).map_err(|_| SegmentError::NotValidUtf8)?;
    if segment_count != decoded.matches('/').count() + 1 {
        return Err(SegmentError::BadChar('/'));
    }
    let mut buf = PathBuf::new();
    for segment in decoded.split('/') {
        if segment == ".." {
            buf.pop();
        } else if !hidden_files && segment.starts_with('.') {
            return Err(SegmentError::BadStart('.'));
        } else if segment.starts_with('*') {
            return Err(SegmentError::BadStart('*'));
        } else if segment.ends_with(':') {
            return Err(SegmentError::BadEnd(':'));
        } else if segment.ends_with('>') {
            return Err(SegmentError::BadEnd('>'));
        } else if segment.ends_with('<') {
            return Err(SegmentError::BadEnd('<'));
        } else if segment.is_empty() {
            continue;
        } else {
            buf.push(segment)
        }
    }
    Ok(buf)
}

fn method_not_allowed(allow: &str) -> Response {
    let mut r = Response::new(405);
    r.set_header("allow", allow);
    r
}

impl App {
    fn error_404(&self, req: &Request) -> Outcome {
        Outcome::Resp(RuntimeError::RouteNotFound(req.path.clone()).into_response())
    }

    fn has_symlink_component(&self, rel: &Path) -> bool {
        let mut p = self.root.clone();
        for c in rel.components() {
            p.push(c);
            if let Ok(md) = std::fs::symlink_metadata(&p) {
                if md.file_type().is_symlink() {
                    return true;
                }
            }
        }
        false
    }

    /// Files' default handler
    fn files_default(&self, req: &Request, sub: &str) -> Outcome {
        let conf = &self.conf;
        if conf.pretty_urls {
            let decoded = String::from_utf8_lossy(&util::percent_decode_str(sub)).to_string();
            let rel = decoded.trim_matches('/');
            let file_path = self.root.join(format!("{rel}.html"));
            if file_path.is_file() {
                match crate::files::serve_file(req, &file_path) {
                    Ok(r) => return Outcome::Resp(r),
                    Err(e) => return Outcome::Err(Response::text(io_status(&e), &e.to_string())),
                }
            }
            let e = std::io::Error::from(std::io::ErrorKind::NotFound);
            let e = std::fs::File::open(&file_path).err().unwrap_or(e);
            return Outcome::Err(Response::text(io_status(&e), &e.to_string()));
        }
        if conf.spa {
            if let Some(index) = &conf.index {
                let p = self.root.join(index);
                match crate::files::serve_file(req, &p) {
                    Ok(r) => return Outcome::Resp(r),
                    Err(e) => return Outcome::Err(Response::text(io_status(&e), &e.to_string())),
                }
            }
        }
        self.error_404(req)
    }

    fn files_service(&self, req: &Request, sub: &str) -> Outcome {
        let conf = &self.conf;
        let rel = match parse_path(sub, conf.show_hidden) {
            Ok(p) => p,
            Err(e) => return Outcome::Resp(Response::text(400, &e.to_string())),
        };
        if conf.no_symlinks && self.has_symlink_component(&rel) {
            return self.files_default(req, sub);
        }
        let path = self.root.join(&rel);
        if path.canonicalize().is_err() {
            return self.files_default(req, sub);
        }
        if path.is_dir() {
            if !req.path.ends_with('/') {
                let mut r = Response::new(307);
                r.set_header("location", &format!("{}/", req.path));
                return Outcome::Resp(r);
            }
            if let Some(index) = &conf.index {
                let named = path.join(index);
                if named.exists() {
                    if let Ok(r) = crate::files::serve_file(req, &named) {
                        return Outcome::Resp(r);
                    }
                }
            }
            let user = self.current_user(req);
            return Outcome::Resp(crate::listing::directory_listing(req, &path, conf, user.as_deref(), &self.local_addr));
        }
        match crate::files::serve_file(req, &path) {
            Ok(r) => Outcome::Resp(r),
            Err(_) => self.files_default(req, sub),
        }
    }

    fn current_user(&self, req: &Request) -> Option<String> {
        if self.conf.auth.is_empty() {
            return None;
        }
        match crate::auth::check_auth(req.header("authorization"), &self.conf.auth) {
            crate::auth::AuthResult::Ok(u) => Some(u),
            _ => None,
        }
    }

    fn scope(&self, req: &Request, body: &mut dyn Read, sub: &str) -> Outcome {
        let conf = &self.conf;
        if !conf.auth.is_empty() {
            match crate::auth::check_auth(req.header("authorization"), &conf.auth) {
                crate::auth::AuthResult::Ok(_) => {}
                crate::auth::AuthResult::Missing => {
                    let mut r = Response::new(401);
                    r.set_header("www-authenticate", "Basic");
                    return Outcome::Resp(r);
                }
                crate::auth::AuthResult::Invalid => {
                    return Outcome::Resp(RuntimeError::InvalidHttpCredentials.into_response());
                }
            }
        }
        if self.root.is_file() {
            if sub.is_empty() || sub == "/" {
                return match crate::files::serve_file(req, &self.root) {
                    Ok(r) => Outcome::Resp(r),
                    Err(e) => Outcome::Err(Response::text(io_status(&e), &e.to_string())),
                };
            }
            return self.error_404(req);
        }
        if conf.file_upload && sub == "/upload" {
            if req.method != "POST" {
                return Outcome::Resp(method_not_allowed("POST"));
            }
            return Outcome::Resp(crate::upload::upload_file(req, body, conf));
        }
        if conf.rm_enabled && sub == "/rm" {
            if req.method != "POST" {
                return Outcome::Resp(method_not_allowed("POST"));
            }
            return Outcome::Resp(crate::upload::rm_file(req, conf));
        }
        if req.method == "GET" || req.method == "HEAD" {
            return self.files_service(req, sub);
        }
        if conf.webdav_enabled && (req.method == "PROPFIND" || req.method == "OPTIONS") {
            return Outcome::Resp(crate::webdav::handle(req, body, conf, &self.root, sub));
        }
        self.error_404(req)
    }

    fn route(&self, req: &Request, body: &mut dyn Read) -> Outcome {
        let conf = &self.conf;
        let path = req.path.as_str();
        if req.method == "GET" && path == conf.healthcheck_route {
            return Outcome::Resp(Response::with_body(200, None, b"OK".to_vec()));
        }
        if req.method == "POST" && path == conf.api_route {
            return Outcome::Resp(crate::api::handle(req, body, conf));
        }
        if req.method == "GET" && path == conf.favicon_route {
            return Outcome::Resp(Response::with_body(200, Some("image/svg+xml"), FAVICON.to_vec()));
        }
        if req.method == "GET" && path == conf.css_route {
            return Outcome::Resp(Response::with_body(200, Some("text/css"), self.css.clone()));
        }
        let prefix = conf.route_prefix.as_str();
        let in_scope = prefix.is_empty() || path == prefix || path.starts_with(&format!("{prefix}/"));
        if in_scope {
            let sub = &path[prefix.len()..];
            return self.scope(req, body, sub);
        }
        self.error_404(req)
    }
}

pub fn io_status(e: &std::io::Error) -> u16 {
    match e.kind() {
        std::io::ErrorKind::NotFound => 404,
        std::io::ErrorKind::PermissionDenied => 403,
        _ => 500,
    }
}

impl Handler for App {
    fn handle(&self, req: &Request, body: &mut dyn Read) -> Response {
        let conf = &self.conf;
        let outcome = self.route(req, body);
        let mut resp = match outcome {
            Outcome::Err(r) => return r,
            Outcome::Resp(r) => r,
        };
        // custom headers
        for h in &conf.header {
            if !resp.has_header(&h.name) {
                resp.headers.push((h.name.clone(), h.value.clone()));
            }
        }
        // error page middleware
        if resp.status >= 400
            && req.path != "/upload"
            && resp.header("content-type") == Some(b"text/plain; charset=utf-8".as_slice())
        {
            if let Body::Bytes(b) | Body::Empty = &resp.body {
                let bytes: Vec<u8> = match &resp.body {
                    Body::Bytes(b) => b.clone(),
                    _ => Vec::new(),
                };
                let _ = b_unused(b_ref(&resp.body));
                if let Ok(msg) = String::from_utf8(bytes) {
                    let return_address = req.header_str("referer").unwrap_or("/").to_string();
                    let page = crate::render::render_error(&msg, resp.status, conf, &return_address);
                    resp.set_header("content-type", "text/html");
                    resp.body = Body::Bytes(page.into_bytes());
                }
            }
        }
        if conf.compress_response {
            resp = crate::compress::maybe_compress(req, resp);
        }
        resp
    }
}

fn b_ref(b: &Body) -> &Body {
    b
}
fn b_unused(_b: &Body) {}
