            match crate::auth::check_auth(req.header("authorization"), &conf.auth) {
                crate::auth::AuthResult::Ok(_) => {}
                crate::auth::AuthResult::Missing => {
                    let mut r = Response::new(401);
                    r.set_header("www-authenticate", "Basic");
                    return Outcome::Resp(r);
                }
                crate::auth::AuthResult::Invalid => {
                    return Outcome::Resp(RuntimeError::InvalidHttpCredentials.into_response());
                }
            }
        }
        if self.root.is_file() {
            if sub.is_empty() || sub == "/" {
                return match crate::files::serve_file(req, &self.root) {
                    Ok(r) => Outcome::Resp(r),
                    Err(e) => Outcome::Err(Response::text(io_status(&e), &e.to_string())),
                };
            }
            return self.error_404(req);
        }
        if conf.file_upload && sub == "/upload" {
            if req.method != "POST" {
                return Outcome::Resp(method_not_allowed("POST"));
            }
            return Outcome::Resp(crate::upload::upload_file(req, body, conf));
        }
        if conf.rm_enabled && sub == "/rm" {
            if req.method != "POST" {
                return Outcome::Resp(method_not_allowed("POST"));
            }
            return Outcome::Resp(crate::upload::rm_file(req, conf));
        }
        if req.method == "GET" || req.method == "HEAD" {
            return self.files_service(req, sub);
        }
        if conf.webdav_enabled && (req.method == "PROPFIND" || req.method == "OPTIONS") {
            return Outcome::Resp(crate::webdav::handle(req, body, conf, &self.root, sub));
        }
        self.error_404(req)
    }

    fn route(&self, req: &Request, body: &mut dyn Read) -> Outcome {
        let conf = &self.conf;
        let path = req.path.as_str();
        if req.method == "GET" && path == conf.healthcheck_route {
            return Outcome::Resp(Response::with_body(200, None, b"OK".to_vec()));
        }
        if req.method == "POST" && path == conf.api_route {
            return Outcome::Resp(crate::api::handle(req, body, conf));
        }
        if req.method == "GET" && path == conf.favicon_route {
            return Outcome::Resp(Response::with_body(200, Some("image/svg+xml"), FAVICON.to_vec()));
        }
        if req.method == "GET" && path == conf.css_route {
            return Outcome::Resp(Response::with_body(200, Some("text/css"), self.css.clone()));
        }
        let prefix = conf.route_prefix.as_str();
        let in_scope = prefix.is_empty() || path == prefix || path.starts_with(&format!("{prefix}/"));
        if in_scope {
            let sub = &path[prefix.len()..];
            return self.scope(req, body, sub);
        }
        self.error_404(req)
    }
}

pub fn io_status(e: &std::io::Error) -> u16 {
    match e.kind() {
        std::io::ErrorKind::NotFound => 404,
        std::io::ErrorKind::PermissionDenied => 403,
        _ => 500,
    }
}

impl Handler for App {
    fn handle(&self, req: &Request, body: &mut dyn Read) -> Response {
        let conf = &self.conf;
        let outcome = self.route(req, body);
        let mut resp = match outcome {
            Outcome::Err(r) => return r,
            Outcome::Resp(r) => r,
        };
        // custom headers
        for h in &conf.header {
            if !resp.has_header(&h.name) {
                resp.headers.push((h.name.clone(), h.value.clone()));
            }
        }
        // error page middleware
        if resp.status >= 400
            && req.path != "/upload"
            && resp.header("content-type") == Some(b"text/plain; charset=utf-8".as_slice())
        {
            if let Body::Bytes(b) | Body::Empty = &resp.body {
                let bytes: Vec<u8> = match &resp.body {
                    Body::Bytes(b) => b.clone(),
                    _ => Vec::new(),
                };
                let _ = b_unused(b_ref(&resp.body));
                if let Ok(msg) = String::from_utf8(bytes) {
                    let return_address = req.header_str("referer").unwrap_or("/").to_string();
                    let page = crate::render::render_error(&msg, resp.status, conf, &return_address);
                    resp.set_header("content-type", "text/html");
                    resp.body = Body::Bytes(page.into_bytes());
                }
            }
        }
        if conf.compress_response {
            resp = crate::compress::maybe_compress(req, resp);
        }
        resp
    }
}

fn b_ref(b: &Body) -> &Body {
    b
}
fn b_unused(_b: &Body) {}
