fn get_if_addrs() -> Vec<IpAddr> {
    let mut out = Vec::new();
    unsafe {
        let mut ifap: *mut libc::ifaddrs = std::ptr::null_mut();
        if libc::getifaddrs(&mut ifap) != 0 {
            return out;
        }
        let mut cur = ifap;
        while !cur.is_null() {
            let ifa = &*cur;
            if !ifa.ifa_addr.is_null() {
                let fam = (*ifa.ifa_addr).sa_family as i32;
                if fam == libc::AF_INET {
                    let sa = &*(ifa.ifa_addr as *const libc::sockaddr_in);
                    let ip = std::net::Ipv4Addr::from(u32::from_be(sa.sin_addr.s_addr));
                    out.push(IpAddr::V4(ip));
                } else if fam == libc::AF_INET6 {
                    let sa = &*(ifa.ifa_addr as *const libc::sockaddr_in6);
                    let ip = std::net::Ipv6Addr::from(sa.sin6_addr.s6_addr);
                    out.push(IpAddr::V6(ip));
                }
            }
            cur = ifa.ifa_next;
        }
        libc::freeifaddrs(ifap);
    }
    out
}

fn block_signals() -> libc::sigset_t {
    unsafe {
        let mut set: libc::sigset_t = std::mem::zeroed();
        libc::sigemptyset(&mut set);
        libc::sigaddset(&mut set, libc::SIGINT);
        libc::sigaddset(&mut set, libc::SIGTERM);
        libc::sigaddset(&mut set, libc::SIGQUIT);
        libc::pthread_sigmask(libc::SIG_BLOCK, &set, std::ptr::null_mut());
        set
    }
}

fn run(conf: MiniserveConfig) -> Result<(), StartupError> {
    if conf.no_symlinks && conf.path.is_symlink() {
        return Err(StartupError::NoSymlinksOptionWithSymlinkServePath(conf.path.to_string_lossy().to_string()));
    }
    if conf.webdav_enabled && conf.path.is_file() {
        return Err(StartupError::WebdavWithFileServePath(conf.path.to_string_lossy().to_string()));
    }
    let canon_path = conf
        .path
        .canonicalize()
        .map_err(|e| StartupError::Io("Failed to resolve path to be served".to_string(), e))?;

    if let Some(index) = &conf.index {
        if !canon_path.join(index).exists() {
            logger::warn(&format!(
                "The file '{}' provided for option --index could not be found.",
                index.to_string_lossy()
            ));
        }
    }
    let path_string = canon_path.to_string_lossy().to_string();

    println!("{} v{}", "miniserve".bold(), cli::VERSION);
    let _ = std::io::stdout().flush();
    let is_tty = std::io::stdout().is_terminal();
    if !conf.path_explicitly_chosen {
        if !is_tty {
            return Err(StartupError::NoExplicitPathAndNoTerminal);
        }
        logger::warn("miniserve has been invoked without an explicit path so it will serve the current directory after a short delay.");
        logger::warn("Invoke with -h|--help to see options or invoke as `miniserve .` to hide this advice.");
        print!("Starting server in ");
        std::io::stdout()
            .flush()
            .map_err(|e| StartupError::Io("Failed to write data".to_string(), e))?;
        for c in "3… 2… 1… \n".chars() {
            print!("{c}");
            std::io::stdout()
                .flush()
                .map_err(|e| StartupError::Io("Failed to write data".to_string(), e))?;
            std::thread::sleep(Duration::from_millis(500));
        }
    }

    let display_urls: Vec<String> = {
        let (mut ifaces, wildcard): (Vec<IpAddr>, Vec<IpAddr>) =
            conf.interfaces.iter().cloned().partition(|a| !a.is_unspecified());
        if !wildcard.is_empty() {
            let all_ipv4 = wildcard.iter().any(|a| a.is_ipv4());
            let all_ipv6 = wildcard.iter().any(|a| a.is_ipv6());
            ifaces = get_if_addrs()
                .into_iter()
                .filter(|ip| (all_ipv4 && ip.is_ipv4()) || (all_ipv6 && ip.is_ipv6()))
                .collect();
            ifaces.sort();
        }
        ifaces
            .into_iter()
            .map(|addr| match addr {
                IpAddr::V4(_) => format!("{}:{}", addr, conf.port),
                IpAddr::V6(_) => format!("[{}]:{}", addr, conf.port),
            })
            .map(|addr| if conf.tls.is_some() { format!("https://{addr}") } else { format!("http://{addr}") })
            .map(|url| format!("{}{}", url, conf.route_prefix))
            .collect()
    };

    let socket_addresses: Vec<SocketAddr> = conf.interfaces.iter().map(|&i| SocketAddr::new(i, conf.port)).collect();

    let workers = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);

    let sigset = block_signals();

    let mut listeners = Vec::new();
    for addr in &socket_addresses {
        let l = http::create_listener(*addr)
            .map_err(|e| StartupError::Io(format!("Failed to bind server to {addr}"), e))?;
        listeners.push((l, *addr));
    }

    logger::info(&format!("starting {workers} workers"));

    let display_sockets: Vec<String> = socket_addresses.iter().map(|s| s.to_string().green().bold().to_string()).collect();
    println!("Bound to {}", display_sockets.join(", "));
    println!("Serving path {}", path_string.yellow().bold());
    println!(
        "Available at (non-exhaustive list):\n    {}\n",
        display_urls.iter().map(|u| u.green().bold().to_string()).collect::<Vec<_>>().join("\n    ")
    );

    if conf.show_qrcode && is_tty {
        for url in display_urls.iter().filter(|u| !u.contains("//127.0.0.1:") && !u.contains("//[::1]:")) {
            println!("QR code for {}:", url.green().bold());
            qr::print_terminal(url);
        }
    }

    if is_tty {
        println!("Quit by pressing CTRL-C");
    }
    let _ = std::io::stdout().flush();

    let css = app::build_css(&conf.default_color_scheme, &conf.default_color_scheme_dark);
    let tls = conf.tls.as_ref().map(|t| t.acceptor.clone());
    let verbose = conf.verbose;
    let conf = Arc::new(conf);
    let opts = Arc::new(http::ServerOptions { verbose });

    logger::info("Actix runtime found; starting in Actix runtime");
    for (listener, addr) in listeners {
        logger::info(&format!(
            "starting service: \"actix-web-service-{addr}\", workers: {workers}, listening on: {addr}"
        ));
        let handler: Arc<dyn http::Handler> = Arc::new(app::App {
            conf: conf.clone(),
            root: canon_path.clone(),
            css: css.clone(),
            local_addr: addr.to_string(),
        });
        let tls = tls.clone();
        let opts = opts.clone();
        std::thread::spawn(move || http::serve_listener(listener, handler, tls, opts));
    }

    // wait for termination signals
    let mut sig: libc::c_int = 0;
    unsafe {
        libc::sigwait(&sigset, &mut sig);
    }
    let name = match sig {
        libc::SIGINT => "SIGINT",
        libc::SIGTERM => "SIGTERM",
        _ => "SIGQUIT",
    };
    if sig == libc::SIGQUIT {
        logger::info(&format!("{name} received; starting forced shutdown"));
    } else {
        logger::info(&format!("{name} received; starting graceful shutdown"));
    }
    logger::info("accept thread stopped");
    for _ in 0..workers {
        logger::info("shutting down idle worker");
    }
    let _ = std::io::stdout().flush();
    std::process::exit(0);
}
