//! Response compression (gzip, deflate, brotli, zstd).

use std::io::Write;

use crate::http::{Body, Request, Response};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Encoding {
    Br,
    Zstd,
    Gzip,
    Deflate,
    Identity,
}

impl Encoding {
    fn name(&self) -> &'static str {
        match self {
            Encoding::Br => "br",
            Encoding::Zstd => "zstd",
            Encoding::Gzip => "gzip",
            Encoding::Deflate => "deflate",
            Encoding::Identity => "identity",
        }
    }
    fn rank(&self) -> u8 {
        match self {
            Encoding::Br => 0,
            Encoding::Zstd => 1,
            Encoding::Gzip => 2,
            Encoding::Deflate => 3,
            Encoding::Identity => 4,
        }
    }
}

pub fn negotiate(header: Option<&str>) -> Encoding {
    let h = match header {
        Some(h) => h,
        None => return Encoding::Identity,
    };
    let mut best: Option<(u32, Encoding)> = None;
    for item in h.split(',') {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        let mut parts = item.split(';');
        let name = parts.next().unwrap_or("").trim().to_ascii_lowercase();
        let mut q: u32 = 1000;
        for p in parts {
            let p = p.trim();
            if let Some(v) = p.strip_prefix("q=").or_else(|| p.strip_prefix("Q=")) {
                q = match v.trim().parse::<f32>() {
                    Ok(f) if (0.0..=1.0).contains(&f) => (f * 1000.0).round() as u32,
                    _ => 0,
                };
            }
        }
        let enc = match name.as_str() {
            "br" => Encoding::Br,
            "zstd" => Encoding::Zstd,
            "gzip" | "x-gzip" => Encoding::Gzip,
            "deflate" => Encoding::Deflate,
            "identity" | "*" => Encoding::Identity,
            _ => continue,
        };
        if q == 0 {
            continue;
        }
        best = match best {
            None => Some((q, enc)),
            Some((bq, be)) => {
                if q > bq || (q == bq && enc.rank() < be.rank()) {
                    Some((q, enc))
                } else {
                    Some((bq, be))
                }
            }
        };
    }
    best.map(|b| b.1).unwrap_or(Encoding::Identity)
}

/// Brotli stream made of uncompressed meta-blocks.
pub fn brotli_store(data: &[u8], out: &mut dyn Write) -> std::io::Result<()> {
    // WBITS = 22: first bit 1, then 3 bits value 5
    // bits (LSB first): 1, 1,0,1
    let mut first = true;
    let mut buf: Vec<u8> = Vec::new();
    for chunk in data.chunks(65536) {
        let mlen1 = (chunk.len() - 1) as u32;
        let mut bits: u64 = 0;
        let mut n = 0;
        let mut push = |v: u64, w: u32, bits: &mut u64, n: &mut u32| {
            *bits |= v << *n;
            *n += w;
        };
        let mut nb: u32 = 0;
        if first {
            push(1, 1, &mut bits, &mut nb);
            push(5, 3, &mut bits, &mut nb);
            first = false;
        }
        push(0, 1, &mut bits, &mut nb); // ISLAST = 0
        push(0, 2, &mut bits, &mut nb); // MNIBBLES = 4
        push(mlen1 as u64, 16, &mut bits, &mut nb);
        push(1, 1, &mut bits, &mut nb); // ISUNCOMPRESSED
        n += nb;
        let bytes = (n + 7) / 8;
        for i in 0..bytes {
            buf.push((bits >> (8 * i)) as u8);
        }
        buf.extend_from_slice(chunk);
        if buf.len() > 1 << 20 {
            out.write_all(&buf)?;
            buf.clear();
        }
    }
    // final empty last meta-block: ISLAST=1, ISLASTEMPTY=1
    if first {
        // header + last
        // bits: 1, 101, 1, 1 => value = 1 | 5<<1 | 1<<4 | 1<<5 = 0x3b
        buf.push(0x3b);
    } else {
        buf.push(0x03);
    }
    out.write_all(&buf)
}

/// zstd frame made of raw blocks.
pub fn zstd_store(data: &[u8], out: &mut dyn Write) -> std::io::Result<()> {
    let mut buf: Vec<u8> = Vec::with_capacity(data.len() + 64);
    buf.extend_from_slice(&[0x28, 0xB5, 0x2F, 0xFD]);
    buf.push(0x00); // frame header descriptor
    buf.push(0x38); // window descriptor: 128 KiB
    const MAX: usize = 128 * 1024;
    if data.is_empty() {
        buf.extend_from_slice(&[0x01, 0x00, 0x00]);
    } else {
        let chunks: Vec<&[u8]> = data.chunks(MAX).collect();
        for (i, c) in chunks.iter().enumerate() {
            let last = if i + 1 == chunks.len() { 1u32 } else { 0 };
            let h = last | ((c.len() as u32) << 3);
            buf.push(h as u8);
            buf.push((h >> 8) as u8);
            buf.push((h >> 16) as u8);
            buf.extend_from_slice(c);
        }
    }
    out.write_all(&buf)
}

fn encode_all(enc: Encoding, data: &[u8], out: &mut dyn Write) -> std::io::Result<()> {
    match enc {
        Encoding::Gzip => {
            let mut e = flate2::write::GzEncoder::new(out, flate2::Compression::default());
            e.write_all(data)?;
            e.finish()?;
            Ok(())
        }
        Encoding::Deflate => {
            let mut e = flate2::write::ZlibEncoder::new(out, flate2::Compression::default());
            e.write_all(data)?;
            e.finish()?;
            Ok(())
        }
        Encoding::Br => brotli_store(data, out),
        Encoding::Zstd => zstd_store(data, out),
        Encoding::Identity => out.write_all(data),
    }
}

pub fn maybe_compress(req: &Request, mut resp: Response) -> Response {
    let enc = negotiate(req.header_str("accept-encoding"));
    if enc == Encoding::Identity {
        return resp;
    }
    if resp.has_header("content-encoding") || resp.status == 101 || resp.status == 204 || resp.status == 304 {
        return resp;
    }
    match &resp.body {
        Body::Empty | Body::NoBody => return resp,
        Body::Bytes(b) if b.is_empty() => return resp,
        Body::File(_, _, 0) => return resp,
        _ => {}
    }
    let body = std::mem::replace(&mut resp.body, Body::Empty);
    resp.set_header("vary", "accept-encoding");
    resp.set_header("content-encoding", enc.name());
    resp.body = Body::Stream(Box::new(move |w: &mut dyn Write| {
        let data: Vec<u8> = match body {
            Body::Bytes(b) => b,
            Body::File(mut f, off, len) => {
                use std::io::{Read, Seek};
                f.seek(std::io::SeekFrom::Start(off))?;
                let mut v = Vec::with_capacity(len as usize);
                f.take(len).read_to_end(&mut v)?;
                v
            }
            Body::Stream(s) => {
                let mut v: Vec<u8> = Vec::new();
                s(&mut v)?;
                v
            }
            _ => Vec::new(),
        };
        encode_all(enc, &data, w)
    }));
    resp
}
