            self.out.write_all(&vec![0u8; 512 - rem])?;
        }
        Ok(())
    }
}

fn path_join_str(base: &str, rel: &Path) -> String {
    let rel_s = rel.to_string_lossy();
    if rel_s.is_empty() {
        format!("{base}/")
    } else {
        format!("{base}/{rel_s}")
    }
}

fn tar_dir(out: &mut dyn Write, src_dir: &Path, skip_symlinks: bool) -> Result<(), RuntimeError> {
    let inner_folder = src_dir
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .ok_or_else(|| RuntimeError::InvalidPath("Directory name terminates in \"..\"".to_string()))?;
    let follow = !skip_symlinks;
    let mut tw = TarWriter { out };
    let wrap = |e: io::Error| {
        RuntimeError::Io(
            format!("Failed to append the content of {}/ to the TAR archive", src_dir.display()),
            e,
        )
    };
    let mut stack: Vec<(PathBuf, bool, bool)> = vec![(src_dir.to_path_buf(), true, false)];
    while let Some((src, is_dir, is_symlink)) = stack.pop() {
        let rel = src.strip_prefix(src_dir).unwrap_or(Path::new(""));
        let dest = path_join_str(&inner_folder, rel);
        if is_dir || (is_symlink && follow && src.is_dir()) {
            for entry in fs::read_dir(&src).map_err(wrap)? {
                let entry = entry.map_err(wrap)?;
                let ft = entry.file_type().map_err(wrap)?;
                stack.push((entry.path(), ft.is_dir(), ft.is_symlink()));
            }
            let md = if follow { fs::metadata(&src) } else { fs::symlink_metadata(&src) }.map_err(wrap)?;
            tw.header(&dest, &md, b'5', 0, None).map_err(wrap)?;
        } else if !follow && is_symlink {
            let md = fs::symlink_metadata(&src).map_err(wrap)?;
            let link = fs::read_link(&src).map_err(wrap)?;
            let ls = link.to_string_lossy().to_string();
            tw.header(&dest, &md, b'2', 0, Some(&ls)).map_err(wrap)?;
        } else {
            let mut f = fs::File::open(&src).map_err(wrap)?;
            tw.append_file(&dest, &mut f).map_err(wrap)?;
        }
    }
    tw.out
        .write_all(&[0u8; 1024])
        .map_err(|e| RuntimeError::Io("Failed to finish writing the TAR archive".to_string(), e))?;
    Ok(())
}

// ---------------- ZIP ----------------

fn crc32(data: &[u8]) -> u32 {
    let mut h = crc32_table();
    let _ = &mut h;
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc = h[((crc ^ b as u32) & 0xff) as usize] ^ (crc >> 8);
    }
    !crc
}

fn crc32_table() -> [u32; 256] {
    let mut t = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
        }
        t[i as usize] = c;
    }
    t
}

struct ZipEntry {
    name: String,
    crc: u32,
    size: u64,
    offset: u64,
    is_dir: bool,
}

struct ZipBuilder {
    buf: Vec<u8>,
    entries: Vec<ZipEntry>,
}

impl ZipBuilder {
    fn put16(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    fn put32(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_le_bytes());
    }
    fn add(&mut self, name: String, data: &[u8], is_dir: bool) {
        let offset = self.buf.len() as u64;
        let crc = if is_dir { 0 } else { crc32(data) };
        let version: u16 = if is_dir { 20 } else { 10 };
        self.put32(0x0403_4b50);
        self.put16(version);
        self.put16(0); // flags
        self.put16(0); // method stored
        self.put16(0); // time
        self.put16(0x21); // date 1980-01-01
        self.put32(crc);
        self.put32(data.len() as u32);
        self.put32(data.len() as u32);
        self.put16(name.len() as u16);
        self.put16(0);
        self.buf.extend_from_slice(name.as_bytes());
        self.buf.extend_from_slice(data);
        self.entries.push(ZipEntry { name, crc, size: data.len() as u64, offset, is_dir });
    }
    fn finish(mut self) -> Vec<u8> {
        let cd_start = self.buf.len() as u64;
        let entries = std::mem::take(&mut self.entries);
        for e in &entries {
            let version: u16 = if e.is_dir { 20 } else { 10 };
            self.put32(0x0201_4b50);
            self.put16(0x0300 | version);
            self.put16(version);
            self.put16(0);
            self.put16(0);
            self.put16(0);
            self.put16(0x21);
            self.put32(e.crc);
            self.put32(e.size as u32);
            self.put32(e.size as u32);
            self.put16(e.name.len() as u16);
            self.put16(0);
            self.put16(0);
            self.put16(0);
            self.put16(0);
            let mode: u32 = if e.is_dir { 0o40755 } else { 0o100644 };
            self.put32(mode << 16);
            self.put32(e.offset as u32);
            self.buf.extend_from_slice(e.name.as_bytes());
        }
        let cd_size = self.buf.len() as u64 - cd_start;
        self.put32(0x0605_4b50);
        self.put16(0);
        self.put16(0);
        self.put16(entries.len() as u16);
        self.put16(entries.len() as u16);
        self.put32(cd_size as u32);
        self.put32(cd_start as u32);
        self.put16(0);
        self.buf
    }
}

fn zip_dir(out: &mut dyn Write, directory: &Path, _skip_symlinks: bool) -> Result<(), RuntimeError> {
    let detail = |m: &str| RuntimeError::ArchiveCreationDetail(m.to_string());
    let zip_root = directory
        .file_name()
        .ok_or_else(|| detail("Directory name terminates in \"..\""))?
        .to_string_lossy()
        .to_string();
    let wrap = |e: RuntimeError| RuntimeError::ArchiveCreation("Failed to create the ZIP archive".to_string(), Box::new(e));
    let mut zb = ZipBuilder { buf: Vec::new(), entries: Vec::new() };
    let mut queue: Vec<PathBuf> = vec![directory.to_path_buf()];
    while let Some(current) = queue.pop() {
        let rd = fs::read_dir(&current).map_err(|e| wrap(RuntimeError::Io("Could not read directory".to_string(), e)))?;
        let rel = current.strip_prefix(directory).unwrap_or(Path::new(""));
        let zip_dir_name = if rel.as_os_str().is_empty() {
            zip_root.clone()
        } else {
            format!("{}/{}", zip_root, rel.to_string_lossy())
        };
        for entry in rd {
            let entry = entry.map_err(|e| wrap(RuntimeError::Io("Could not read directory entry".to_string(), e)))?;
            let entry_path = entry.path();
            let md = fs::metadata(&entry_path).map_err(|e| wrap(RuntimeError::Io("Could not get file metadata".to_string(), e)))?;
            let name = entry_path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let rel_name = format!("{zip_dir_name}/{name}");
            if md.is_file() {
                let mut data = Vec::new();
                fs::File::open(&entry_path)
                    .and_then(|mut f| f.read_to_end(&mut data))
                    .map_err(|e| wrap(RuntimeError::Io("Could not read file".to_string(), e)))?;
                zb.add(rel_name, &data, false);
            } else if md.is_dir() {
                zb.add(format!("{rel_name}/"), &[], true);
                queue.push(entry_path);
            }
        }
    }
    let data = zb.finish();
    out.write_all(&data)
        .map_err(|e| wrap(RuntimeError::Io("Failed to write the ZIP archive".to_string(), e)))?;
    Ok(())
}
