//! QR code generation (byte mode, error correction level L) with SVG output.

const ECC_CODEWORDS_PER_BLOCK_L: [i32; 41] = [
    -1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30,
    30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30,
];
const NUM_ERROR_CORRECTION_BLOCKS_L: [i32; 41] = [
    -1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18,
    19, 19, 20, 21, 22, 24, 25,
];

pub struct QrCode {
    pub size: i32,
    modules: Vec<bool>,
    is_function: Vec<bool>,
}

fn num_raw_data_modules(ver: i32) -> i32 {
    let mut result = (16 * ver + 128) * ver + 64;
    if ver >= 2 {
        let numalign = ver / 7 + 2;
        result -= (25 * numalign - 10) * numalign - 55;
        if ver >= 7 {
            result -= 36;
        }
    }
    result
}

fn num_data_codewords(ver: i32) -> usize {
    (num_raw_data_modules(ver) / 8
        - ECC_CODEWORDS_PER_BLOCK_L[ver as usize] * NUM_ERROR_CORRECTION_BLOCKS_L[ver as usize]) as usize
}

fn rs_multiply(x: u8, y: u8) -> u8 {
    let mut z: i32 = 0;
    for i in (0..8).rev() {
        z = (z << 1) ^ ((z >> 7) * 0x11D);
        z ^= ((y as i32 >> i) & 1) * x as i32;
    }
    z as u8
}

fn rs_divisor(degree: usize) -> Vec<u8> {
    let mut result = vec![0u8; degree];
    result[degree - 1] = 1;
    let mut root: u8 = 1;
    for _ in 0..degree {
        for j in 0..degree {
            result[j] = rs_multiply(result[j], root);
            if j + 1 < degree {
                result[j] ^= result[j + 1];
            }
        }
        root = rs_multiply(root, 0x02);
    }
    result
}

fn rs_remainder(data: &[u8], divisor: &[u8]) -> Vec<u8> {
    let mut result = vec![0u8; divisor.len()];
    for &b in data {
        let factor = b ^ result[0];
        result.remove(0);
        result.push(0);
        for (x, &y) in result.iter_mut().zip(divisor.iter()) {
            *x ^= rs_multiply(y, factor);
        }
    }
    result
}

impl QrCode {
    fn get(&self, x: i32, y: i32) -> bool {
        self.modules[(y * self.size + x) as usize]
    }
    fn set_function(&mut self, x: i32, y: i32, dark: bool) {
        let i = (y * self.size + x) as usize;
        self.modules[i] = dark;
        self.is_function[i] = true;
    }

    pub fn encode(text: &[u8]) -> Option<QrCode> {
        // choose version
        let mut version = 0;
        for v in 1..=40 {
            let cc_bits = if v <= 9 { 8 } else { 16 };
            let needed = 4 + cc_bits + text.len() * 8;
            if needed <= num_data_codewords(v) * 8 {
                version = v;
                break;
            }
        }
        if version == 0 {
            return None;
        }
        let cc_bits = if version <= 9 { 8 } else { 16 };
        let mut bits: Vec<bool> = Vec::new();
        let mut append = |val: u32, len: usize, bits: &mut Vec<bool>| {
            for i in (0..len).rev() {
                bits.push((val >> i) & 1 != 0);
            }
        };
        append(4, 4, &mut bits);
        append(text.len() as u32, cc_bits, &mut bits);
        for &b in text {
            append(b as u32, 8, &mut bits);
        }
        let capacity = num_data_codewords(version) * 8;
        let term = std::cmp::min(4, capacity - bits.len());
        append(0, term, &mut bits);
        let pad = (8 - bits.len() % 8) % 8;
        append(0, pad, &mut bits);
        let mut pad_byte = 0xEC;
        while bits.len() < capacity {
            append(pad_byte, 8, &mut bits);
            pad_byte ^= 0xEC ^ 0x11;
        }
        let mut data = vec![0u8; bits.len() / 8];
        for (i, &b) in bits.iter().enumerate() {
            if b {
                data[i >> 3] |= 1 << (7 - (i & 7));
            }
        }
        let mut qr = QrCode {
            size: version * 4 + 17,
            modules: vec![false; ((version * 4 + 17) * (version * 4 + 17)) as usize],
            is_function: vec![false; ((version * 4 + 17) * (version * 4 + 17)) as usize],
        };
        qr.draw_function_patterns(version);
        let all = qr.add_ecc_and_interleave(&data, version);
        qr.draw_codewords(&all);
        // choose mask
        let mut best_mask = 0;
        let mut min_penalty = i32::MAX;
        for m in 0..8 {
            qr.apply_mask(m);
            qr.draw_format_bits(m);
            let p = qr.penalty_score();
            if p < min_penalty {
                best_mask = m;
                min_penalty = p;
            }
            qr.apply_mask(m);
        }
        qr.apply_mask(best_mask);
        qr.draw_format_bits(best_mask);
        qr.is_function.clear();
        Some(qr)
    }

    fn draw_function_patterns(&mut self, version: i32) {
        for i in 0..self.size {
            self.set_function(6, i, i % 2 == 0);
            self.set_function(i, 6, i % 2 == 0);
        }
        self.draw_finder(3, 3);
        self.draw_finder(self.size - 4, 3);
        self.draw_finder(3, self.size - 4);
        let align = self.alignment_positions(version);
        let n = align.len();
        for i in 0..n {
            for j in 0..n {
                if (i == 0 && j == 0) || (i == 0 && j == n - 1) || (i == n - 1 && j == 0) {
                    continue;
                }
                self.draw_alignment(align[i], align[j]);
            }
        }
        self.draw_format_bits(0);
        self.draw_version(version);
    }

    fn alignment_positions(&self, version: i32) -> Vec<i32> {
        if version == 1 {
            return vec![];
        }
        let numalign = version / 7 + 2;
        let step = if version == 32 { 26 } else { (version * 4 + numalign * 2 + 1) / (numalign * 2 - 2) * 2 };
        let mut result: Vec<i32> = (0..numalign - 1).map(|i| self.size - 7 - i * step).collect();
        result.push(6);
        result.reverse();
        result
    }

    fn draw_finder(&mut self, x: i32, y: i32) {
        for dy in -4..=4 {
            for dx in -4..=4 {
                let xx = x + dx;
                let yy = y + dy;
                if 0 <= xx && xx < self.size && 0 <= yy && yy < self.size {
                    let dist = std::cmp::max(dx.abs(), dy.abs());
                    self.set_function(xx, yy, dist != 2 && dist != 4);
