        for i in 0..18 {
            let bit = (bits >> i) & 1 != 0;
            let a = self.size - 11 + i % 3;
            let b = i / 3;
            self.set_function(a, b, bit);
            self.set_function(b, a, bit);
        }
    }

    fn add_ecc_and_interleave(&self, data: &[u8], version: i32) -> Vec<u8> {
        let numblocks = NUM_ERROR_CORRECTION_BLOCKS_L[version as usize] as usize;
        let blockecclen = ECC_CODEWORDS_PER_BLOCK_L[version as usize] as usize;
        let rawcodewords = (num_raw_data_modules(version) / 8) as usize;
        let numshortblocks = numblocks - rawcodewords % numblocks;
        let shortblocklen = rawcodewords / numblocks;
        let mut blocks: Vec<Vec<u8>> = Vec::with_capacity(numblocks);
        let rsdiv = rs_divisor(blockecclen);
        let mut k = 0;
        for i in 0..numblocks {
            let datlen = shortblocklen - blockecclen + if i < numshortblocks { 0 } else { 1 };
            let mut dat = data[k..k + datlen].to_vec();
            k += datlen;
            let ecc = rs_remainder(&dat, &rsdiv);
            if i < numshortblocks {
                dat.push(0);
            }
            dat.extend_from_slice(&ecc);
            blocks.push(dat);
        }
        let mut result = Vec::with_capacity(rawcodewords);
        for i in 0..blocks[0].len() {
            for (j, block) in blocks.iter().enumerate() {
                if i != shortblocklen - blockecclen || j >= numshortblocks {
                    result.push(block[i]);
                }
            }
        }
        result
    }

    fn draw_codewords(&mut self, data: &[u8]) {
        let mut i: usize = 0;
        let mut right = self.size - 1;
        while right >= 1 {
            if right == 6 {
                right = 5;
            }
            for vert in 0..self.size {
                for j in 0..2 {
                    let x = right - j;
                    let upward = (right + 1) & 2 == 0;
                    let y = if upward { self.size - 1 - vert } else { vert };
                    let idx = (y * self.size + x) as usize;
                    if !self.is_function[idx] && i < data.len() * 8 {
                        self.modules[idx] = (data[i >> 3] >> (7 - (i & 7))) & 1 != 0;
                        i += 1;
                    }
                }
            }
            right -= 2;
        }
    }

    fn apply_mask(&mut self, mask: i32) {
        for y in 0..self.size {
            for x in 0..self.size {
                let invert = match mask {
                    0 => (x + y) % 2 == 0,
                    1 => y % 2 == 0,
                    2 => x % 3 == 0,
                    3 => (x + y) % 3 == 0,
                    4 => (x / 3 + y / 2) % 2 == 0,
                    5 => x * y % 2 + x * y % 3 == 0,
                    6 => (x * y % 2 + x * y % 3) % 2 == 0,
                    _ => ((x + y) % 2 + x * y % 3) % 2 == 0,
                };
                let idx = (y * self.size + x) as usize;
                if invert && !self.is_function[idx] {
                    self.modules[idx] = !self.modules[idx];
                }
            }
        }
    }

    fn penalty_score(&self) -> i32 {
        let mut result = 0;
        let size = self.size;
        // rows
        for y in 0..size {
            let mut run_color = false;
            let mut run_x = 0;
            let mut history = [0i32; 7];
            for x in 0..size {
                if self.get(x, y) == run_color {
                    run_x += 1;
                    if run_x == 5 {
                        result += 3;
                    } else if run_x > 5 {
                        result += 1;
                    }
                } else {
                    self.finder_history_add(run_x, &mut history);
                    if !run_color {
                        result += self.finder_count_patterns(&history) * 40;
                    }
                    run_color = self.get(x, y);
                    run_x = 1;
                }
            }
            result += self.finder_terminate(run_color, run_x, &mut history) * 40;
        }
        for x in 0..size {
            let mut run_color = false;
            let mut run_y = 0;
            let mut history = [0i32; 7];
            for y in 0..size {
                if self.get(x, y) == run_color {
                    run_y += 1;
                    if run_y == 5 {
                        result += 3;
                    } else if run_y > 5 {
                        result += 1;
                    }
                } else {
                    self.finder_history_add(run_y, &mut history);
                    if !run_color {
                        result += self.finder_count_patterns(&history) * 40;
                    }
                    run_color = self.get(x, y);
                    run_y = 1;
                }
            }
            result += self.finder_terminate(run_color, run_y, &mut history) * 40;
        }
        for y in 0..size - 1 {
            for x in 0..size - 1 {
                let c = self.get(x, y);
                if c == self.get(x + 1, y) && c == self.get(x, y + 1) && c == self.get(x + 1, y + 1) {
                    result += 3;
                }
            }
        }
        let dark: i32 = self.modules.iter().filter(|&&m| m).count() as i32;
        let total = size * size;
        let k = ((dark * 20 - total * 10).abs() + total - 1) / total - 1;
        result += k * 10;
        result
    }

    fn finder_count_patterns(&self, h: &[i32; 7]) -> i32 {
        let n = h[1];
        let core = n > 0 && h[2] == n && h[3] == n * 3 && h[4] == n && h[5] == n;
        (if core && h[0] >= n * 4 && h[6] >= n { 1 } else { 0 })
            + (if core && h[6] >= n * 4 && h[0] >= n { 1 } else { 0 })
    }

    fn finder_terminate(&self, run_color: bool, mut run: i32, h: &mut [i32; 7]) -> i32 {
        if run_color {
            self.finder_history_add(run, h);
            run = 0;
        }
        run += self.size;
        self.finder_history_add(run, h);
        self.finder_count_patterns(h)
    }

    fn finder_history_add(&self, mut run: i32, h: &mut [i32; 7]) {
        if h[0] == 0 {
            run += self.size;
        }
        h.copy_within(0..6, 1);
        h[0] = run;
    }
}

/// SVG with a one-module margin like fast_qr's SvgBuilder.
pub fn svg_for(text: &str) -> String {
    let qr = match QrCode::encode(text.as_bytes()) {
        Some(q) => q,
        None => return String::new(),
    };
    let margin = 1;
    let n = qr.size + margin * 2;
    let mut out = format!(
        "<svg viewBox=\"0 0 {n} {n}\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"{n}px\" height=\"{n}px\" fill=\"#ffffff\"/><path d=\""
    );
    for y in 0..qr.size {
        for x in 0..qr.size {
            if qr.get(x, y) {
                out.push_str(&format!("M{},{}h1v1h-1", x + margin, y + margin));
            }
        }
    }
    out.push_str("\" fill=\"#000000\"/></svg>");
    out
}

/// Print the QR code to the terminal using half block characters.
pub fn print_terminal(text: &str) {
