//! QR code generation (byte mode, error correction level L) with SVG output.

const ECC_CODEWORDS_PER_BLOCK_L: [i32; 41] = [
    -1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30,
    30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30,
];
const NUM_ERROR_CORRECTION_BLOCKS_L: [i32; 41] = [
    -1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18,
    19, 19, 20, 21, 22, 24, 25,
];

pub struct QrCode {
    pub size: i32,
    modules: Vec<bool>,
    is_function: Vec<bool>,
}

fn num_raw_data_modules(ver: i32) -> i32 {
    let mut result = (16 * ver + 128) * ver + 64;
    if ver >= 2 {
        let numalign = ver / 7 + 2;
        result -= (25 * numalign - 10) * numalign - 55;
        if ver >= 7 {
            result -= 36;
        }
    }
    result
}

fn num_data_codewords(ver: i32) -> usize {
    (num_raw_data_modules(ver) / 8
        - ECC_CODEWORDS_PER_BLOCK_L[ver as usize] * NUM_ERROR_CORRECTION_BLOCKS_L[ver as usize]) as usize
}

fn rs_multiply(x: u8, y: u8) -> u8 {
    let mut z: i32 = 0;
    for i in (0..8).rev() {
        z = (z << 1) ^ ((z >> 7) * 0x11D);
        z ^= ((y as i32 >> i) & 1) * x as i32;
    }
    z as u8
}

fn rs_divisor(degree: usize) -> Vec<u8> {
    let mut result = vec![0u8; degree];
    result[degree - 1] = 1;
    let mut root: u8 = 1;
    for _ in 0..degree {
        for j in 0..degree {
            result[j] = rs_multiply(result[j], root);
            if j + 1 < degree {
                result[j] ^= result[j + 1];
            }
        }
        root = rs_multiply(root, 0x02);
    }
    result
}

fn rs_remainder(data: &[u8], divisor: &[u8]) -> Vec<u8> {
    let mut result = vec![0u8; divisor.len()];
    for &b in data {
        let factor = b ^ result[0];
        result.remove(0);
        result.push(0);
        for (x, &y) in result.iter_mut().zip(divisor.iter()) {
            *x ^= rs_multiply(y, factor);
        }
    }
    result
}

impl QrCode {
    fn get(&self, x: i32, y: i32) -> bool {
        self.modules[(y * self.size + x) as usize]
    }
    fn set_function(&mut self, x: i32, y: i32, dark: bool) {
        let i = (y * self.size + x) as usize;
        self.modules[i] = dark;
        self.is_function[i] = true;
    }

    pub fn encode(text: &[u8]) -> Option<QrCode> {
        // choose version
        let mut version = 0;
        for v in 1..=40 {
            let cc_bits = if v <= 9 { 8 } else { 16 };
            let needed = 4 + cc_bits + text.len() * 8;
            if needed <= num_data_codewords(v) * 8 {
                version = v;
                break;
            }
        }
        if version == 0 {
            return None;
        }
        let cc_bits = if version <= 9 { 8 } else { 16 };
        let mut bits: Vec<bool> = Vec::new();
        let mut append = |val: u32, len: usize, bits: &mut Vec<bool>| {
            for i in (0..len).rev() {
                bits.push((val >> i) & 1 != 0);
            }
        };
        append(4, 4, &mut bits);
        append(text.len() as u32, cc_bits, &mut bits);
        for &b in text {
            append(b as u32, 8, &mut bits);
        }
        let capacity = num_data_codewords(version) * 8;
        let term = std::cmp::min(4, capacity - bits.len());
        append(0, term, &mut bits);
        let pad = (8 - bits.len() % 8) % 8;
        append(0, pad, &mut bits);
        let mut pad_byte = 0xEC;
        while bits.len() < capacity {
            append(pad_byte, 8, &mut bits);
            pad_byte ^= 0xEC ^ 0x11;
        }
        let mut data = vec![0u8; bits.len() / 8];
        for (i, &b) in bits.iter().enumerate() {
            if b {
                data[i >> 3] |= 1 << (7 - (i & 7));
            }
        }
        let mut qr = QrCode {
            size: version * 4 + 17,
            modules: vec![false; ((version * 4 + 17) * (version * 4 + 17)) as usize],
            is_function: vec![false; ((version * 4 + 17) * (version * 4 + 17)) as usize],
        };
        qr.draw_function_patterns(version);
        let all = qr.add_ecc_and_interleave(&data, version);
        qr.draw_codewords(&all);
        // choose mask
        let mut best_mask = 0;
        let mut min_penalty = i32::MAX;
        for m in 0..8 {
            qr.apply_mask(m);
            qr.draw_format_bits(m);
            let p = qr.penalty_score();
            if p < min_penalty {
                best_mask = m;
                min_penalty = p;
            }
            qr.apply_mask(m);
        }
        qr.apply_mask(best_mask);
        qr.draw_format_bits(best_mask);
        qr.is_function.clear();
        Some(qr)
    }

    fn draw_function_patterns(&mut self, version: i32) {
        for i in 0..self.size {
            self.set_function(6, i, i % 2 == 0);
            self.set_function(i, 6, i % 2 == 0);
        }
        self.draw_finder(3, 3);
        self.draw_finder(self.size - 4, 3);
        self.draw_finder(3, self.size - 4);
        let align = self.alignment_positions(version);
        let n = align.len();
        for i in 0..n {
            for j in 0..n {
                if (i == 0 && j == 0) || (i == 0 && j == n - 1) || (i == n - 1 && j == 0) {
                    continue;
                }
                self.draw_alignment(align[i], align[j]);
            }
        }
        self.draw_format_bits(0);
        self.draw_version(version);
    }

    fn alignment_positions(&self, version: i32) -> Vec<i32> {
        if version == 1 {
            return vec![];
        }
        let numalign = version / 7 + 2;
        let step = if version == 32 { 26 } else { (version * 4 + numalign * 2 + 1) / (numalign * 2 - 2) * 2 };
        let mut result: Vec<i32> = (0..numalign - 1).map(|i| self.size - 7 - i * step).collect();
        result.push(6);
        result.reverse();
        result
    }

    fn draw_finder(&mut self, x: i32, y: i32) {
        for dy in -4..=4 {
            for dx in -4..=4 {
                let xx = x + dx;
                let yy = y + dy;
                if 0 <= xx && xx < self.size && 0 <= yy && yy < self.size {
                    let dist = std::cmp::max(dx.abs(), dy.abs());
                    self.set_function(xx, yy, dist != 2 && dist != 4);
                }
            }
        }
    }

    fn draw_alignment(&mut self, x: i32, y: i32) {
        for dy in -2..=2 {
            for dx in -2..=2 {
                self.set_function(x + dx, y + dy, std::cmp::max(dx.abs(), dy.abs()) != 1);
            }
        }
    }

    fn draw_format_bits(&mut self, mask: i32) {
        // ECL L format bits = 1
        let data: i32 = (1 << 3) | mask;
        let mut rem = data;
        for _ in 0..10 {
            rem = (rem << 1) ^ ((rem >> 9) * 0x537);
        }
        let bits = (data << 10 | rem) ^ 0x5412;
        let get = |i: i32| (bits >> i) & 1 != 0;
        for i in 0..6 {
            self.set_function(8, i, get(i));
        }
        self.set_function(8, 7, get(6));
        self.set_function(8, 8, get(7));
        self.set_function(7, 8, get(8));
        for i in 9..15 {
            self.set_function(14 - i, 8, get(i));
        }
        let size = self.size;
        for i in 0..8 {
            self.set_function(size - 1 - i, 8, get(i));
        }
        for i in 8..15 {
            self.set_function(8, size - 15 + i, get(i));
        }
        self.set_function(8, size - 8, true);
    }

    fn draw_version(&mut self, version: i32) {
        if version < 7 {
            return;
        }
        let mut rem = version;
        for _ in 0..12 {
            rem = (rem << 1) ^ ((rem >> 11) * 0x1F25);
        }
        let bits = version << 12 | rem;
        for i in 0..18 {
            let bit = (bits >> i) & 1 != 0;
            let a = self.size - 11 + i % 3;
            let b = i / 3;
            self.set_function(a, b, bit);
            self.set_function(b, a, bit);
        }
    }

    fn add_ecc_and_interleave(&self, data: &[u8], version: i32) -> Vec<u8> {
        let numblocks = NUM_ERROR_CORRECTION_BLOCKS_L[version as usize] as usize;
        let blockecclen = ECC_CODEWORDS_PER_BLOCK_L[version as usize] as usize;
        let rawcodewords = (num_raw_data_modules(version) / 8) as usize;
        let numshortblocks = numblocks - rawcodewords % numblocks;
        let shortblocklen = rawcodewords / numblocks;
        let mut blocks: Vec<Vec<u8>> = Vec::with_capacity(numblocks);
        let rsdiv = rs_divisor(blockecclen);
        let mut k = 0;
        for i in 0..numblocks {
            let datlen = shortblocklen - blockecclen + if i < numshortblocks { 0 } else { 1 };
            let mut dat = data[k..k + datlen].to_vec();
            k += datlen;
            let ecc = rs_remainder(&dat, &rsdiv);
            if i < numshortblocks {
                dat.push(0);
            }
            dat.extend_from_slice(&ecc);
            blocks.push(dat);
        }
        let mut result = Vec::with_capacity(rawcodewords);
        for i in 0..blocks[0].len() {
            for (j, block) in blocks.iter().enumerate() {
                if i != shortblocklen - blockecclen || j >= numshortblocks {
                    result.push(block[i]);
                }
            }
        }
        result
    }

    fn draw_codewords(&mut self, data: &[u8]) {
        let mut i: usize = 0;
        let mut right = self.size - 1;
        while right >= 1 {
            if right == 6 {
                right = 5;
            }
            for vert in 0..self.size {
                for j in 0..2 {
                    let x = right - j;
                    let upward = (right + 1) & 2 == 0;
                    let y = if upward { self.size - 1 - vert } else { vert };
                    let idx = (y * self.size + x) as usize;
                    if !self.is_function[idx] && i < data.len() * 8 {
                        self.modules[idx] = (data[i >> 3] >> (7 - (i & 7))) & 1 != 0;
                        i += 1;
                    }
                }
            }
            right -= 2;
        }
    }

    fn apply_mask(&mut self, mask: i32) {
        for y in 0..self.size {
            for x in 0..self.size {
                let invert = match mask {
                    0 => (x + y) % 2 == 0,
                    1 => y % 2 == 0,
                    2 => x % 3 == 0,
                    3 => (x + y) % 3 == 0,
                    4 => (x / 3 + y / 2) % 2 == 0,
                    5 => x * y % 2 + x * y % 3 == 0,
                    6 => (x * y % 2 + x * y % 3) % 2 == 0,
                    _ => ((x + y) % 2 + x * y % 3) % 2 == 0,
                };
                let idx = (y * self.size + x) as usize;
                if invert && !self.is_function[idx] {
                    self.modules[idx] = !self.modules[idx];
                }
            }
        }
    }

    fn penalty_score(&self) -> i32 {
        let mut result = 0;
        let size = self.size;
        // rows
        for y in 0..size {
            let mut run_color = false;
            let mut run_x = 0;
            let mut history = [0i32; 7];
            for x in 0..size {
                if self.get(x, y) == run_color {
                    run_x += 1;
                    if run_x == 5 {
                        result += 3;
                    } else if run_x > 5 {
                        result += 1;
                    }
                } else {
                    self.finder_history_add(run_x, &mut history);
                    if !run_color {
                        result += self.finder_count_patterns(&history) * 40;
                    }
                    run_color = self.get(x, y);
                    run_x = 1;
                }
            }
            result += self.finder_terminate(run_color, run_x, &mut history) * 40;
        }
        for x in 0..size {
            let mut run_color = false;
            let mut run_y = 0;
            let mut history = [0i32; 7];
            for y in 0..size {
                if self.get(x, y) == run_color {
                    run_y += 1;
                    if run_y == 5 {
                        result += 3;
                    } else if run_y > 5 {
                        result += 1;
                    }
                } else {
                    self.finder_history_add(run_y, &mut history);
                    if !run_color {
                        result += self.finder_count_patterns(&history) * 40;
                    }
                    run_color = self.get(x, y);
                    run_y = 1;
                }
            }
            result += self.finder_terminate(run_color, run_y, &mut history) * 40;
        }
        for y in 0..size - 1 {
            for x in 0..size - 1 {
                let c = self.get(x, y);
                if c == self.get(x + 1, y) && c == self.get(x, y + 1) && c == self.get(x + 1, y + 1) {
                    result += 3;
                }
            }
        }
        let dark: i32 = self.modules.iter().filter(|&&m| m).count() as i32;
        let total = size * size;
        let k = ((dark * 20 - total * 10).abs() + total - 1) / total - 1;
        result += k * 10;
        result
    }

    fn finder_count_patterns(&self, h: &[i32; 7]) -> i32 {
        let n = h[1];
        let core = n > 0 && h[2] == n && h[3] == n * 3 && h[4] == n && h[5] == n;
        (if core && h[0] >= n * 4 && h[6] >= n { 1 } else { 0 })
            + (if core && h[6] >= n * 4 && h[0] >= n { 1 } else { 0 })
    }

    fn finder_terminate(&self, run_color: bool, mut run: i32, h: &mut [i32; 7]) -> i32 {
        if run_color {
            self.finder_history_add(run, h);
            run = 0;
        }
        run += self.size;
        self.finder_history_add(run, h);
        self.finder_count_patterns(h)
    }

    fn finder_history_add(&self, mut run: i32, h: &mut [i32; 7]) {
        if h[0] == 0 {
            run += self.size;
        }
        h.copy_within(0..6, 1);
        h[0] = run;
    }
}

/// SVG with a one-module margin like fast_qr's SvgBuilder.
pub fn svg_for(text: &str) -> String {
    let qr = match QrCode::encode(text.as_bytes()) {
        Some(q) => q,
        None => return String::new(),
    };
    let margin = 1;
    let n = qr.size + margin * 2;
    let mut out = format!(
        "<svg viewBox=\"0 0 {n} {n}\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"{n}px\" height=\"{n}px\" fill=\"#ffffff\"/><path d=\""
    );
    for y in 0..qr.size {
        for x in 0..qr.size {
            if qr.get(x, y) {
                out.push_str(&format!("M{},{}h1v1h-1", x + margin, y + margin));
            }
        }
    }
    out.push_str("\" fill=\"#000000\"/></svg>");
    out
}

/// Print the QR code to the terminal using half block characters.
pub fn print_terminal(text: &str) {
    let qr = match QrCode::encode(text.as_bytes()) {
        Some(q) => q,
        None => return,
    };
    let border = 1;
    let size = qr.size;
    let dark = |x: i32, y: i32| -> bool { x >= 0 && y >= 0 && x < size && y < size && qr.get(x, y) };
    let mut out = String::new();
    let mut y = -border;
    while y < size + border {
        for x in -border..size + border {
            let top = dark(x, y);
            let bottom = dark(x, y + 1);
            out.push(match (top, bottom) {
                (true, true) => ' ',
                (true, false) => '▄',
                (false, true) => '▀',
                (false, false) => '█',
            });
        }
        out.push('\n');
        y += 2;
    }
    print!("{out}");
}
