//! File upload, directory creation and deletion handlers.

use std::io::{self, Read, Write};
use std::path::{Component, Path, PathBuf};

use sha2::{Digest, Sha256, Sha512};

use crate::config::{sanitize_path, DuplicateFile, MiniserveConfig};
use crate::errors::RuntimeError;
use crate::http::{Request, Response};

// ---------------- multipart ----------------

pub struct PartHeaders {
    pub name: Option<String>,
    pub filename: Option<String>,
}

struct Multipart<'a> {
    body: &'a mut dyn Read,
    buf: Vec<u8>,
    eof: bool,
    delim: Vec<u8>, // "\r\n--boundary"
    in_part: bool,
    finished: bool,
    started: bool,
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || hay.len() < needle.len() {
        return None;
    }
    hay.windows(needle.len()).position(|w| w == needle)
}

impl<'a> Multipart<'a> {
    fn fill(&mut self, min: usize) -> Result<(), String> {
        while !self.eof && self.buf.len() < min {
            let mut tmp = vec![0u8; std::cmp::max(65536, min)];
            match self.body.read(&mut tmp) {
                Ok(0) => self.eof = true,
                Ok(n) => self.buf.extend_from_slice(&tmp[..n]),
                Err(e) => return Err(e.to_string()),
            }
        }
        Ok(())
    }

    fn next_part(&mut self) -> Result<Option<PartHeaders>, String> {
        if self.finished {
            return Ok(None);
        }
        // finish current part data
        if self.in_part {
            let mut sink = vec![0u8; 65536];
            while self.read_data(&mut sink)? > 0 {}
        }
        if !self.started {
            // find first boundary: "--boundary" (delim without leading CRLF)
            let first = self.delim[2..].to_vec();
            loop {
                self.fill(self.buf.len() + first.len() + 2)?;
                if let Some(p) = find(&self.buf, &first) {
                    self.buf.drain(..p + first.len());
                    break;
                }
                if self.eof {
                    return Err("Multipart stream is incomplete".to_string());
                }
                if self.buf.len() > first.len() {
                    let keep = self.buf.len() - first.len();
                    self.buf.drain(..keep);
                }
            }
            self.started = true;
        }
        // after a delimiter: "--" means end, otherwise CRLF
        self.fill(2)?;
        if self.buf.len() < 2 {
            return Err("Multipart stream is incomplete".to_string());
        }
        if &self.buf[..2] == b"--" {
            self.finished = true;
            return Ok(None);
        }
        // skip to end of line
        loop {
            if let Some(p) = find(&self.buf, b"\r\n") {
                self.buf.drain(..p + 2);
                break;
            }
            if self.eof {
                return Err("Multipart stream is incomplete".to_string());
            }
            let l = self.buf.len() + 1;
            self.fill(l)?;
        }
        // headers
        let headers_end;
        loop {
            if self.buf.starts_with(b"\r\n") {
                headers_end = 0;
                break;
            }
            if let Some(p) = find(&self.buf, b"\r\n\r\n") {
                headers_end = p + 2;
                break;
            }
            if self.eof {
                return Err("Multipart stream is incomplete".to_string());
            }
            if self.buf.len() > 64 * 1024 {
                return Err("A payload reached size limit.".to_string());
            }
            let l = self.buf.len() + 1;
            self.fill(l)?;
        }
        let head: Vec<u8> = self.buf[..headers_end].to_vec();
        self.buf.drain(..headers_end + 2);
        let mut ph = PartHeaders { name: None, filename: None };
        for line in String::from_utf8_lossy(&head).split("\r\n") {
            if let Some((k, v)) = line.split_once(':') {
                if k.trim().eq_ignore_ascii_case("content-disposition") {
                    let (name, filename) = parse_content_disposition(v.trim());
                    ph.name = name;
                    ph.filename = filename;
                }
            }
        }
        self.in_part = true;
        Ok(Some(ph))
    }

    fn read_data(&mut self, out: &mut [u8]) -> Result<usize, String> {
        if !self.in_part {
            return Ok(0);
        }
        let dl = self.delim.len();
        self.fill(dl + out.len())?;
        if let Some(p) = find(&self.buf, &self.delim) {
            if p == 0 {
                self.buf.drain(..dl);
                self.in_part = false;
                return Ok(0);
            }
            let n = std::cmp::min(p, out.len());
            out[..n].copy_from_slice(&self.buf[..n]);
            self.buf.drain(..n);
            return Ok(n);
        }
        if self.eof {
            return Err("Multipart stream is incomplete".to_string());
        }
        let safe = self.buf.len().saturating_sub(dl);
        let n = std::cmp::min(safe, out.len());
        if n == 0 {
            let l = self.buf.len() + 1;
            self.fill(l)?;
            return self.read_data(out);
        }
        out[..n].copy_from_slice(&self.buf[..n]);
        self.buf.drain(..n);
        Ok(n)
    }
}

fn parse_params(s: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let b = s.as_bytes();
    let mut i = 0;
    // skip disposition type
    while i < b.len() && b[i] != b';' {
        i += 1;
    }
    while i < b.len() {
        // skip ';' and whitespace
        while i < b.len() && (b[i] == b';' || b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
        let ks = i;
        while i < b.len() && b[i] != b'=' && b[i] != b';' {
            i += 1;
        }
        let key = s[ks..i].trim().to_ascii_lowercase();
        if i >= b.len() || b[i] == b';' {
            continue;
        }
        i += 1; // '='
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
        let mut val = Vec::new();
        if i < b.len() && b[i] == b'"' {
            i += 1;
            while i < b.len() && b[i] != b'"' {
                if b[i] == b'\\' && i + 1 < b.len() {
                    i += 1;
                }
                val.push(b[i]);
                i += 1;
            }
            i += 1;
        } else {
            while i < b.len() && b[i] != b';' {
                val.push(b[i]);
                i += 1;
            }
            while val.last().map(|c| *c == b' ' || *c == b'\t').unwrap_or(false) {
                val.pop();
            }
        }
        out.push((key, String::from_utf8_lossy(&val).to_string()));
    }
    out
}

fn parse_content_disposition(v: &str) -> (Option<String>, Option<String>) {
    let params = parse_params(v);
    let name = params.iter().find(|(k, _)| k == "name").map(|(_, v)| v.clone());
    let filename = params.iter().find(|(k, _)| k == "filename").map(|(_, v)| v.clone());
    (name, filename)
}

fn multipart_from_request<'a>(req: &Request, body: &'a mut dyn Read) -> Result<Multipart<'a>, String> {
    let ct = req.header_str("content-type").ok_or_else(|| "Could not find Content-Type header".to_string())?;
    let base = ct.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    let (top, sub) = base.split_once('/').ok_or_else(|| "Could not parse Content-Type header".to_string())?;
    if top.is_empty() || sub.is_empty() {
        return Err("Could not parse Content-Type header".to_string());
    }
    if top != "multipart" {
        return Err("ContentTypeIncompatible".to_string());
    }
    let params = parse_params(ct);
    let boundary = params
        .iter()
        .find(|(k, _)| k == "boundary")
        .map(|(_, v)| v.clone())
        .ok_or_else(|| "Multipart boundary is not found".to_string())?;
    let mut delim = b"\r\n--".to_vec();
    delim.extend_from_slice(boundary.as_bytes());
    Ok(Multipart { body, buf: Vec::new(), eof: false, delim, in_part: false, finished: false, started: false })
}

// ---------------- helpers ----------------

#[derive(Debug)]
enum FileHash {
    Sha256(String),
    Sha512(String),
}

fn contains_symlink(path: &Path) -> Result<bool, RuntimeError> {
    let mut joined = PathBuf::new();
    for slice in path.iter() {
        joined = joined.join(slice);
        if !joined.exists() {
            continue;
        }
        let md = joined
            .symlink_metadata()
            .map_err(|e| RuntimeError::Io("Failed to get symlink metadata".to_string(), e))?;
        if md.file_type().is_symlink() {
            return Ok(true);
        }
    }
    Ok(false)
}

fn random_alnum(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut buf = vec![0u8; n];
    unsafe {
        let fd = libc::open(b"/dev/urandom\0".as_ptr() as *const libc::c_char, libc::O_RDONLY);
        if fd >= 0 {
            libc::read(fd, buf.as_mut_ptr() as *mut libc::c_void, n);
            libc::close(fd);
        }
    }
    buf.iter().map(|b| CHARS[(*b as usize) % CHARS.len()] as char).collect()
}

fn create_temp_file(dir: &Path) -> io::Result<(std::fs::File, PathBuf)> {
    use std::os::unix::fs::OpenOptionsExt;
    for _ in 0..100 {
        let p = dir.join(format!(".tmp{}", random_alnum(6)));
        match std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&p) {
            Ok(f) => return Ok((f, p)),
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        }
    }
    Err(io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary files exist"))
}

fn current_umask() -> u32 {
    static UMASK: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *UMASK.get_or_init(|| unsafe {
        let old = libc::umask(0o022);
        libc::umask(old);
        old as u32
    })
}

pub fn init_umask() {
    let _ = current_umask();
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

fn save_file(
    mp: &mut Multipart,
    file_path: PathBuf,
    on_dup: DuplicateFile,
    file_hash: Option<&FileHash>,
    file_mode: Option<u32>,
    temp_dir: Option<&PathBuf>,
) -> Result<u64, RuntimeError> {
    let mut file_path = file_path;
    if file_path.exists() {
        match on_dup {
            DuplicateFile::Error => return Err(RuntimeError::DuplicateFile),
            DuplicateFile::Overwrite => {}
            DuplicateFile::Rename => {
                let stem = file_path.file_stem().unwrap_or_default().to_string_lossy().to_string();
                let ext = file_path.extension().map(|s| s.to_string_lossy().to_string());
                let mut i = 1u64;
                loop {
                    let new_name = match &ext {
                        Some(e) => format!("{stem}-{i}.{e}"),
                        None => format!("{stem}-{i}"),
                    };
                    let np = file_path.with_file_name(new_name);
                    if !np.exists() {
                        file_path = np;
                        break;
                    }
                    i += 1;
                }
            }
        }
    }
    let tdir = temp_dir.cloned().unwrap_or_else(std::env::temp_dir);
    let (mut tmp, tmp_path) = create_temp_file(&tdir)
        .map_err(|e| RuntimeError::Io("Failed to create temporary file".to_string(), e))?;
    let mut sha256 = Sha256::new();
    let mut sha512 = Sha512::new();
    let mut written: u64 = 0;
    let mut buf = vec![0u8; 65536];
    let mut write_err: Option<io::Error> = None;
    loop {
        let n = match mp.read_data(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) => {
                drop(tmp);
                let _ = std::fs::remove_file(&tmp_path);
                return Err(RuntimeError::Multipart(e));
            }
        };
        match file_hash {
            Some(FileHash::Sha256(_)) => sha256.update(&buf[..n]),
            Some(FileHash::Sha512(_)) => sha512.update(&buf[..n]),
            None => {}
        }
        if write_err.is_none() {
            if let Err(e) = tmp.write_all(&buf[..n]) {
                write_err = Some(e);
            } else {
                written += n as u64;
            }
        }
    }
    drop(tmp);
    if let Some(h) = file_hash {
        let (expected, actual) = match h {
            FileHash::Sha256(e) => (e.clone(), hex(&sha256.finalize())),
            FileHash::Sha512(e) => (e.clone(), hex(&sha512.finalize())),
        };
        if actual != expected {
            crate::logger::warn(&format!(
                "The expected file hash {expected} did not match the calculated hash of {actual}"
            ));
            let _ = std::fs::remove_file(&tmp_path);
            return Err(RuntimeError::UploadHashMismatch);
        }
    }
    if let Some(e) = write_err {
        let _ = std::fs::remove_file(&tmp_path);
        return Err(RuntimeError::Io("Failed to write to temporary file".to_string(), e));
    }
    if let Err(e) = std::fs::rename(&tmp_path, &file_path) {
        let _ = std::fs::remove_file(&tmp_path);
        return Err(RuntimeError::Io(
            format!("Failed to move temporary file {:?} to {:?}", tmp_path, file_path),
            e,
        ));
    }
    let mode = file_mode.unwrap_or(0o666 & !current_umask());
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&file_path, std::fs::Permissions::from_mode(mode));
    }
    Ok(written)
}

fn handle_part(
    mp: &mut Multipart,
    ph: PartHeaders,
    path: &Path,
    conf: &MiniserveConfig,
    file_hash: Option<&FileHash>,
) -> Result<u64, RuntimeError> {
    let field_name = ph.name.clone().unwrap_or_default();
    match std::fs::metadata(path) {
        Err(_) => return Err(RuntimeError::InsufficientPermissions(path.display().to_string())),
        Ok(md) if !md.is_dir() => {
            return Err(RuntimeError::InvalidPath(format!(
                "cannot upload file to {}, since it's not a directory",
                path.display()
            )))
        }
        Ok(_) => {}
    }
    if field_name == "mkdir" {
        if !conf.mkdir_enabled {
            return Err(RuntimeError::InsufficientPermissions(path.display().to_string()));
        }
        let mut data = Vec::new();
        let mut buf = vec![0u8; 65536];
        let n = mp.read_data(&mut buf).map_err(RuntimeError::Multipart)?;
        data.extend_from_slice(&buf[..n]);
        if data.is_empty() {
            return Err(RuntimeError::Parse("Failed to parse 'mkdir' path".to_string(), String::new()));
        }
        let mkdir_path = std::str::from_utf8(&data)
            .map_err(|e| RuntimeError::Parse("Failed to parse 'mkdir' path".to_string(), e.to_string()))?;
        let mkdir_path = mkdir_path.replace('\\', "/");
        let mut absolute_path = path.to_path_buf();
        absolute_path.push(&mkdir_path);
        let user_given = PathBuf::from(&mkdir_path);
        if user_given.components().any(|c| c == Component::ParentDir) {
            return Err(RuntimeError::InvalidPath("Cannot use '..' in mkdir path".to_string()));
        }
        if sanitize_path(&user_given, conf.show_hidden).is_none() {
            return Err(RuntimeError::InvalidPath("Cannot use hidden paths in mkdir path".to_string()));
        }
        if conf.no_symlinks {
            match contains_symlink(&absolute_path) {
                Err(e) => return Err(RuntimeError::InsufficientPermissions(e.to_string())),
                Ok(true) => {
                    return Err(RuntimeError::InsufficientPermissions(format!(
                        "{:?} traverses through a symlink",
                        user_given
                    )))
                }
                Ok(false) => {}
            }
        }
        return match std::fs::create_dir_all(&absolute_path) {
            Err(e) if e.kind() == io::ErrorKind::PermissionDenied => {
                Err(RuntimeError::InsufficientPermissions(path.display().to_string()))
            }
            Err(e) => Err(RuntimeError::Io(format!("Failed to create {}", user_given.display()), e)),
            Ok(_) => Ok(0),
        };
    }
    let filename = ph.filename.ok_or_else(|| {
        RuntimeError::Parse("HTTP header".to_string(), "Failed to retrieve the name of the file to upload".to_string())
    })?;
    let filename_path = sanitize_path(Path::new(&filename), conf.show_hidden)
        .ok_or_else(|| RuntimeError::InvalidPath("Invalid file name to upload".to_string()))?;
    if conf.no_symlinks {
        match contains_symlink(path) {
            Err(e) => return Err(RuntimeError::InsufficientPermissions(e.to_string())),
            Ok(true) => {
                return Err(RuntimeError::InsufficientPermissions(format!("{:?} traverses through a symlink", path)))
            }
            Ok(false) => {}
        }
    }
    save_file(
        mp,
        path.join(filename_path),
        conf.on_duplicate_files,
        file_hash,
        conf.chmod,
        conf.temp_upload_directory.as_ref(),
    )
}

fn query_path(req: &Request) -> Result<String, Response> {
    let mut path: Option<String> = None;
    for (k, v) in crate::util::parse_query(&req.query) {
        if k == "path" {
            if path.is_some() {
                return Err(Response::text(400, "Query deserialize error: duplicate field `path`"));
            }
            path = Some(v);
        }
    }
    path.ok_or_else(|| Response::text(400, "Query deserialize error: missing field `path`"))
}

fn see_other(req: &Request) -> Response {
    let ret = req.header_str("referer").unwrap_or("/").to_string();
    let mut r = Response::new(303);
    r.set_header("location", &ret);
    r
}

pub fn upload_file(req: &Request, body: &mut dyn Read, conf: &MiniserveConfig) -> Response {
    let qpath = match query_path(req) {
        Ok(p) => p,
        Err(r) => return r,
    };
    match upload_inner(req, body, conf, &qpath) {
        Ok(r) => r,
        Err(e) => e.into_response(),
    }
}

fn upload_inner(req: &Request, body: &mut dyn Read, conf: &MiniserveConfig, qpath: &str) -> Result<Response, RuntimeError> {
    let upload_path = sanitize_path(Path::new(qpath), conf.show_hidden)
        .ok_or_else(|| RuntimeError::InvalidPath("Invalid value for 'path' parameter".to_string()))?;
    let app_root_dir = conf
        .path
        .canonicalize()
        .map_err(|e| RuntimeError::Io("Failed to resolve path served by miniserve".to_string(), e))?;
    let upload_allowed = conf.allowed_upload_dir.is_empty()
        || conf.allowed_upload_dir.iter().any(|s| upload_path.starts_with(s));
    if !upload_allowed {
        return Err(RuntimeError::UploadForbidden);
    }
    let non_canonicalized_target_dir = app_root_dir.join(&upload_path);
    match non_canonicalized_target_dir.canonicalize() {
        Ok(_) if !conf.no_symlinks => {}
        Ok(p) if p.starts_with(&app_root_dir) => {}
        _ => return Err(RuntimeError::InvalidHttpRequest("Invalid value for 'path' parameter".to_string())),
    }
    let hash = req.header_str("x-file-hash").map(|s| s.to_string());
    let hash_fn = req.header_str("x-file-hash-function").map(|s| s.to_string());
    let file_hash = match (hash, hash_fn) {
        (Some(h), Some(f)) => match f.to_ascii_uppercase().as_str() {
            "SHA256" => Some(FileHash::Sha256(h)),
            "SHA512" => Some(FileHash::Sha512(h)),
            sha => {
                return Err(RuntimeError::InvalidHttpRequest(format!(
                    "Invalid header value found for 'X-File-Hash-Function'. Supported values are SHA256 or SHA512. Found {sha}."
                )))
            }
        },
        _ => None,
    };
    let mut mp = multipart_from_request(req, body).map_err(RuntimeError::Multipart)?;
    loop {
        let ph = match mp.next_part() {
            Ok(Some(p)) => p,
            Ok(None) => break,
            Err(e) => return Err(RuntimeError::Multipart(e)),
        };
        handle_part(&mut mp, ph, &non_canonicalized_target_dir, conf, file_hash.as_ref())?;
    }
    Ok(see_other(req))
}

pub fn rm_file(req: &Request, conf: &MiniserveConfig) -> Response {
    let qpath = match query_path(req) {
        Ok(p) => p,
        Err(r) => return r,
    };
    match rm_inner(req, conf, &qpath) {
        Ok(r) => r,
        Err(e) => e.into_response(),
    }
}

fn rm_inner(req: &Request, conf: &MiniserveConfig, qpath: &str) -> Result<Response, RuntimeError> {
    let rm_path = sanitize_path(Path::new(qpath), conf.show_hidden)
        .ok_or_else(|| RuntimeError::InvalidPath("Invalid value for 'path' parameter".to_string()))?;
    let app_root_dir = conf
        .path
        .canonicalize()
        .map_err(|e| RuntimeError::Io("Failed to resolve path served by miniserve".to_string(), e))?;
    let rm_allowed = conf.allowed_rm_dir.is_empty() || conf.allowed_rm_dir.iter().any(|s| rm_path.starts_with(s));
    if !rm_allowed {
        return Err(RuntimeError::RmForbidden);
    }
    let target = match app_root_dir.join(&rm_path).canonicalize() {
        Ok(p) if !conf.no_symlinks => p,
        Ok(p) if p.starts_with(&app_root_dir) => p,
        _ => return Err(RuntimeError::InvalidHttpRequest("Invalid value for 'path' parameter".to_string())),
    };
    let md = std::fs::symlink_metadata(&target)
        .map_err(|e| RuntimeError::Io(format!("Failed to delete {}", target.display()), e))?;
    let res = if md.is_dir() { std::fs::remove_dir_all(&target) } else { std::fs::remove_file(&target) };
    res.map_err(|e| RuntimeError::Io(format!("Failed to delete {}", target.display()), e))?;
    Ok(see_other(req))
}
