fn dav_etag(md: &std::fs::Metadata) -> String {
    let micros = md
        .modified()
        .ok()
        .and_then(|m| m.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_micros() as u64)
        .unwrap_or(0);
    if md.is_file() {
        format!("{:x}-{:x}-{:x}", md.ino(), md.len(), micros)
    } else {
        format!("{:x}-{:x}", md.ino(), micros)
    }
}

fn xml_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            '\'' => o.push_str("&apos;"),
            _ => o.push(c),
        }
    }
    o
}

fn encode_href_path(p: &str) -> String {
    let mut out = String::new();
    for &b in p.as_bytes() {
        if b.is_ascii_alphanumeric() || b"/-_.~!$&'()*+,;=:@".contains(&b) {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn response_entry(href: &str, md: &std::fs::Metadata, path: &Path) -> String {
    let created = md
        .created()
        .or_else(|_| md.modified())
        .ok()
        .map(|t| crate::timeutil::rfc3339(crate::timeutil::unix_secs(t)))
        .unwrap_or_default();
    let modified = md.modified().ok().map(|t| crate::timeutil::http_date(crate::timeutil::unix_secs(t))).unwrap_or_default();
    let mut s = String::new();
    s.push_str("<D:response><D:href>");
    s.push_str(&xml_escape(href));
    s.push_str("</D:href><D:propstat><D:prop>");
    s.push_str(&format!("<D:creationdate>{created}</D:creationdate>"));
    if md.is_file() {
        s.push_str(&format!("<D:getcontentlength>{}</D:getcontentlength>", md.len()));
        s.push_str(&format!("<D:getcontenttype>{}</D:getcontenttype>", crate::util::guess_mime(path)));
    } else {
        s.push_str("<D:getcontenttype>httpd/unix-directory</D:getcontenttype>");
    }
    s.push_str(&format!("<D:getetag>{}</D:getetag>", dav_etag(md)));
    s.push_str(&format!("<D:getlastmodified>{modified}</D:getlastmodified>"));
    s.push_str("<D:lockdiscovery></D:lockdiscovery>");
    if md.is_dir() {
        s.push_str("<D:resourcetype><D:collection></D:collection></D:resourcetype>");
    } else {
        s.push_str("<D:resourcetype></D:resourcetype>");
    }
    s.push_str("<D:supportedlock></D:supportedlock></D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat></D:response>");
    s
}

pub fn handle(req: &Request, body: &mut dyn Read, conf: &MiniserveConfig, root: &Path, sub: &str) -> Response {
    let mut sink = Vec::new();
    let _ = body.take(1 << 20).read_to_end(&mut sink);
    if req.method == "OPTIONS" {
        let mut r = Response::new(200);
        r.set_header("dav", "1,2,3,sabredav-partialupdate");
        r.set_header("ms-author-via", "DAV");
        r.set_header("allow", "OPTIONS,PROPFIND");
        return r;
    }
    let depth = req.header_str("depth").map(|s| s.trim().to_ascii_lowercase());
    let depth = match depth.as_deref() {
        Some("0") => 0,
        Some("1") => 1,
        _ => {
            let mut r = Response::with_body(
                403,
                Some("application/xml; charset=utf-8"),
                b"<?xml version=\"1.0\" encoding=\"utf-8\" ?>\n<D:error xmlns:D=\"DAV:\">\n<D:propfind-finite-depth/>\n</D:error>\n".to_vec(),
            );
            r.set_header("cache-control", "no-cache");
            r.set_header("pragma", "no-cache");
            return r;
        }
    };
    let decoded = String::from_utf8_lossy(&crate::util::percent_decode_str(sub)).to_string();
    let rel = crate::config::sanitize_path(Path::new(&decoded), conf.show_hidden);
    let rel = match rel {
        Some(r) => r,
        None => return Response::new(404),
    };
    let fs_path = root.join(&rel);
    let md = match std::fs::metadata(&fs_path) {
        Ok(m) => m,
        Err(_) => return Response::new(404),
    };
    let mut href_base = format!("{}/{}", conf.route_prefix, rel.to_string_lossy());
    if href_base.ends_with("//") {
        href_base.pop();
    }
    if md.is_dir() && !href_base.ends_with('/') {
        href_base.push('/');
    }
    let mut parts: Vec<String> = Vec::new();
    parts.push(format!(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?><D:multistatus xmlns:D=\"DAV:\">{}",
        response_entry(&encode_href_path(&href_base), &md, &fs_path)
    ));
    if depth == 1 && md.is_dir() {
        if let Ok(rd) = std::fs::read_dir(&fs_path) {
            for e in rd.flatten() {
                let name = e.file_name().to_string_lossy().to_string();
                if !conf.show_hidden && name.starts_with('.') {
                    continue;
                }
                let lmd = match e.metadata() {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                if conf.no_symlinks && lmd.file_type().is_symlink() {
                    continue;
                }
                let cmd = match std::fs::metadata(e.path()) {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                let mut href = format!("{}{}", href_base, name);
                if cmd.is_dir() {
                    href.push('/');
                }
                parts.push(response_entry(&encode_href_path(&href), &cmd, &e.path()));
            }
        }
    }
    parts.push("</D:multistatus>".to_string());
    let mut r = Response::new(207);
    r.set_header("content-type", "application/xml; charset=utf-8");
    r.set_header("cache-control", "no-cache");
    r.set_header("pragma", "no-cache");
    r.body = Body::Stream(Box::new(move |w| {
        for p in parts {
            w.write_all(p.as_bytes())?;
        }
        Ok(())
    }));
    r
}
