            d=s.recv(65536)
            if not d: break
            data+=d
    except socket.timeout:
        data+=b'<<TIMEOUT>>'
    s.close()
    head,_,bd=data.partition(b'\r\n\r\n')
    lines=head.decode('latin1').split('\r\n')
    status=lines[0]
    hdrs={}
    for l in lines[1:]:
        k,_,v=l.partition(':'); k=k.lower(); v=v.strip()
        if k=='date': continue
        hdrs.setdefault(k,[]).append(v)
    if 'chunked' in ' '.join(hdrs.get('transfer-encoding',[])):
        bd=dechunk(bd)
    enc=' '.join(hdrs.get('content-encoding',[]))
    if enc=='gzip':
