    b=b.replace(str(PA).encode(),b'PORT').replace(str(PB).encode(),b'PORT')
    return b

def norm_hdrs(h):
    h=dict(h)
    for k in list(h):
        h[k]=[v.replace(str(PA),'PORT').replace(str(PB),'PORT') for v in h[k]]
    # ignore length differences for compressed bodies
    if 'content-encoding' in h and h['content-encoding'][0] in ('br','zstd','gzip','deflate'):
