    b=re.sub(rb'\d+ seconds ago',b'N seconds ago',b)
    b=re.sub(rb'\b(now|a minute ago|\d+ minutes ago)\b',b'RECENT',b)
    b=b.replace(str(PA).encode(),b'PORT').replace(str(PB).encode(),b'PORT')
    return b

def norm_hdrs(h):
    h=dict(h)
    for k in list(h):
        h[k]=[v.replace(str(PA),'PORT').replace(str(PB),'PORT') for v in h[k]]
