    if 'content-encoding' in h and h['content-encoding'][0] in ('br','zstd','gzip','deflate'):
        h.pop('content-length',None)
    return h

def show_diff(a,b):
    import difflib
    sa=a.decode('utf-8','replace').replace('><','>\n<').split('\n')
    sb=b.decode('utf-8','replace').replace('><','>\n<').split('\n')
    d=list(difflib.unified_diff(sa,sb,'orig','mine',n=1,lineterm=''))
    return '\n'.join(d[:60])

def run_suite(name, args, reqs, setup=None, check_files=None, quiet=False):
    if setup: setup()
    pa=start(ORIG,PA,args)
    res_a=[]
    for r in reqs:
        if r.get('fs_reset'): r['fs_reset']()
        res_a.append(request(PA,**{k:v for k,v in r.items() if k in('method','path','headers','body','raw')}))
        if r.get('sleep'): time.sleep(r['sleep'])
    fs_a = check_files() if check_files else None
    oa,ea=stop(pa)
    if setup: setup()
    pb=start(MINE,PB,args)
    res_b=[]
    for r in reqs:
        if r.get('fs_reset'): r['fs_reset']()
        res_b.append(request(PB,**{k:v for k,v in r.items() if k in('method','path','headers','body','raw')}))
        if r.get('sleep'): time.sleep(r['sleep'])
    fs_b = check_files() if check_files else None
    ob,eb=stop(pb)
    fails=0
    for r,a,b in zip(reqs,res_a,res_b):
        sa,ha,ba=a; sb,hb,bb=b
        ha=norm_hdrs(ha); hb=norm_hdrs(hb)
        if r.get('ignore_headers'):
            for k in r['ignore_headers']: ha.pop(k,None); hb.pop(k,None)
        ba=norm_body(ba); bb=norm_body(bb)
        if r.get('body_ignore'): ba=bb=b''
        if sa!=sb or ha!=hb or ba!=bb:
            fails+=1
            print(f'### [{name}] {r.get("method")} {r.get("path")} {r.get("headers","")}')
            if sa!=sb: print('  status:',sa,'|',sb)
            if ha!=hb:
                for k in sorted(set(ha)|set(hb)):
                    if ha.get(k)!=hb.get(k): print(f'  hdr {k}: {ha.get(k)} | {hb.get(k)}')
            if ba!=bb: print(show_diff(ba,bb))
    if fs_a!=fs_b:
        fails+=1
        print(f'### [{name}] filesystem differs:\n  orig={fs_a}\n  mine={fs_b}')
    def normlog(s):
        s=re.sub(r'\w{3}, \d\d \w{3} \d{4} \d\d:\d\d:\d\d \+0000','<TS>',s)
        s=s.replace(str(PA),'PORT').replace(str(PB),'PORT')
        s=re.sub(r'\d+\.\d{6}$','T',s,flags=re.M)
        s=re.sub(r'/\.tmp\w{6}','/.tmpXXXXXX',s)
        return s
    if normlog(ea)!=normlog(eb) and not quiet:
        print(f'### [{name}] stderr differs:\n--orig\n{normlog(ea)}\n--mine\n{normlog(eb)}')
    if normlog(oa)!=normlog(ob) and not quiet:
        print(f'### [{name}] stdout differs:\n--orig\n{normlog(oa)}\n--mine\n{normlog(ob)}')
    print(f'[{name}] {len(reqs)} requests, {fails} diffs')
    return fails

def G(path, **kw):
    d={'method':'GET','path':path}; d.update(kw); return d
