//! Read-only WebDAV (PROPFIND) support.

use std::io::Read;
use std::os::unix::fs::MetadataExt;
use std::path::Path;
use std::time::UNIX_EPOCH;

use crate::config::MiniserveConfig;
use crate::http::{Body, Request, Response};

fn dav_etag(md: &std::fs::Metadata) -> String {
    let micros = md
        .modified()
        .ok()
        .and_then(|m| m.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_micros() as u64)
        .unwrap_or(0);
    if md.is_file() {
        format!("{:x}-{:x}-{:x}", md.ino(), md.len(), micros)
    } else {
        format!("{:x}-{:x}", md.ino(), micros)
    }
}

fn xml_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            '\'' => o.push_str("&apos;"),
            _ => o.push(c),
        }
    }
    o
}

fn encode_href_path(p: &str) -> String {
    let mut out = String::new();
    for &b in p.as_bytes() {
        if b.is_ascii_alphanumeric() || b"/-_.~".contains(&b) {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

const DAV_NS: &str = "DAV:";

#[derive(Clone, Debug)]
struct PropName {
    ns: String,
    name: String,
}

enum PropRequest {
    AllProp,
    PropName,
    Props(Vec<PropName>),
}

/// Very small XML scanner sufficient for PROPFIND bodies.
fn parse_propfind(body: &[u8]) -> Result<PropRequest, ()> {
    let text = std::str::from_utf8(body).map_err(|_| ())?;
    if text.trim().is_empty() {
        return Ok(PropRequest::AllProp);
    }
    // tokens: (name, attrs, is_end, self_closing)
    let mut stack: Vec<(String, Vec<(String, String)>)> = Vec::new();
    let mut ns_stack: Vec<Vec<(String, String)>> = Vec::new();
    let mut i = 0;
    let b = text.as_bytes();
    let mut root_seen = false;
    let mut result: Option<PropRequest> = None;
    let mut in_prop_depth: Option<usize> = None;
    let mut props: Vec<PropName> = Vec::new();
    let resolve = |prefix: &str, ns_stack: &Vec<Vec<(String, String)>>| -> Option<String> {
        for scope in ns_stack.iter().rev() {
            for (p, u) in scope.iter() {
                if p == prefix {
                    return Some(u.clone());
                }
            }
        }
        if prefix.is_empty() {
            Some(String::new())
        } else {
            None
        }
    };
    while i < b.len() {
        if b[i] != b'<' {
            if !b[i].is_ascii_whitespace() && stack.is_empty() {
                return Err(());
            }
            i += 1;
            continue;
        }
        let end = match text[i..].find('>') {
            Some(e) => i + e,
            None => return Err(()),
        };
        let tag = &text[i + 1..end];
        i = end + 1;
        if tag.starts_with('?') || tag.starts_with('!') {
            continue;
        }
        if let Some(name) = tag.strip_prefix('/') {
            let name = name.trim();
            let (open, _) = stack.pop().ok_or(())?;
            if open != name {
                return Err(());
            }
            ns_stack.pop();
            if let Some(d) = in_prop_depth {
                if stack.len() < d {
                    in_prop_depth = None;
                }
            }
            continue;
        }
        let self_closing = tag.ends_with('/');
        let tag = tag.trim_end_matches('/');
        let mut parts = tag.splitn(2, |c: char| c.is_whitespace());
        let name = parts.next().unwrap_or("").to_string();
        if name.is_empty() {
            return Err(());
        }
        let attr_text = parts.next().unwrap_or("");
        let mut attrs = Vec::new();
        let mut scope = Vec::new();
        let mut rest = attr_text.trim();
        while !rest.is_empty() {
            let eq = rest.find('=').ok_or(())?;
            let key = rest[..eq].trim().to_string();
            let after = rest[eq + 1..].trim_start();
            let q = after.chars().next().ok_or(())?;
            if q != '"' && q != '\'' {
                return Err(());
            }
            let close = after[1..].find(q).ok_or(())? + 1;
            let val = after[1..close].to_string();
            if key == "xmlns" {
                scope.push((String::new(), val.clone()));
            } else if let Some(p) = key.strip_prefix("xmlns:") {
                scope.push((p.to_string(), val.clone()));
            }
            attrs.push((key, val));
            rest = after[close + 1..].trim_start();
        }
        ns_stack.push(scope);
        let (prefix, local) = match name.split_once(':') {
            Some((p, l)) => (p.to_string(), l.to_string()),
            None => (String::new(), name.clone()),
        };
        let ns = resolve(&prefix, &ns_stack).ok_or(())?;
        let depth = stack.len();
        if depth == 0 {
            if root_seen || local != "propfind" || ns != DAV_NS {
                return Err(());
            }
            root_seen = true;
        } else if depth == 1 && ns == DAV_NS {
            match local.as_str() {
                "allprop" => result = Some(PropRequest::AllProp),
                "propname" => result = Some(PropRequest::PropName),
                "prop" => {
                    in_prop_depth = Some(2);
                }
                _ => {}
            }
        } else if depth == 2 && in_prop_depth.is_some() {
            props.push(PropName { ns: ns.clone(), name: local.clone() });
        }
        if self_closing {
            ns_stack.pop();
            if local == "prop" && depth == 1 {
                in_prop_depth = None;
            }
        } else {
            stack.push((name, attrs));
        }
    }
    if !stack.is_empty() || !root_seen {
        return Err(());
    }
    if let Some(r) = result {
        return Ok(r);
    }
    Ok(PropRequest::Props(props))
}

fn prop_value(name: &str, md: &std::fs::Metadata, path: &Path) -> Option<String> {
    match name {
        "creationdate" => Some(
            md.created()
                .or_else(|_| md.modified())
                .ok()
                .map(|t| crate::timeutil::rfc3339(crate::timeutil::unix_secs(t)))
                .unwrap_or_default(),
        ),
        "getcontentlength" if md.is_file() => Some(md.len().to_string()),
        "getcontenttype" => Some(if md.is_file() {
            crate::util::guess_mime(path).to_string()
        } else {
            "httpd/unix-directory".to_string()
        }),
        "getetag" => Some(dav_etag(md)),
        "getlastmodified" => Some(
            md.modified()
                .ok()
                .map(|t| crate::timeutil::http_date(crate::timeutil::unix_secs(t)))
                .unwrap_or_default(),
        ),
        "lockdiscovery" => Some(String::new()),
        "resourcetype" => Some(if md.is_dir() { "<D:collection></D:collection>".to_string() } else { String::new() }),
        "supportedlock" => Some(String::new()),
        _ => None,
    }
}

const ALLPROPS: [&str; 8] = [
    "creationdate",
    "getcontentlength",
    "getcontenttype",
    "getetag",
    "getlastmodified",
    "lockdiscovery",
    "resourcetype",
    "supportedlock",
];

fn response_entry(href: &str, md: &std::fs::Metadata, path: &Path, req: &PropRequest) -> String {
    let mut s = String::new();
    s.push_str("<D:response><D:href>");
    s.push_str(&xml_escape(href));
    s.push_str("</D:href>");
    match req {
        PropRequest::AllProp => {
            s.push_str("<D:propstat><D:prop>");
            for p in ALLPROPS {
                if let Some(v) = prop_value(p, md, path) {
                    s.push_str(&format!("<D:{p}>{v}</D:{p}>"));
                }
            }
            s.push_str("</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>");
        }
        PropRequest::PropName => {
            s.push_str("<D:propstat><D:prop>");
            for p in ALLPROPS {
                if prop_value(p, md, path).is_some() {
                    s.push_str(&format!("<D:{p}></D:{p}>"));
                }
            }
            if md.is_file() {
                s.push_str("<A:executable></A:executable>");
            }
            s.push_str("<Z:Win32LastAccessTime></Z:Win32LastAccessTime>");
            s.push_str("</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>");
        }
        PropRequest::Props(props) => {
            let mut found = String::new();
            let mut missing = String::new();
            for p in props {
                let v = if p.ns == DAV_NS { prop_value(&p.name, md, path) } else { None };
                match v {
                    Some(v) => found.push_str(&format!("<D:{}>{}</D:{}>", p.name, v, p.name)),
                    None => {
                        if p.ns == DAV_NS {
                            missing.push_str(&format!("<D:{}></D:{}>", p.name, p.name));
                        } else if p.ns.is_empty() {
                            missing.push_str(&format!("<{}></{}>", p.name, p.name));
                        } else {
                            missing.push_str(&format!(
                                "<{} xmlns=\"{}\"></{}>",
                                p.name,
                                xml_escape(&p.ns),
                                p.name
                            ));
                        }
                    }
                }
            }
            if !found.is_empty() {
                s.push_str("<D:propstat><D:prop>");
                s.push_str(&found);
                s.push_str("</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>");
            }
            if !missing.is_empty() {
                s.push_str("<D:propstat><D:prop>");
                s.push_str(&missing);
                s.push_str("</D:prop><D:status>HTTP/1.1 404 Not Found</D:status></D:propstat>");
            }
        }
    }
    s.push_str("</D:response>");
    s
}

fn not_found() -> Response {
    Response::new(404)
}

fn has_symlink(root: &Path, rel: &Path) -> bool {
    let mut p = root.to_path_buf();
    for c in rel.components() {
        p.push(c);
        if let Ok(md) = std::fs::symlink_metadata(&p) {
            if md.file_type().is_symlink() {
                return true;
            }
        }
    }
    false
}

/// Returns None when the request should fall through (route not found).
pub fn handle(req: &Request, body: &mut dyn Read, conf: &MiniserveConfig, root: &Path, sub: &str) -> Option<Response> {
    if sub.is_empty() {
        return None;
    }
    let mut data = Vec::new();
    let _ = body.take(1 << 20).read_to_end(&mut data);
    let decoded = String::from_utf8_lossy(&crate::util::percent_decode_str(sub)).to_string();
    let rel = match crate::config::sanitize_path(Path::new(&decoded), conf.show_hidden) {
        Some(r) => r,
        None => return Some(not_found()),
    };
    if conf.no_symlinks && has_symlink(root, &rel) {
        return Some(not_found());
    }
    let fs_path = root.join(&rel);
    let md = match std::fs::metadata(&fs_path) {
        Ok(m) => m,
        Err(_) => return Some(not_found()),
    };
    if req.method == "OPTIONS" {
        let mut r = Response::new(200);
        r.set_header("dav", "1,2,3,sabredav-partialupdate");
        r.set_header("ms-author-via", "DAV");
        r.set_header("allow", if md.is_file() { "HEAD,GET,OPTIONS,PROPFIND" } else { "OPTIONS,PROPFIND" });
        return Some(r);
    }
    let depth = req.header_str("depth").map(|s| s.trim().to_ascii_lowercase());
    let depth = match depth.as_deref() {
        Some("0") => 0,
        Some("1") => 1,
        _ => {
            let mut r = Response::with_body(
                403,
                Some("application/xml; charset=utf-8"),
                b"<?xml version=\"1.0\" encoding=\"utf-8\" ?>\n<D:error xmlns:D=\"DAV:\">\n<D:propfind-finite-depth/>\n</D:error>\n".to_vec(),
            );
            r.set_header("cache-control", "no-cache");
            r.set_header("pragma", "no-cache");
            return Some(r);
        }
    };
    let preq = match parse_propfind(&data) {
        Ok(p) => p,
        Err(()) => return Some(Response::new(400)),
    };
    let rel_s = rel.to_string_lossy().to_string();
    let mut href_base = if rel_s.is_empty() {
        format!("{}/", conf.route_prefix)
    } else {
        format!("{}/{}", conf.route_prefix, rel_s)
    };
    let mut content_location = None;
    if md.is_dir() && !href_base.ends_with('/') {
        href_base.push('/');
    }
    if md.is_dir() && !sub.ends_with('/') {
        content_location = Some(encode_href_path(&href_base));
    }
    let ns_decl = if matches!(preq, PropRequest::PropName) {
        " xmlns:A=\"http://apache.org/dav/props/\" xmlns:D=\"DAV:\" xmlns:Z=\"urn:schemas-microsoft-com:\""
    } else {
        " xmlns:D=\"DAV:\""
    };
    let mut parts: Vec<String> = Vec::new();
    parts.push(format!(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?><D:multistatus{}>{}",
        ns_decl,
        response_entry(&encode_href_path(&href_base), &md, &fs_path, &preq)
    ));
    if depth == 1 && md.is_dir() {
        if let Ok(rd) = std::fs::read_dir(&fs_path) {
            for e in rd.flatten() {
                let name = e.file_name().to_string_lossy().to_string();
                if !conf.show_hidden && name.starts_with('.') {
                    continue;
                }
                let lmd = match e.metadata() {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                if conf.no_symlinks && lmd.file_type().is_symlink() {
                    continue;
                }
                let cmd = match std::fs::metadata(e.path()) {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                let mut href = format!("{}{}", href_base, name);
                if cmd.is_dir() {
                    href.push('/');
                }
                parts.push(response_entry(&encode_href_path(&href), &cmd, &e.path(), &preq));
            }
        }
    }
    parts.push("</D:multistatus>".to_string());
    let mut r = Response::new(207);
    if let Some(cl) = content_location {
        r.set_header("content-location", &cl);
    }
    r.set_header("content-type", "application/xml; charset=utf-8");
    r.set_header("cache-control", "no-cache");
    r.set_header("pragma", "no-cache");
    r.body = Body::Stream(Box::new(move |w| {
        for p in parts {
            w.write_all(p.as_bytes())?;
        }
        Ok(())
    }));
    Some(r)
}
