//! A CommonMark renderer modelled on the reference implementation (cmark),
//! producing the same HTML as comrak with default options.

use std::collections::HashMap;

// ---------------------------------------------------------------------------
// Block structure
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq)]
struct ListData {
    ordered: bool,
    bullet: char,
    delim: char,
    start: u64,
    padding: usize, // column offset of content relative to item start
    marker_offset: usize,
    tight: bool,
}

#[derive(Debug)]
enum Kind {
    Document,
    BlockQuote,
    List(ListData),
    Item(ListData),
    Paragraph,
    Heading(u8, bool /*setext*/),
    ThematicBreak,
    CodeBlock { fenced: bool, fence_char: char, fence_len: usize, fence_offset: usize, info: String },
    HtmlBlock(u8),
}

struct Node {
    kind: Kind,
    children: Vec<usize>,
    parent: Option<usize>,
    open: bool,
    content: String,
    last_line_blank: bool,
}

struct Parser {
    nodes: Vec<Node>,
    tip: usize,
    refs: HashMap<String, (String, Option<String>)>,
    // current line state
    line: Vec<char>,
    offset: usize,
    column: usize,
    next_nonspace: usize,
    next_nonspace_column: usize,
    indent: usize,
    blank: bool,
    partially_consumed_tab: bool,
    last_matched: usize,
}

fn is_space_or_tab(c: Option<char>) -> bool {
    matches!(c, Some(' ') | Some('\t'))
}

impl Parser {
    fn new() -> Parser {
        let doc = Node { kind: Kind::Document, children: vec![], parent: None, open: true, content: String::new(), last_line_blank: false };
        Parser {
            nodes: vec![doc],
            tip: 0,
            refs: HashMap::new(),
            line: vec![],
            offset: 0,
            column: 0,
            next_nonspace: 0,
            next_nonspace_column: 0,
            indent: 0,
            blank: false,
            partially_consumed_tab: false,
            last_matched: 0,
        }
    }

    fn peek(&self, i: usize) -> Option<char> {
        self.line.get(i).copied()
    }

    fn find_next_nonspace(&mut self) {
        let mut i = self.offset;
        let mut cols = self.column;
        loop {
            match self.peek(i) {
                Some(' ') => {
                    i += 1;
                    cols += 1;
                }
                Some('\t') => {
                    i += 1;
                    cols += 4 - (cols % 4);
                }
                _ => break,
            }
        }
        self.blank = matches!(self.peek(i), None | Some('\n') | Some('\r'));
        self.next_nonspace = i;
        self.next_nonspace_column = cols;
        self.indent = self.next_nonspace_column - self.column;
    }

    fn advance_offset(&mut self, mut count: usize, columns: bool) {
        while count > 0 {
            match self.peek(self.offset) {
                Some('\t') => {
                    let chars_to_tab = 4 - (self.column % 4);
                    if columns {
                        self.partially_consumed_tab = chars_to_tab > count;
                        let chars_to_advance = std::cmp::min(count, chars_to_tab);
                        self.column += chars_to_advance;
                        if !self.partially_consumed_tab {
                            self.offset += 1;
                        }
                        count -= chars_to_advance;
                    } else {
                        self.partially_consumed_tab = false;
                        self.column += chars_to_tab;
                        self.offset += 1;
                        count -= 1;
                    }
                }
                Some(_) => {
                    self.partially_consumed_tab = false;
                    self.offset += 1;
                    self.column += 1;
                    count -= 1;
                }
                None => break,
            }
        }
    }

    fn advance_next_nonspace(&mut self) {
        self.offset = self.next_nonspace;
        self.column = self.next_nonspace_column;
        self.partially_consumed_tab = false;
    }

    fn add_child(&mut self, kind: Kind) -> usize {
        // close tip while it can't contain the new kind
        while !self.can_contain(self.tip, &kind) {
            let t = self.tip;
            self.finalize(t);
        }
        let id = self.nodes.len();
        self.nodes.push(Node { kind, children: vec![], parent: Some(self.tip), open: true, content: String::new(), last_line_blank: false });
        let tip = self.tip;
        self.nodes[tip].children.push(id);
        self.tip = id;
        id
    }

    fn can_contain(&self, parent: usize, child: &Kind) -> bool {
        match &self.nodes[parent].kind {
            Kind::Document | Kind::BlockQuote | Kind::Item(_) => !matches!(child, Kind::Item(_)),
            Kind::List(_) => matches!(child, Kind::Item(_)),
            _ => false,
        }
    }

    fn accepts_lines(&self, n: usize) -> bool {
        matches!(self.nodes[n].kind, Kind::Paragraph | Kind::CodeBlock { .. } | Kind::HtmlBlock(_))
    }

    fn rest_of_line(&self) -> String {
        let mut s: String = String::new();
        if self.partially_consumed_tab {
            let chars_to_tab = 4 - (self.column % 4);
            for _ in 0..chars_to_tab {
                s.push(' ');
            }
            s.extend(self.line[self.offset + 1..].iter());
        } else {
            s.extend(self.line[self.offset..].iter());
        }
        s
    }

    fn add_line(&mut self) {
        let rest = self.rest_of_line();
        let tip = self.tip;
        self.nodes[tip].content.push_str(&rest);
        self.nodes[tip].content.push('\n');
    }

    fn finalize(&mut self, n: usize) {
        let parent = self.nodes[n].parent;
        self.nodes[n].open = false;
        match &self.nodes[n].kind {
            Kind::Paragraph => {
                // extract link reference definitions
                let mut content = std::mem::take(&mut self.nodes[n].content);
                loop {
                    if !content.starts_with('[') {
                        break;
                    }
                    match parse_reference(&content) {
                        Some((consumed, label, dest, title)) => {
                            let key = normalize_label(&label);
                            if !key.is_empty() {
                                self.refs.entry(key).or_insert((dest, title));
                            }
                            content = content[consumed..].to_string();
                        }
                        None => break,
                    }
                }
                self.nodes[n].content = content;
            }
            Kind::CodeBlock { fenced, .. } => {
                let fenced = *fenced;
                let content = std::mem::take(&mut self.nodes[n].content);
                if fenced {
                    // first line is the info string
                    let (first, rest) = match content.find('\n') {
                        Some(i) => (content[..i].to_string(), content[i + 1..].to_string()),
                        None => (content.clone(), String::new()),
                    };
                    let info = unescape_string(first.trim());
                    if let Kind::CodeBlock { info: ref mut inf, .. } = self.nodes[n].kind {
                        *inf = info;
                    }
                    self.nodes[n].content = rest;
                } else {
                    // remove trailing blank lines
                    let mut lines: Vec<&str> = content.split('\n').collect();
                    if lines.last() == Some(&"") {
                        lines.pop();
                    }
                    while let Some(l) = lines.last() {
                        if l.trim_matches(|c| c == ' ' || c == '\t').is_empty() {
                            lines.pop();
                        } else {
                            break;
                        }
                    }
                    let mut s = lines.join("\n");
                    s.push('\n');
                    self.nodes[n].content = s;
                }
            }
            Kind::List(_) => {
                let tight = self.list_is_tight(n);
                if let Kind::List(ref mut ld) = self.nodes[n].kind {
                    ld.tight = tight;
                }
            }
            _ => {}
        }
        if let Some(p) = parent {
            self.tip = p;
        }
    }

    fn ends_with_blank_line(&self, n: usize) -> bool {
        let mut cur = n;
        loop {
            if self.nodes[cur].last_line_blank {
                return true;
            }
            match &self.nodes[cur].kind {
                Kind::List(_) | Kind::Item(_) => match self.nodes[cur].children.last() {
                    Some(&c) => cur = c,
                    None => return false,
                },
                _ => return false,
            }
        }
    }

    fn list_is_tight(&self, n: usize) -> bool {
        let items = &self.nodes[n].children;
        for (i, &item) in items.iter().enumerate() {
            if self.nodes[item].last_line_blank && i + 1 < items.len() {
                return false;
            }
            let subs = &self.nodes[item].children;
            for (j, &sub) in subs.iter().enumerate() {
                let last_item = i + 1 == items.len();
                let last_sub = j + 1 == subs.len();
                if (!last_item || !last_sub) && self.ends_with_blank_line(sub) {
                    return false;
                }
            }
        }
        true
    }

    fn close_unmatched(&mut self) {
        while self.tip != self.last_matched {
            let t = self.tip;
            self.finalize(t);
            if self.tip == t {
                break;
            }
        }
    }

    /// Returns 0 = matched, 1 = not matched, 2 = matched & line consumed (fence end)
    fn continue_block(&mut self, n: usize) -> u8 {
        match &self.nodes[n].kind {
            Kind::Document => 0,
            Kind::BlockQuote => {
                self.find_next_nonspace();
                if self.indent <= 3 && self.peek(self.next_nonspace) == Some('>') {
                    self.advance_next_nonspace();
                    self.advance_offset(1, false);
                    if is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                    0
                } else {
                    1
                }
            }
            Kind::List(_) => 0,
            Kind::Item(ld) => {
                let (mo, pad) = (ld.marker_offset, ld.padding);
                self.find_next_nonspace();
                if self.blank {
                    if self.nodes[n].children.is_empty() {
                        return 1;
                    }
                    self.advance_next_nonspace();
                    0
                } else if self.indent >= mo + pad {
                    self.advance_offset(mo + pad, true);
                    0
                } else {
                    1
                }
            }
            Kind::Heading(..) | Kind::ThematicBreak => 1,
            Kind::CodeBlock { fenced, fence_char, fence_len, fence_offset, .. } => {
                let (fenced, fc, fl, fo) = (*fenced, *fence_char, *fence_len, *fence_offset);
                self.find_next_nonspace();
                if fenced {
                    // closing fence?
                    if self.indent <= 3 && self.peek(self.next_nonspace) == Some(fc) {
                        let mut j = self.next_nonspace;
                        let mut cnt = 0;
                        while self.peek(j) == Some(fc) {
                            j += 1;
                            cnt += 1;
                        }
                        let mut k = j;
                        while is_space_or_tab(self.peek(k)) {
                            k += 1;
                        }
                        if cnt >= fl && matches!(self.peek(k), None | Some('\n')) {
                            let t = n;
                            self.finalize(t);
                            return 2;
                        }
                    }
                    // skip optional spaces of fence offset
                    let mut i = fo;
                    while i > 0 && is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                        i -= 1;
                    }
                    0
                } else if self.indent >= 4 {
                    self.advance_offset(4, true);
                    0
                } else if self.blank {
                    self.advance_next_nonspace();
                    0
                } else {
                    1
                }
            }
            Kind::HtmlBlock(t) => {
                let t = *t;
                if self.blank && (t == 6 || t == 7) {
                    1
                } else {
                    0
                }
            }
            Kind::Paragraph => {
                self.find_next_nonspace();
                if self.blank {
                    1
                } else {
                    0
                }
            }
        }
    }

    fn incorporate_line(&mut self, line: &str) {
        self.line = line.chars().collect();
        self.offset = 0;
        self.column = 0;
        self.blank = false;
        self.partially_consumed_tab = false;

        // 1. match open containers
        let mut container = 0usize;
        let mut all_matched = true;
        loop {
            let last_child = match self.nodes[container].children.last() {
                Some(&c) if self.nodes[c].open => c,
                _ => break,
            };
            container = last_child;
            match self.continue_block(container) {
                0 => {}
                1 => {
                    container = self.nodes[container].parent.unwrap();
                    all_matched = false;
                    break;
                }
                _ => return, // fenced code closed; line consumed
            }
        }
        let _ = all_matched;
        self.last_matched = container;
        let mut matched_leaf = matches!(self.nodes[container].kind, Kind::Paragraph) == false && self.accepts_lines(container);

        // 2. try new block starts
        while !matched_leaf {
            self.find_next_nonspace();
            let nn = self.next_nonspace;
            let c = self.peek(nn);
            if self.indent >= 4 {
                if !matches!(self.nodes[self.tip].kind, Kind::Paragraph) && !self.blank {
                    // indented code block
                    self.advance_offset(4, true);
                    self.close_unmatched();
                    self.add_child(Kind::CodeBlock { fenced: false, fence_char: ' ', fence_len: 0, fence_offset: 0, info: String::new() });
                    container = self.tip;
                    matched_leaf = true;
                    continue;
                }
                break;
            }
            match c {
                Some('>') => {
                    self.advance_next_nonspace();
                    self.advance_offset(1, false);
                    if is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                    self.close_unmatched();
                    container = self.add_child(Kind::BlockQuote);
                    continue;
                }
                Some('#') => {
                    let mut j = nn;
                    let mut lvl = 0;
                    while self.peek(j) == Some('#') && lvl < 7 {
                        j += 1;
                        lvl += 1;
                    }
                    if lvl >= 1 && lvl <= 6 && matches!(self.peek(j), None | Some(' ') | Some('\t') | Some('\n')) {
                        self.advance_next_nonspace();
                        self.advance_offset(lvl, false);
                        self.close_unmatched();
                        let h = self.add_child(Kind::Heading(lvl as u8, false));
                        let rest: String = self.line[self.offset..].iter().collect();
                        let rest = rest.trim_end_matches('\n');
                        let mut t = rest.trim_matches(|c| c == ' ' || c == '\t').to_string();
                        // strip closing sequence
                        let trimmed = t.trim_end_matches('#');
                        if trimmed.is_empty() {
                            t = String::new();
                        } else if trimmed.ends_with(' ') || trimmed.ends_with('\t') {
                            t = trimmed.trim_end_matches(|c| c == ' ' || c == '\t').to_string();
                        }
                        self.nodes[h].content = t;
                        self.offset = self.line.len();
                        container = h;
                        matched_leaf = true;
                        continue;
                    }
                }
                Some('`') | Some('~') => {
                    let fc = c.unwrap();
                    let mut j = nn;
                    let mut cnt = 0;
                    while self.peek(j) == Some(fc) {
                        j += 1;
                        cnt += 1;
                    }
                    let rest: String = self.line[j..].iter().collect();
                    if cnt >= 3 && !(fc == '`' && rest.contains('`')) {
                        let fence_offset = self.indent;
                        self.close_unmatched();
                        let cb = self.add_child(Kind::CodeBlock { fenced: true, fence_char: fc, fence_len: cnt, fence_offset, info: String::new() });
                        self.advance_next_nonspace();
                        self.advance_offset(cnt, false);
                        container = cb;
                        matched_leaf = true;
                        continue;
                    }
                }
                Some('<') => {
                    let rest: String = self.line[nn..].iter().collect();
                    let is_para = matches!(self.nodes[self.tip].kind, Kind::Paragraph);
                    if let Some(t) = html_block_start(&rest, is_para && !std::ptr::eq(&self.nodes[container], &self.nodes[self.tip]) || is_para) {
                        self.close_unmatched();
                        let hb = self.add_child(Kind::HtmlBlock(t));
                        container = hb;
                        matched_leaf = true;
                        continue;
                    }
                }
                _ => {}
            }
            // setext heading underline
            if matches!(self.nodes[container].kind, Kind::Paragraph) && (c == Some('=') || c == Some('-')) {
                let rest: String = self.line[nn..].iter().collect();
                let r = rest.trim_end_matches(['\n', ' ', '\t']);
                let ch = c.unwrap();
                if !r.is_empty() && r.chars().all(|x| x == ch) {
                    // the paragraph may consist only of reference definitions
                    let para = container;
                    let content = self.nodes[para].content.clone();
                    let mut probe = content.clone();
                    loop {
                        if !probe.starts_with('[') {
                            break;
                        }
                        match parse_reference(&probe) {
                            Some((consumed, label, dest, title)) => {
                                let key = normalize_label(&label);
                                if !key.is_empty() {
                                    self.refs.entry(key).or_insert((dest, title));
                                }
                                probe = probe[consumed..].to_string();
                            }
                            None => break,
                        }
                    }
                    if !probe.trim().is_empty() {
                        self.close_unmatched();
                        self.nodes[para].kind = Kind::Heading(if ch == '=' { 1 } else { 2 }, true);
                        self.nodes[para].content = probe;
                        self.offset = self.line.len();
                        matched_leaf = true;
                        continue;
                    } else {
                        self.nodes[para].content = probe;
                    }
                }
            }
            // thematic break
            if matches!(c, Some('*') | Some('-') | Some('_')) {
                let ch = c.unwrap();
                let rest: String = self.line[nn..].iter().collect();
                let cnt = rest.chars().filter(|&x| x == ch).count();
                if cnt >= 3 && rest.trim_end_matches('\n').chars().all(|x| x == ch || x == ' ' || x == '\t') {
                    self.close_unmatched();
                    let tb = self.add_child(Kind::ThematicBreak);
                    self.offset = self.line.len();
                    container = tb;
                    matched_leaf = true;
                    continue;
                }
            }
            // list item
            let is_para = matches!(self.nodes[container].kind, Kind::Paragraph);
            if let Some((ld, marker_len)) = self.parse_list_marker(is_para) {
                self.advance_next_nonspace();
                self.advance_offset(marker_len, true);
                // compute padding
                let spaces_start_col = self.column;
                let spaces_start_offset = self.offset;
                loop {
                    self.advance_offset(1, true);
                    let next = self.peek(self.offset);
                    if !(self.column - spaces_start_col < 5 && is_space_or_tab(next)) {
                        break;
                    }
                }
                let blank_item = matches!(self.peek(self.offset), None | Some('\n'));
                let spaces_after_marker = self.column - spaces_start_col;
                let mut ld = ld;
                if spaces_after_marker >= 5 || spaces_after_marker < 1 || blank_item {
                    ld.padding = marker_len + 1;
                    self.column = spaces_start_col;
                    self.offset = spaces_start_offset;
                    if is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                } else {
                    ld.padding = marker_len + spaces_after_marker;
                }
                self.close_unmatched();
                let need_new_list = match &self.nodes[self.tip].kind {
                    Kind::List(pld) => !(pld.ordered == ld.ordered && pld.bullet == ld.bullet && pld.delim == ld.delim),
                    _ => true,
                };
                if need_new_list {
                    if matches!(self.nodes[self.tip].kind, Kind::List(_)) {
                        let t = self.tip;
                        self.finalize(t);
                    }
                    self.add_child(Kind::List(ld.clone()));
                }
                container = self.add_child(Kind::Item(ld));
                continue;
            }
            break;
        }

        // 3. add text
        self.find_next_nonspace();
        let blank = self.blank;
        let _ = self.next_nonspace;
        // propagate last_line_blank
        if blank {
            if let Some(&lc) = self.nodes[container].children.last() {
                self.nodes[lc].last_line_blank = true;
            }
        }
        let last_line_blank = blank
            && !matches!(self.nodes[container].kind, Kind::BlockQuote | Kind::Heading(..) | Kind::ThematicBreak)
            && !matches!(self.nodes[container].kind, Kind::CodeBlock { fenced: true, .. })
            && !(matches!(self.nodes[container].kind, Kind::Item(_)) && self.nodes[container].children.is_empty());
        self.nodes[container].last_line_blank = last_line_blank;
        let mut cont = container;
        while let Some(p) = self.nodes[cont].parent {
            self.nodes[p].last_line_blank = false;
            cont = p;
        }

        let tip_is_para = matches!(self.nodes[self.tip].kind, Kind::Paragraph);
        if self.tip != self.last_matched && !blank && tip_is_para {
            // lazy continuation
            self.add_line();
            return;
        }
        self.close_unmatched();
        if matches!(self.nodes[container].kind, Kind::Heading(..) | Kind::ThematicBreak) {
            if matches!(self.nodes[container].kind, Kind::Heading(_, true)) {
                // setext already handled
            }
            let t = container;
            if self.nodes[t].open && matches!(self.nodes[t].kind, Kind::ThematicBreak | Kind::Heading(_, false)) {
                self.finalize(t);
            }
            return;
        }
        if self.accepts_lines(container) {
            if let Kind::HtmlBlock(t) = self.nodes[container].kind {
                self.add_line();
                let rest: String = self.line[self.offset..].iter().collect();
                if html_block_end(t, &rest) {
                    let c = container;
                    self.finalize(c);
                }
                return;
            }
            if matches!(self.nodes[container].kind, Kind::Paragraph) {
                // strip leading whitespace
                self.advance_next_nonspace();
            }
            self.add_line();
            return;
        }
        if !blank {
            self.advance_next_nonspace();
            self.add_child(Kind::Paragraph);
            self.add_line();
        }
    }

    fn parse_list_marker(&self, interrupts_paragraph: bool) -> Option<(ListData, usize)> {
        let nn = self.next_nonspace;
        let c = self.peek(nn)?;
        let (ld, len) = if c == '*' || c == '+' || c == '-' {
            (ListData { ordered: false, bullet: c, delim: ' ', start: 0, padding: 0, marker_offset: self.indent, tight: true }, 1)
        } else if c.is_ascii_digit() {
            let mut j = nn;
            let mut digits = String::new();
            while let Some(d) = self.peek(j) {
                if d.is_ascii_digit() && digits.len() < 9 {
                    digits.push(d);
                    j += 1;
                } else {
                    break;
                }
            }
            let d = self.peek(j)?;
            if (d != '.' && d != ')') || (self.peek(j).map(|x| x.is_ascii_digit()).unwrap_or(false)) {
                return None;
            }
            let start: u64 = digits.parse().ok()?;
            if interrupts_paragraph && start != 1 {
                return None;
            }
            (ListData { ordered: true, bullet: ' ', delim: d, start, padding: 0, marker_offset: self.indent, tight: true }, digits.len() + 1)
        } else {
            return None;
        };
        let after = self.peek(nn + len);
        if !matches!(after, None | Some(' ') | Some('\t') | Some('\n')) {
            return None;
        }
        if interrupts_paragraph {
            // must not be blank
            let mut k = nn + len;
            while is_space_or_tab(self.peek(k)) {
                k += 1;
            }
            if matches!(self.peek(k), None | Some('\n')) {
                return None;
            }
        }
        Some((ld, len))
    }
}

fn html_block_start(s: &str, in_paragraph: bool) -> Option<u8> {
    let lower = s.to_ascii_lowercase();
    for t in ["<script", "<pre", "<style", "<textarea"] {
        if lower.starts_with(t) {
            let next = lower[t.len()..].chars().next();
            if matches!(next, None | Some(' ') | Some('\t') | Some('>') | Some('\n')) {
                return Some(1);
            }
        }
    }
    if s.starts_with("<!--") {
        return Some(2);
    }
    if s.starts_with("<?") {
        return Some(3);
    }
    if s.starts_with("<!") && s[2..].chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false) {
        return Some(4);
    }
    if s.starts_with("<![CDATA[") {
        return Some(5);
    }
    const BLOCK_TAGS: &[&str] = &[
        "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col", "colgroup", "dd",
        "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure", "footer", "form", "frame",
        "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link",
        "main", "menu", "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
        "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
    ];
    let rest = if let Some(r) = lower.strip_prefix("</") { r } else { lower.strip_prefix('<').unwrap_or("") };
    let name: String = rest.chars().take_while(|c| c.is_ascii_alphanumeric()).collect();
    if !name.is_empty() && BLOCK_TAGS.contains(&name.as_str()) {
        let after = &rest[name.len()..];
        if after.is_empty() || after.starts_with(' ') || after.starts_with('\t') || after.starts_with('\n') || after.starts_with('>') || after.starts_with("/>") {
            return Some(6);
        }
    }
    if !in_paragraph {
        let line = s.trim_end_matches('\n');
        if let Some(n) = match_html_tag(line) {
            if line[n..].trim_matches(|c| c == ' ' || c == '\t').is_empty() {
                return Some(7);
            }
        }
    }
    None
}

fn html_block_end(t: u8, s: &str) -> bool {
    let lower = s.to_ascii_lowercase();
    match t {
        1 => lower.contains("</script>") || lower.contains("</pre>") || lower.contains("</style>") || lower.contains("</textarea>"),
        2 => s.contains("-->"),
        3 => s.contains("?>"),
        4 => s.contains('>'),
        5 => s.contains("]]>"),
        _ => false,
    }
}

/// Matches an HTML open/closing tag, comment, PI, declaration or CDATA at the
/// start of s; returns its length in bytes.
fn match_html_tag(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.first() != Some(&b'<') {
        return None;
    }
    if s.starts_with("<!--") {
        if s.starts_with("<!-->") {
            return Some(5);
        }
        if s.starts_with("<!--->") {
            return Some(6);
        }
        return s[4..].find("-->").map(|i| 4 + i + 3);
    }
    if s.starts_with("<?") {
        return s[2..].find("?>").map(|i| 2 + i + 2);
    }
    if s.starts_with("<![CDATA[") {
        return s[9..].find("]]>").map(|i| 9 + i + 3);
    }
    if s.starts_with("<!") && b.get(2).map(|c| c.is_ascii_alphabetic()).unwrap_or(false) {
        return s[2..].find('>').map(|i| 2 + i + 1);
    }
    let mut i = 1;
    let closing = b.get(1) == Some(&b'/');
    if closing {
        i += 1;
    }
    if !b.get(i).map(|c| c.is_ascii_alphabetic()).unwrap_or(false) {
        return None;
    }
    while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'-') {
        i += 1;
    }
    if closing {
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        return if b.get(i) == Some(&b'>') { Some(i + 1) } else { None };
    }
    // attributes
    loop {
        let ws_start = i;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            i += 1;
        }
        if b.get(i) == Some(&b'>') {
            return Some(i + 1);
        }
        if b.get(i) == Some(&b'/') && b.get(i + 1) == Some(&b'>') {
            return Some(i + 2);
        }
        if i == ws_start {
            return None;
        }
        // attribute name
        if !b.get(i).map(|c| c.is_ascii_alphabetic() || *c == b'_' || *c == b':').unwrap_or(false) {
            return None;
        }
        while i < b.len() && (b[i].is_ascii_alphanumeric() || b"_.:-".contains(&b[i])) {
            i += 1;
        }
        // optional value
        let mut j = i;
        while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
            j += 1;
        }
        if b.get(j) == Some(&b'=') {
            j += 1;
            while j < b.len() && (b[j] == b' ' || b[j] == b'\t' || b[j] == b'\n') {
                j += 1;
            }
            match b.get(j) {
                Some(&b'"') => {
                    let end = s[j + 1..].find('"')?;
                    j = j + 1 + end + 1;
                }
                Some(&b'\'') => {
                    let end = s[j + 1..].find('\'')?;
                    j = j + 1 + end + 1;
                }
                Some(_) => {
                    let start = j;
                    while j < b.len() && !b" \t\n\"'=<>`".contains(&b[j]) {
                        j += 1;
                    }
                    if j == start {
                        return None;
                    }
                }
                None => return None,
            }
            i = j;
        }
    }
}

// ---------------------------------------------------------------------------
// Link reference definitions
// ---------------------------------------------------------------------------

fn normalize_label(s: &str) -> String {
    let collapsed: Vec<&str> = s.split_whitespace().collect();
    let joined = collapsed.join(" ");
    joined.to_lowercase().replace('ß', "ss")
}

fn scan_link_label(s: &str) -> Option<(usize, String)> {
    // s starts with '['
    let b = s.as_bytes();
    let mut i = 1;
    let mut n = 0;
    while i < b.len() {
        match b[i] {
            b'\\' => {
                i += 2;
                n += 2;
                continue;
            }
            b'[' => return None,
            b']' => {
                if n > 999 {
                    return None;
                }
                let label = s[1..i].to_string();
                if label.trim().is_empty() {
                    return None;
                }
                return Some((i + 1, label));
            }
            _ => {}
        }
        i += 1;
        n += 1;
    }
    None
}

fn skip_spaces_one_newline(s: &str, mut i: usize) -> usize {
    let b = s.as_bytes();
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
        i += 1;
    }
    if i < b.len() && b[i] == b'\n' {
        i += 1;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
            i += 1;
        }
    }
    i
}

fn scan_link_destination(s: &str, i: usize) -> Option<(usize, String)> {
    let b = s.as_bytes();
    if i < b.len() && b[i] == b'<' {
        let mut j = i + 1;
        while j < b.len() {
            match b[j] {
                b'\\' if j + 1 < b.len() => j += 2,
                b'>' => return Some((j + 1, unescape_string(&s[i + 1..j]))),
                b'<' | b'\n' => return None,
                _ => j += 1,
            }
        }
        return None;
    }
    let mut j = i;
    let mut parens = 0;
    while j < b.len() {
        let c = b[j];
        if c == b'\\' && j + 1 < b.len() && (b[j + 1] as char).is_ascii_punctuation() {
            j += 2;
            continue;
        }
        if c == b'(' {
            parens += 1;
            if parens > 32 {
                return None;
            }
        } else if c == b')' {
            if parens == 0 {
                break;
            }
            parens -= 1;
        } else if c <= b' ' {
            break;
        }
        j += 1;
    }
    if j == i || parens != 0 {
        if j == i {
            return None;
        }
        return None;
    }
    Some((j, unescape_string(&s[i..j])))
}

fn scan_link_title(s: &str, i: usize) -> Option<(usize, String)> {
    let b = s.as_bytes();
    let open = *b.get(i)?;
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut j = i + 1;
    while j < b.len() {
        if b[j] == b'\\' && j + 1 < b.len() {
            j += 2;
            continue;
        }
        if b[j] == close {
            return Some((j + 1, unescape_string(&s[i + 1..j])));
        }
        if open == b'(' && b[j] == b'(' {
            return None;
        }
        j += 1;
    }
    None
}

/// Parses a link reference definition at the start of s.
fn parse_reference(s: &str) -> Option<(usize, String, String, Option<String>)> {
    let (mut i, label) = scan_link_label(s)?;
    if s.as_bytes().get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    i = skip_spaces_one_newline(s, i);
    let (j, dest) = scan_link_destination(s, i)?;
    if j == i && !s[i..].starts_with("<>") {
        return None;
    }
    let after_dest = j;
    let k = skip_spaces_one_newline(s, after_dest);
    let mut title = None;
    let mut end = after_dest;
    if k > after_dest {
        if let Some((t_end, t)) = scan_link_title(s, k) {
            // rest of line must be blank
            let mut m = t_end;
            let b = s.as_bytes();
            while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
                m += 1;
            }
            if m >= b.len() || b[m] == b'\n' {
                title = Some(t);
                end = if m < b.len() { m + 1 } else { m };
            }
        }
    }
    if title.is_none() {
        let b = s.as_bytes();
        let mut m = after_dest;
        while m < b.len() && (b[m] == b' ' || b[m] == b'\t') {
            m += 1;
        }
        if m < b.len() && b[m] != b'\n' {
            return None;
        }
        end = if m < b.len() { m + 1 } else { m };
    }
    Some((end, label, dest, title))
}

