        "ensp" => "\u{2002}",
        "emsp" => "\u{2003}",
        "thinsp" => "\u{2009}",
        "zwnj" => "\u{200c}",
        "zwj" => "\u{200d}",
        _ => return None,
    })
}

/// Try to parse an entity at s (starting with '&'); returns (len, decoded)
fn parse_entity(s: &str) -> Option<(usize, String)> {
    let b = s.as_bytes();
    if b.first() != Some(&b'&') {
        return None;
    }
    if b.get(1) == Some(&b'#') {
        let (hex, start) = if matches!(b.get(2), Some(b'x') | Some(b'X')) { (true, 3) } else { (false, 2) };
        let mut j = start;
        while j < b.len() && (if hex { b[j].is_ascii_hexdigit() } else { b[j].is_ascii_digit() }) {
            j += 1;
        }
        let ndigits = j - start;
        if ndigits == 0 || ndigits > (if hex { 6 } else { 7 }) || b.get(j) != Some(&b';') {
            return None;
        }
        let v = u32::from_str_radix(&s[start..j], if hex { 16 } else { 10 }).ok()?;
        let c = if v == 0 { '\u{fffd}' } else { char::from_u32(v).unwrap_or('\u{fffd}') };
        return Some((j + 1, c.to_string()));
    }
    let mut j = 1;
    while j < b.len() && b[j].is_ascii_alphanumeric() {
        j += 1;
    }
    if j == 1 || b.get(j) != Some(&b';') {
        return None;
    }
    entity(&s[1..j]).map(|e| (j + 1, e.to_string()))
}

fn unescape_string(s: &str) -> String {
    let mut out = String::new();
    let mut i = 0;
    let b = s.as_bytes();
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() && (b[i + 1] as char).is_ascii_punctuation() {
            out.push(b[i + 1] as char);
            i += 2;
            continue;
        }
        if b[i] == b'&' {
            if let Some((len, dec)) = parse_entity(&s[i..]) {
                out.push_str(&dec);
                i += len;
                continue;
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}

fn escape_html(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            _ => o.push(c),
        }
    }
    o
}

fn escape_href(s: &str) -> String {
    let mut o = String::new();
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b'%' && i + 2 < b.len() + 0 && i + 2 < b.len() + 1 && b.get(i + 1).map(|x| x.is_ascii_hexdigit()).unwrap_or(false) && b.get(i + 2).map(|x| x.is_ascii_hexdigit()).unwrap_or(false) {
            o.push('%');
            i += 1;
            continue;
        }
        if c.is_ascii_alphanumeric() || b"-_.+!*(),%#@?=;:/,$~'".contains(&c) {
            o.push(c as char);
        } else if c == b'&' {
            o.push_str("&amp;");
        } else if c == b'[' || c == b']' {
            o.push(c as char);
        } else {
            o.push_str(&format!("%{:02X}", c));
        }
        i += 1;
    }
    o
}

fn is_dangerous_url(url: &str, image: bool) -> bool {
    let lower = url.trim().to_ascii_lowercase();
    if lower.starts_with("javascript:") || lower.starts_with("vbscript:") || lower.starts_with("file:") {
        return true;
    }
    if lower.starts_with("data:") {
        if image {
            for ok in ["data:image/png", "data:image/gif", "data:image/jpeg", "data:image/webp"] {
                if lower.starts_with(ok) {
                    return false;
                }
            }
        }
        return true;
    }
    false
}

// ---------------------------------------------------------------------------
// Inlines
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Inline {
    Text(String),
    Code(String),
    Html,
    SoftBreak,
    HardBreak,
    Emph(Vec<Inline>),
    Strong(Vec<Inline>),
    Link { url: String, title: Option<String>, children: Vec<Inline> },
    Image { url: String, title: Option<String>, children: Vec<Inline> },
}

struct Delim {
    pos: usize, // index into nodes list
    ch: char,
    count: usize,
    orig_count: usize,
    can_open: bool,
    can_close: bool,
    active: bool,
}

struct Bracket {
    pos: usize,
    image: bool,
    active: bool,
    text_start: usize, // byte offset in source after '['
    delim_bottom: usize,
}

enum Tok {
    Node(Inline),
    DelimText(String), // placeholder text for delimiter runs
}

struct InlineParser<'a> {
    src: &'a str,
    pos: usize,
    toks: Vec<Tok>,
    delims: Vec<Delim>,
    brackets: Vec<Bracket>,
    refs: &'a HashMap<String, (String, Option<String>)>,
}

fn is_punct(c: char) -> bool {
    c.is_ascii_punctuation() || (!c.is_ascii() && (c.is_alphanumeric() == false && !c.is_whitespace()))
}

impl<'a> InlineParser<'a> {
    fn push_text(&mut self, s: &str) {
        if let Some(Tok::Node(Inline::Text(t))) = self.toks.last_mut() {
            t.push_str(s);
            return;
        }
        self.toks.push(Tok::Node(Inline::Text(s.to_string())));
    }

    fn parse(&mut self) {
        let b = self.src.as_bytes();
        while self.pos < b.len() {
            let c = b[self.pos];
            match c {
                b'\n' => {
                    // check for hard break: two+ spaces before
                    let mut hard = false;
                    if let Some(Tok::Node(Inline::Text(t))) = self.toks.last_mut() {
                        let trimmed = t.trim_end_matches(' ');
                        let spaces = t.len() - trimmed.len();
                        if spaces >= 2 {
                            hard = true;
                        }
                        let tl = trimmed.len();
                        t.truncate(tl);
                    }
                    self.toks.push(Tok::Node(if hard { Inline::HardBreak } else { Inline::SoftBreak }));
                    self.pos += 1;
                    while self.pos < b.len() && b[self.pos] == b' ' {
                        self.pos += 1;
                    }
                }
                b'\\' => {
                    if self.pos + 1 < b.len() && b[self.pos + 1] == b'\n' {
                        self.toks.push(Tok::Node(Inline::HardBreak));
                        self.pos += 2;
                        while self.pos < b.len() && b[self.pos] == b' ' {
                            self.pos += 1;
                        }
                    } else if self.pos + 1 < b.len() && (b[self.pos + 1] as char).is_ascii_punctuation() {
                        let s = (b[self.pos + 1] as char).to_string();
                        self.push_text(&s);
                        self.pos += 2;
                    } else {
                        self.push_text("\\");
                        self.pos += 1;
                    }
                }
                b'`' => self.parse_code(),
                b'&' => {
                    if let Some((len, dec)) = parse_entity(&self.src[self.pos..]) {
                        self.push_text(&dec);
                        self.pos += len;
                    } else {
                        self.push_text("&");
                        self.pos += 1;
                    }
                }
                b'<' => {
                    if !self.parse_autolink_or_html() {
                        self.push_text("<");
                        self.pos += 1;
                    }
                }
                b'*' | b'_' => self.parse_delim_run(c as char),
                b'[' => {
                    self.toks.push(Tok::Node(Inline::Text("[".to_string())));
                    let p = self.toks.len() - 1;
                    self.pos += 1;
                    self.brackets.push(Bracket { pos: p, image: false, active: true, text_start: self.pos, delim_bottom: self.delims.len() });
                    // prevent merging following text into this token
                    self.toks.push(Tok::Node(Inline::Text(String::new())));
                }
                b'!' if b.get(self.pos + 1) == Some(&b'[') => {
                    self.toks.push(Tok::Node(Inline::Text("![".to_string())));
                    let p = self.toks.len() - 1;
                    self.pos += 2;
                    self.brackets.push(Bracket { pos: p, image: true, active: true, text_start: self.pos, delim_bottom: self.delims.len() });
                    self.toks.push(Tok::Node(Inline::Text(String::new())));
                }
                b']' => self.parse_close_bracket(),
                _ => {
                    let start = self.pos;
                    while self.pos < b.len() && !b"\n\\`&<*_[]!".contains(&b[self.pos]) {
                        self.pos += 1;
                    }
                    if self.pos == start {
                        // a lone '!'
                        let ch = self.src[self.pos..].chars().next().unwrap();
                        self.pos += ch.len_utf8();
                        self.push_text(&ch.to_string());
                    } else {
                        let s = self.src[start..self.pos].to_string();
                        self.push_text(&s);
                    }
                }
            }
        }
    }

    fn parse_code(&mut self) {
        let b = self.src.as_bytes();
        let start = self.pos;
        let mut n = 0;
        while self.pos < b.len() && b[self.pos] == b'`' {
            n += 1;
            self.pos += 1;
        }
        let after_open = self.pos;
        let mut i = after_open;
        while i < b.len() {
            if b[i] == b'`' {
                let s = i;
                let mut m = 0;
                while i < b.len() && b[i] == b'`' {
                    m += 1;
                    i += 1;
                }
                if m == n {
                    let mut content = self.src[after_open..s].replace('\n', " ");
                    if content.len() >= 2 && content.starts_with(' ') && content.ends_with(' ') && !content.chars().all(|c| c == ' ') {
                        content = content[1..content.len() - 1].to_string();
                    }
                    self.toks.push(Tok::Node(Inline::Code(content)));
                    self.pos = i;
                    return;
                }
            } else {
                i += 1;
            }
        }
        // no match: literal backticks
        let s = self.src[start..after_open].to_string();
        self.push_text(&s);
    }

    fn parse_autolink_or_html(&mut self) -> bool {
        let rest = &self.src[self.pos..];
        // URI autolink
        if let Some(end) = rest.find('>') {
            let inner = &rest[1..end];
            if !inner.contains(' ') && !inner.contains('<') && !inner.contains('\n') {
                if let Some(colon) = inner.find(':') {
                    let scheme = &inner[..colon];
                    if scheme.len() >= 2
                        && scheme.len() <= 32
                        && scheme.chars().next().unwrap().is_ascii_alphabetic()
                        && scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '.' || c == '-')
                        && !inner.chars().any(|c| c.is_control())
                    {
                        let url = inner.to_string();
                        self.toks.push(Tok::Node(Inline::Link {
                            url: url.clone(),
                            title: None,
                            children: vec![Inline::Text(url)],
                        }));
                        self.pos += end + 1;
                        return true;
                    }
                }
                // email
                if let Some(at) = inner.find('@') {
                    let (local, domain) = (&inner[..at], &inner[at + 1..]);
                    let local_ok = !local.is_empty() && local.chars().all(|c| c.is_ascii_alphanumeric() || ".!#$%&'*+/=?^_`{|}~-".contains(c));
                    let domain_ok = !domain.is_empty()
                        && domain.split('.').all(|l| {
                            !l.is_empty() && l.len() <= 63 && l.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') && !l.starts_with('-') && !l.ends_with('-')
                        });
                    if local_ok && domain_ok {
                        self.toks.push(Tok::Node(Inline::Link {
                            url: format!("mailto:{inner}"),
                            title: None,
                            children: vec![Inline::Text(inner.to_string())],
                        }));
                        self.pos += end + 1;
                        return true;
                    }
                }
            }
        }
        if let Some(n) = match_html_tag(rest) {
            self.toks.push(Tok::Node(Inline::Html));
            self.pos += n;
            return true;
        }
        false
    }

    fn char_before(&self, pos: usize) -> Option<char> {
        if pos == 0 {
            None
        } else {
            self.src[..pos].chars().next_back()
        }
    }

    fn parse_delim_run(&mut self, ch: char) {
        let b = self.src.as_bytes();
        let start = self.pos;
        let mut n = 0;
        while self.pos < b.len() && b[self.pos] as char == ch {
            n += 1;
            self.pos += 1;
        }
        let before = self.char_before(start).unwrap_or('\n');
        let after = self.src[self.pos..].chars().next().unwrap_or('\n');
        let after_ws = after.is_whitespace();
        let before_ws = before.is_whitespace();
        let after_p = is_punct(after);
        let before_p = is_punct(before);
        let left = !after_ws && (!after_p || before_ws || before_p);
        let right = !before_ws && (!before_p || after_ws || after_p);
        let (can_open, can_close) = if ch == '_' {
            (left && (!right || before_p), right && (!left || after_p))
        } else {
            (left, right)
        };
        self.toks.push(Tok::DelimText(std::iter::repeat(ch).take(n).collect()));
        let p = self.toks.len() - 1;
        self.delims.push(Delim { pos: p, ch, count: n, orig_count: n, can_open, can_close, active: true });
    }

    fn parse_close_bracket(&mut self) {
        self.pos += 1;
        let bracket = match self.brackets.pop() {
            Some(b) => b,
            None => {
                self.push_text("]");
                return;
            }
        };
        if !bracket.active {
            self.push_text("]");
            return;
        }
        let label_text = &self.src[bracket.text_start..self.pos - 1];
        let after = self.pos;
        let mut result: Option<(String, Option<String>, usize)> = None;
        // inline link
        if self.src.as_bytes().get(after) == Some(&b'(') {
            let s = self.src;
            let mut i = skip_spaces_one_newline_all(s, after + 1);
            let dest;
            if let Some((j, d)) = scan_link_destination(s, i) {
                dest = Some(d);
                i = j;
            } else if s.as_bytes().get(i) == Some(&b')') {
                dest = Some(String::new());
            } else {
                dest = None;
            }
            if let Some(d) = dest {
                let k = skip_spaces_one_newline_all(s, i);
                let mut title = None;
                let mut m = k;
                if k > i {
                    if let Some((t_end, t)) = scan_link_title(s, k) {
                        title = Some(t);
                        m = skip_spaces_one_newline_all(s, t_end);
                    }
                }
                if s.as_bytes().get(m) == Some(&b')') {
                    result = Some((d, title, m + 1));
                }
            }
        }
        if result.is_none() {
            // reference link
            let s = self.src;
            let mut consumed = after;
            let mut key: Option<String> = None;
            if s.as_bytes().get(after) == Some(&b'[') {
                if let Some((len, lbl)) = scan_link_label(&s[after..]) {
                    key = Some(lbl);
                    consumed = after + len;
                } else if s[after..].starts_with("[]") {
                    key = Some(label_text.to_string());
                    consumed = after + 2;
                }
            }
            let key_s = key.clone().unwrap_or_else(|| label_text.to_string());
            if let Some((url, title)) = self.refs.get(&normalize_label(&key_s)) {
                result = Some((url.clone(), title.clone(), if key.is_some() { consumed } else { after }));
            }
        }
        match result {
            Some((url, title, newpos)) => {
                self.pos = newpos;
                // process emphasis inside
                self.process_emphasis(bracket.delim_bottom);
                let children_toks: Vec<Tok> = self.toks.drain(bracket.pos + 1..).collect();
                self.toks.pop(); // the bracket opener
                let children = toks_to_inlines(children_toks);
                let node = if bracket.image {
                    Inline::Image { url, title, children }
                } else {
                    Inline::Link { url, title, children }
                };
                self.toks.push(Tok::Node(node));
                self.toks.push(Tok::Node(Inline::Text(String::new())));
                if !bracket.image {
                    for b in self.brackets.iter_mut() {
                        if !b.image {
                            b.active = false;
                        }
                    }
                }
            }
            None => {
                self.push_text("]");
            }
        }
    }

    fn process_emphasis(&mut self, bottom: usize) {
        let mut closer_idx = bottom;
        let mut openers_bottom: HashMap<(char, bool, usize), usize> = HashMap::new();
        while closer_idx < self.delims.len() {
            if !self.delims[closer_idx].can_close || !self.delims[closer_idx].active {
                closer_idx += 1;
                continue;
            }
            let ch = self.delims[closer_idx].ch;
            let key = (ch, self.delims[closer_idx].can_open, self.delims[closer_idx].orig_count % 3);
            let lower = *openers_bottom.get(&key).unwrap_or(&bottom);
            let mut opener_idx: Option<usize> = None;
            let mut j = closer_idx;
            while j > lower {
                j -= 1;
                let d = &self.delims[j];
                if d.active && d.ch == ch && d.can_open && d.count > 0 {
                    let c = &self.delims[closer_idx];
                    let odd = (d.can_close || c.can_open) && (d.orig_count + c.orig_count) % 3 == 0 && !(d.orig_count % 3 == 0 && c.orig_count % 3 == 0);
                    if !odd {
                        opener_idx = Some(j);
                        break;
                    }
                }
            }
            match opener_idx {
                Some(oi) => {
                    let use_n = if self.delims[closer_idx].count >= 2 && self.delims[oi].count >= 2 { 2 } else { 1 };
                    self.delims[oi].count -= use_n;
                    self.delims[closer_idx].count -= use_n;
                    let opos = self.delims[oi].pos;
                    let cpos = self.delims[closer_idx].pos;
                    // update texts
                    if let Tok::DelimText(t) = &mut self.toks[opos] {
                        let l = t.len() - use_n;
                        t.truncate(l);
                    }
                    if let Tok::DelimText(t) = &mut self.toks[cpos] {
                        let l = t.len() - use_n;
                        t.truncate(l);
                    }
                    // wrap tokens between opos and cpos
                    let inner: Vec<Tok> = self.toks.drain(opos + 1..cpos).collect();
                    let removed = inner.len();
                    let children = toks_to_inlines(inner);
                    let node = if use_n == 2 { Inline::Strong(children) } else { Inline::Emph(children) };
                    self.toks.insert(opos + 1, Tok::Node(node));
                    let shift = removed as isize - 1;
                    // fix positions of delims after
                    for d in self.delims.iter_mut() {
                        if d.pos > opos {
                            if d.pos >= cpos {
                                d.pos = (d.pos as isize - shift) as usize;
                            }
                        }
                    }
                    for b in self.brackets.iter_mut() {
                        if b.pos > opos && b.pos >= cpos {
                            b.pos = (b.pos as isize - shift) as usize;
                        }
                    }
                    // deactivate delimiters between opener and closer
                    for k in oi + 1..closer_idx {
                        self.delims[k].active = false;
                    }
                    if self.delims[oi].count == 0 {
                        self.delims[oi].active = false;
                    }
                    if self.delims[closer_idx].count == 0 {
                        self.delims[closer_idx].active = false;
                        closer_idx += 1;
                    }
                }
                None => {
                    openers_bottom.insert(key, closer_idx);
                    if !self.delims[closer_idx].can_open {
                        self.delims[closer_idx].active = false;
                    }
                    closer_idx += 1;
                }
            }
        }
        // remove all delimiters above bottom
        self.delims.truncate(bottom);
    }
}

fn skip_spaces_one_newline_all(s: &str, mut i: usize) -> usize {
    let b = s.as_bytes();
    while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
        i += 1;
    }
    i
}

fn toks_to_inlines(toks: Vec<Tok>) -> Vec<Inline> {
    let mut out: Vec<Inline> = Vec::new();
    for t in toks {
        let node = match t {
            Tok::Node(n) => n,
            Tok::DelimText(s) => Inline::Text(s),
        };
        if let Inline::Text(s) = &node {
            if s.is_empty() {
                continue;
            }
            if let Some(Inline::Text(prev)) = out.last_mut() {
                prev.push_str(s);
                continue;
            }
        }
        out.push(node);
    }
    out
}

fn parse_inlines(src: &str, refs: &HashMap<String, (String, Option<String>)>) -> Vec<Inline> {
    let src = src.trim_end_matches(['\n', ' ', '\t']);
    let src = src.trim_start_matches([' ', '\t']);
    let mut p = InlineParser { src, pos: 0, toks: Vec::new(), delims: Vec::new(), brackets: Vec::new(), refs };
    p.parse();
    p.process_emphasis(0);
    toks_to_inlines(p.toks)
}

fn plain_text(nodes: &[Inline], out: &mut String) {
    for n in nodes {
        match n {
            Inline::Text(t) => out.push_str(t),
            Inline::Code(c) => out.push_str(c),
            Inline::SoftBreak | Inline::HardBreak => out.push('\n'),
            Inline::Emph(c) | Inline::Strong(c) => plain_text(c, out),
            Inline::Link { children, .. } | Inline::Image { children, .. } => plain_text(children, out),
            Inline::Html => {}
        }
    }
}

fn render_inlines(nodes: &[Inline], out: &mut String) {
    for n in nodes {
        match n {
            Inline::Text(t) => out.push_str(&escape_html(t)),
            Inline::Code(c) => {
                out.push_str("<code>");
                out.push_str(&escape_html(c));
                out.push_str("</code>");
            }
            Inline::Html => out.push_str("<!-- raw HTML omitted -->"),
            Inline::SoftBreak => out.push('\n'),
            Inline::HardBreak => out.push_str("<br />\n"),
            Inline::Emph(c) => {
                out.push_str("<em>");
                render_inlines(c, out);
                out.push_str("</em>");
            }
            Inline::Strong(c) => {
                out.push_str("<strong>");
                render_inlines(c, out);
                out.push_str("</strong>");
            }
            Inline::Link { url, title, children } => {
                out.push_str("<a href=\"");
                if !is_dangerous_url(url, false) {
                    out.push_str(&escape_href(url));
                }
                out.push('"');
                if let Some(t) = title {
                    out.push_str(" title=\"");
                    out.push_str(&escape_html(t));
                    out.push('"');
                }
                out.push('>');
                render_inlines(children, out);
                out.push_str("</a>");
            }
            Inline::Image { url, title, children } => {
                out.push_str("<img src=\"");
                if !is_dangerous_url(url, true) {
                    out.push_str(&escape_href(url));
                }
                out.push_str("\" alt=\"");
                let mut alt = String::new();
                plain_text(children, &mut alt);
                out.push_str(&escape_html(&alt));
                out.push('"');
                if let Some(t) = title {
                    out.push_str(" title=\"");
                    out.push_str(&escape_html(t));
                    out.push('"');
                }
                out.push_str(" />");
            }
        }
    }
}

// ---------------------------------------------------------------------------
// HTML output
// ---------------------------------------------------------------------------

fn render_block(p: &Parser, n: usize, tight: bool, out: &mut String) {
    let node = &p.nodes[n];
    match &node.kind {
        Kind::Document => {
            for &c in &node.children {
                render_block(p, c, false, out);
            }
        }
        Kind::BlockQuote => {
            out.push_str("<blockquote>\n");
            for &c in &node.children {
                render_block(p, c, false, out);
            }
            out.push_str("</blockquote>\n");
        }
        Kind::List(ld) => {
            if ld.ordered {
                if ld.start != 1 {
                    out.push_str(&format!("<ol start=\"{}\">\n", ld.start));
                } else {
                    out.push_str("<ol>\n");
                }
            } else {
                out.push_str("<ul>\n");
            }
            for &c in &node.children {
                render_block(p, c, ld.tight, out);
            }
            out.push_str(if ld.ordered { "</ol>\n" } else { "</ul>\n" });
        }
        Kind::Item(_) => {
            out.push_str("<li>");
            let children = &node.children;
            for (i, &c) in children.iter().enumerate() {
                let is_para = matches!(p.nodes[c].kind, Kind::Paragraph);
                if !(tight && is_para) && (i == 0 || !out.ends_with('\n')) {
                    if !out.ends_with('\n') {
                        out.push('\n');
                    }
                }
                render_block(p, c, tight, out);
                if tight && is_para && i + 1 < children.len() {
                    out.push('\n');
                }
            }
            out.push_str("</li>\n");
        }
        Kind::Paragraph => {
            if node.content.trim().is_empty() {
                return;
            }
            let inl = parse_inlines(&node.content, &p.refs);
            if tight {
                render_inlines(&inl, out);
            } else {
                out.push_str("<p>");
                render_inlines(&inl, out);
                out.push_str("</p>\n");
            }
        }
        Kind::Heading(lvl, _) => {
            let inl = parse_inlines(&node.content, &p.refs);
            out.push_str(&format!("<h{lvl}>"));
            render_inlines(&inl, out);
            out.push_str(&format!("</h{lvl}>\n"));
        }
        Kind::ThematicBreak => out.push_str("<hr />\n"),
        Kind::CodeBlock { info, .. } => {
            let lang = info.split_whitespace().next().unwrap_or("");
            if lang.is_empty() {
                out.push_str("<pre><code>");
            } else {
                out.push_str(&format!("<pre><code class=\"language-{}\">", escape_html(lang)));
            }
            out.push_str(&escape_html(&node.content));
            out.push_str("</code></pre>\n");
        }
        Kind::HtmlBlock(_) => out.push_str("<!-- raw HTML omitted -->\n"),
    }
}

pub fn markdown_to_html(src: &str) -> String {
    let mut p = Parser::new();
    let text = src.replace("\r\n", "\n").replace('\r', "\n").replace('\0', "\u{fffd}");
    let mut lines: Vec<&str> = text.split('\n').collect();
    if text.ends_with('\n') {
        lines.pop();
    }
    for l in lines {
        let mut line = l.to_string();
        line.push('\n');
        p.incorporate_line(&line);
    }
    while p.tip != 0 {
        let t = p.tip;
        p.finalize(t);
    }
    p.finalize(0);
    let mut out = String::new();
    render_block(&p, 0, false, &mut out);
    out
}
