pub struct Pool {
    inner: Arc<(std::sync::Mutex<PoolState>, std::sync::Condvar)>,
}

struct PoolState {
    jobs: std::collections::VecDeque<Job>,
    idle: usize,
}

impl Pool {
    pub fn new(initial: usize) -> Pool {
        let inner = Arc::new((std::sync::Mutex::new(PoolState { jobs: Default::default(), idle: 0 }), std::sync::Condvar::new()));
        let p = Pool { inner };
        for _ in 0..initial {
            p.spawn_worker();
        }
        p
    }

    fn spawn_worker(&self) {
        let inner = self.inner.clone();
        {
            let mut st = inner.0.lock().unwrap();
            st.idle += 1;
        }
        let _ = std::thread::Builder::new().stack_size(4 << 20).spawn(move || loop {
            let job = {
                let mut st = inner.0.lock().unwrap();
                loop {
                    if let Some(j) = st.jobs.pop_front() {
                        st.idle -= 1;
                        break j;
                    }
                    st = inner.1.wait(st).unwrap();
                }
            };
            job();
            let mut st = inner.0.lock().unwrap();
            st.idle += 1;
        });
    }

    pub fn execute(&self, job: Job) {
        let need_spawn = {
            let mut st = self.inner.0.lock().unwrap();
            st.jobs.push_back(job);
            st.idle < st.jobs.len()
        };
        if need_spawn {
            self.spawn_worker();
        }
        self.inner.1.notify_one();
    }
}

pub fn serve_listener(listener: TcpListener, handler: Arc<dyn Handler>, tls: Option<Arc<TlsAcceptor>>, opts: Arc<ServerOptions>, pool: Arc<Pool>) {
