                continue;
            }
        };
        let handler = handler.clone();
        let tls = tls.clone();
        let opts = opts.clone();
        pool.execute(Box::new(move || {
            let peer = match stream.peer_addr() {
                Ok(p) => p,
                Err(_) => return,
            };
